-- Private H activation policy; never rewrites saved G rules or committed effects.
create or replace function ml_private.p3h_active_blocker(s jsonb,a integer) returns integer language sql stable set search_path=pg_catalog,ml_private as $$
 select (p.v->>'seat')::int from jsonb_array_elements(s->'players') with ordinality p(v,n)
 where s->>'version'='web-v0.1.19' and ml_private.stage4_on_board(s,a)
 and p.v->>'character'='character-011' and (p.v->>'seat')::int<>a and ml_private.stage4_on_board(s,(p.v->>'seat')::int)
 and (s->>'mode' is distinct from 'team' or p.v->>'team' is distinct from s#>>array['players',a::text,'team'])
 and (ml_private.version_catalog(s->>'version')#>'{mapDefinition,map}'->(p.v->>'cell')->>'region')=(ml_private.version_catalog(s->>'version')#>'{mapDefinition,map}'->(s#>>array['players',a::text,'cell'])->>'region')
 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',(p.v->>'seat')::int,'roleModifiers','[]'::jsonb),a,s#>>array['players',a::text,'character'])
 order by p.n limit 1
$$;
create or replace function ml_private.p3h_active_allowed(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_active_blocker(s,a) is null$$;
create or replace function ml_private.p3h_active_choice(kind text) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select kind in ('h-small','h-respect','h-ren-expel','east-start','qb-pursuit','xie-ledger','west-carry','lemon-support','runner-roll','runner-pay','encourage','egg-move','f-self-harm','f-sting','primitive-food','g-invisible')$$;
create or replace function ml_private.p3h_active_skill(kind text) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select kind in ('ren','freeze','dog','execute','magma','gas','escape','clan','feather','mayi','jj','cooperate','circle')$$;
create or replace function ml_private.p3h_prime_active(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3g_prime(s,a) and ml_private.p3h_active_allowed(s,a)$$;
-- H first tranche. Private v19 harness only; no release migration or production execution.
create or replace function ml_private.p3h_choice_label(kind text) returns text language sql immutable set search_path=pg_catalog,ml_private as $$select case kind when 'h-equip-draw' then '装备哥：成功安装后摸1' when 'h-small' then '小：跨过角色判定' when 'h-birth' then '世界是多元的：选择出生格' when 'h-respect' then 'respect：选择驱逐落点' when 'h-ren-retreat' then '做自己喜欢的教育' when 'h-ren-back' then '教育：选择后退方向' when 'h-ren-expel' then '厌蠢：选择移出地区' when 'h-ren-gear' then '化学金牌教练：选择装备替换' when 'h-cooperate' then '南南合作：选择等量交换手牌' when 'h-circle-pay' then '画圆：支付1AP越界' when 'h-attract' then '组织部部长' when 'h-reroll' then '狂叫' when 'h-six' then '6：免费摸牌' else kind end$$;
create or replace function ml_private.p3h_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select s->>'version'='web-v0.1.19'$$;
create or replace function ml_private.p3h_initial_state() returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$select '{"frozenBy":[null,null,null,null],"freezeReadyAt":[0,0,0,0],"lowest":[false,false,false,false],"pendingTurns":[],"extraReturn":null,"rerollRoots":{},"circles":[],"circleUsed":[false,false,false,false],"circlePermissions":{}}'::jsonb$$;
create or replace function ml_private.p3h_observe_hp(s jsonb,initial boolean default false) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare q jsonb;a integer;minhp integer;low boolean;begin
 if not ml_private.p3h_enabled(s) then return s;end if;select min((v->>'hp')::int) into minhp from ml_private.arr(s->'players') v where (v->>'hp')::int>0;
 for q in select * from ml_private.arr(s->'players') loop a:=(q->>'seat')::int;low:=(q->>'hp')::int>0 and (q->>'hp')::int=minhp;
 if not initial and q->>'character'='character-015' and low and s#>>array['stage3','h','lowest',a::text]='false' and a<>(s->>'active')::int and not(s#>'{stage3,h,pendingTurns}' @> jsonb_build_array(a)) then s:=jsonb_set(s,'{stage3,h,pendingTurns}',(s#>'{stage3,h,pendingTurns}')||jsonb_build_array(a));end if;s:=jsonb_set(s,array['stage3','h','lowest',a::text],to_jsonb(coalesce(low,false)));end loop;return s;end $$;
create or replace function ml_private.p3h_freeze_targets(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,n) where ml_private.p3h_enabled(s) and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-039' and (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>array['stage3','h','frozenBy',v#>>'{}']='null'::jsonb and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),(v#>>'{}')::int,s#>>array['players',v#>>'{}','character'])$$;
create or replace function ml_private.p3h_freeze_action(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare targets jsonb:=ml_private.p3h_freeze_targets(s,a);remaining integer:=case when ml_private.p3h_enabled(s) then greatest(0,(s#>>array['stage3','h','freezeReadyAt',a::text])::int-(s#>>array['stage3','starts',a::text])::int) else 0 end;begin return jsonb_build_object('available',s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and (s#>>array['players',a::text,'ap'])::int>=2 and remaining=0 and jsonb_array_length(targets)>0,'remaining',remaining,'targets',targets);end $$;
create or replace function ml_private.p3h_freeze(s jsonb,a integer,target integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$begin
 perform ml_private.need(ml_private.p3h_enabled(s) and ml_private.p3h_freeze_action(s,a)->>'available'='true' and ml_private.p3h_freeze_targets(s,a) @> jsonb_build_array(target),'冰封之力次数、角色或目标不合法');s:=ml_private.p3d_pay(s,a,2);s:=jsonb_set(s,array['stage3','h','freezeReadyAt',a::text],to_jsonb((s#>>array['stage3','starts',a::text])::int+2));s:=jsonb_set(s,array['stage3','h','frozenBy',target::text],to_jsonb(a));return ml_private.emit(s,'skill','S'||(a+1)||' 冰封之力支付2AP，S'||(target+1)||'下次个人回合跳过自由行动');end $$;
create or replace function ml_private.p3h_take_extra(s jsonb,continuation jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer;candidate jsonb;pending jsonb;begin
 if not ml_private.p3h_enabled(s) or s#>'{stage3,h,extraReturn}'<>'null'::jsonb then return s||jsonb_build_object('_hExtraTaken',false);end if;pending:=s#>'{stage3,h,pendingTurns}';
 while jsonb_array_length(pending)>0 loop candidate:=pending->0;pending:=pending-0;if (s#>>array['players',candidate#>>'{}','hp'])::int>0 then a:=(candidate#>>'{}')::int;exit;end if;end loop;s:=jsonb_set(s,'{stage3,h,pendingTurns}',pending);if a is null then return s||jsonb_build_object('_hExtraTaken',false);end if;
 s:=jsonb_set(s,'{stage3,h,extraReturn}',jsonb_build_object('cursor',s->'cursor','queue',continuation));s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',a)));s:=ml_private.emit(s,'skill','S'||(a+1)||' 拖动进度条：插入个人回合，整轮不变');return s||jsonb_build_object('_hExtraTaken',true);end $$;
create or replace function ml_private.p3h_return_extra(s jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare saved jsonb:=s#>'{stage3,h,extraReturn}';begin
 if not ml_private.p3h_enabled(s) or saved='null'::jsonb then return s||jsonb_build_object('_hExtraReturned',false);end if;s:=jsonb_set(s,'{stage3,h,extraReturn}','null');s:=s||jsonb_build_object('cursor',saved->'cursor','queue',saved->'queue');s:=ml_private.p3h_take_extra(s,s->'queue');return (s-'_hExtraTaken')||jsonb_build_object('_hExtraReturned',true);end $$;
create or replace function ml_private.p3h_should_yield(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_enabled(s) and s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->'movement'='null'::jsonb and s#>'{cardStack,stack}'='[]'::jsonb and s#>'{stage4,interruptTurn}'='null'::jsonb and s#>'{stage3,h,extraReturn}'='null'::jsonb and exists(select 1 from ml_private.arr(s#>'{stage3,h,pendingTurns}') v where (s#>>array['players',v#>>'{}','hp'])::int>0 and v<>s->'active')$$;
create or replace function ml_private.p3h_start_tasks(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(ml_private.stage3_task('h-attract',jsonb_build_object('actor',a,'target',v,'data',jsonb_build_object('base',s#>array['players',a::text,'cell'],'root','h-start'||(s#>>'{stage3,turn}')))) order by n),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,n) where ml_private.p3h_enabled(s) and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-001' and v<>to_jsonb(a) and ml_private.stage4_on_board(s,(v#>>'{}')::int) and not(s#>>array['players',v#>>'{}','character']='character-027' and jsonb_array_length(s#>array['players',v#>>'{}','hand'])=1) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',a,'roleModifiers','[]'::jsonb),(v#>>'{}')::int,s#>>array['players',v#>>'{}','character'])$$;
create or replace function ml_private.p3h_attract_cells(s jsonb,a integer,target integer,base text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare result jsonb:='[]';direction text;cell text;actual text;before integer;begin
 if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or a=target or s#>>array['players',target::text,'character']='character-027' and jsonb_array_length(s#>array['players',target::text,'hand'])=1 or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then return result;end if;
 before:=ml_private.distance_for_version(s->>'version',s#>>array['players',target::text,'cell'],base);foreach direction in array array['up','right','down','left'] loop cell:=ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],direction);if cell is not null and ml_private.stage4_board_empty(s,target,cell,jsonb_build_array(target)) and ml_private.stage3_can_enter(s,target,cell) then actual:=ml_private.playtest_relocation_cell(s,target,s#>>array['players',target::text,'cell'],cell);if actual is not null and ml_private.distance_for_version(s->>'version',actual,base)<before then result:=result||jsonb_build_array(cell);end if;end if;end loop;return result;end $$;
create or replace function ml_private.p3h_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;d jsonb:=t->'data';cells jsonb;gate jsonb;begin
 if not ml_private.p3h_enabled(s) or t->>'action'<>'h-attract' then return s||jsonb_build_object('_hHandled',false);end if;s:=jsonb_set(s,'{stage3,e,current}',d->'root');cells:=ml_private.p3h_attract_cells(s,a,target,d->>'base');if jsonb_array_length(cells)>0 then gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),d->>'root');if gate is not null then s:=ml_private.stage3_prepend(s,gate);else s:=ml_private.select_choice(s,'h-attract',a,at,jsonb_build_object('source',target,'cells',cells,'data',d));end if;end if;return s||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;target integer:=(c->>'source')::int;d jsonb:=c->'data';cells jsonb;cell text;begin
 if not ml_private.p3h_enabled(s) or c->>'kind'<>'h-attract' then return s||jsonb_build_object('_hHandled',false);end if;s:=jsonb_set(s,'{stage3,e,current}',d->'root');cells:=ml_private.p3h_attract_cells(s,a,target,d->>'base');cell:=case when timeout then cells->>0 else cmd->>'cell' end;if cell is null then perform ml_private.need(jsonb_array_length(cells)=0,'请选择组织部部长合法方向');else perform ml_private.need(c->'cells' ? cell and cells ? cell,'组织部部长落点已失效');s:=s||jsonb_build_object('_eCause',jsonb_build_object('source',a,'root',d->'root'));s:=ml_private.stage3_relocate(s,target,cell,false,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks')-'_relocationTasks';end if;return s||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_reroll_key(s jsonb,owner integer) returns text language sql immutable set search_path=pg_catalog,ml_private as $$select owner::text||':'||regexp_replace(ml_private.p3e_root(s),'^(revision|move)([0-9]+)$','action\2')$$;
create or replace function ml_private.p3h_can_reroll(s jsonb,owner integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_enabled(s) and owner is not null and ml_private.p3h_active_allowed(s,owner) and ml_private.stage4_on_board(s,owner) and s#>>array['players',owner::text,'character']='character-015' and not coalesce((s#>>array['stage3','h','rerollRoots',ml_private.p3h_reroll_key(s,owner)])::boolean,false)$$;
create or replace function ml_private.p3h_six_actor(s jsonb,owner integer,value integer) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (v#>>'{}')::int from jsonb_array_elements(s->'order') with ordinality q(v,n) where ml_private.p3h_enabled(s) and owner is not null and value=6 and ml_private.p3h_active_allowed(s,(v#>>'{}')::int) and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>>array['players',v#>>'{}','character']='character-001' order by n limit 1$$;
-- H N-13 private effect view: never duplicate equipment entities or zones.
create or replace function ml_private.p3h_gear_shared(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_enabled(s) and s->>'mode'='team' and a between 0 and 3 and exists(select 1 from ml_private.arr(s->'players') q where q->>'character'='character-050' and (q->>'hp')::int>0 and q->'team'=s#>array['players',a::text,'team'])$$;
create or replace function ml_private.p3h_gear_cards(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(s#>array['stage3','equipment',a::text],'[]')||case when ml_private.p3h_gear_shared(s,a) then (select coalesce(jsonb_agg(card order by ord,n),'[]') from jsonb_array_elements(s->'players') with ordinality p(q,ord) cross join lateral jsonb_array_elements(s#>array['stage3','equipment',q->>'seat']) with ordinality g(card,n) where (q->>'seat')::int<>a and (q->>'hp')::int>0 and q->'team'=s#>array['players',a::text,'team']) else '[]'::jsonb end$$;
create or replace function ml_private.p3h_gear_owner(s jsonb,card text) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (q->>'seat')::int from ml_private.arr(s->'players') q where s#>array['stage3','equipment',q->>'seat'] ? card limit 1$$;
create or replace function ml_private.p3h_gear_source(s jsonb,a integer,card text) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select (s#>array['stage3','equipmentSources',card])||case when ml_private.p3h_enabled(s) and ml_private.p3h_gear_owner(s,card) is distinct from a then jsonb_build_object('actor',a,'faction',s#>array['players',a::text,'faction']) else '{}'::jsonb end$$;
create or replace function ml_private.p3h_gear_starts(s jsonb,a integer,card text) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (s#>>array['stage3','starts',case when ml_private.p3h_enabled(s) then coalesce(ml_private.p3h_gear_owner(s,card),a)::text else a::text end])::int$$;
create or replace function ml_private.p3h_gear_watch(s jsonb,a integer,card text) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when not ml_private.p3h_enabled(s) or ml_private.p3h_gear_owner(s,card)=a then s#>array['stage4','watches',card] when s#>array['stage3','h','sharedWatches',card,a::text] is not null and s#>array['stage4','watches',card] is not null then (s#>array['stage3','h','sharedWatches',card,a::text])||jsonb_build_object('usedTurn',s#>array['stage4','watches',card,'usedTurn']) else null end$$;
create or replace function ml_private.p3h_gear_watch_start(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare card text;old jsonb;begin
 if not ml_private.p3h_gear_shared(s,a) then return s;end if;
 for card in select v#>>'{}' from ml_private.arr(ml_private.p3h_gear_cards(s,a)) v loop if ml_private.p3h_gear_owner(s,card)<>a and ml_private.stage4_equipment_definition(s,card)='basic-060' then
  old:=s#>array['stage3','h','sharedWatches',card,a::text];s:=jsonb_set(s,'{stage3,h,sharedWatches}',coalesce(s#>'{stage3,h,sharedWatches}','{}'));s:=jsonb_set(s,array['stage3','h','sharedWatches',card],coalesce(s#>array['stage3','h','sharedWatches',card],'{}'));
  s:=jsonb_set(s,array['stage3','h','sharedWatches',card,a::text],jsonb_build_object('current',s#>array['players',a::text,'cell'],'previous',old->'current'));
 end if;end loop;return s;
end $$;
create or replace function ml_private.p3h_gear_forget(s jsonb,card text) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3h_enabled(s) and s#>'{stage3,h,sharedWatches}' is not null then s#-array['stage3','h','sharedWatches',card] else s end$$;
create or replace function ml_private.p3h_gear_refresh(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer;card text;u text;begin if not ml_private.p3h_enabled(s) or not exists(select 1 from ml_private.arr(s->'players') q where q->>'character'='character-050') then return s;end if;
 for card in select jsonb_object_keys(coalesce(s#>'{stage3,h,sharedWatches}','{}')) loop
  for u in select jsonb_object_keys(s#>array['stage3','h','sharedWatches',card]) loop if not(ml_private.p3h_gear_cards(s,u::int) ? card) or ml_private.p3h_gear_owner(s,card)=u::int then s:=s#-array['stage3','h','sharedWatches',card,u];end if;end loop;
  if s#>array['stage3','h','sharedWatches',card]='{}' then s:=s#-array['stage3','h','sharedWatches',card];end if;
 end loop;
 for a in 0..3 loop s:=ml_private.stage4_gear_movement(s,a);s:=ml_private.p3g_terrain_refresh(s,a);end loop;return s;end $$;
create or replace function ml_private.p3h_gear_install_draw(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3h_enabled(s) and s#>>array['players',a::text,'character']='character-050' and (s#>>array['players',a::text,'hp'])::int>0 then ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('h-equip-draw',jsonb_build_object('actor',a)))) else s end$$;
create or replace function ml_private.p3h_gear_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;begin if not ml_private.p3h_enabled(s) or t->>'action'<>'h-equip-draw' then return s||jsonb_build_object('_hHandled',false);end if;if ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-050' then s:=ml_private.select_choice(s,'h-equip-draw',a,at,'{}');end if;return s||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_gear_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(s#>>'{choice,actor}')::int;begin if not ml_private.p3h_enabled(s) or s#>>'{choice,kind}'<>'h-equip-draw' then return s||jsonb_build_object('_hHandled',false);end if;if not timeout and cmd->>'accept'='true' and ml_private.stage4_on_board(s,a) then s:=ml_private.draw(s,a,1);s:=ml_private.emit(s,'skill','S'||(a+1)||' 装备哥：成功安装后摸1');end if;return s||jsonb_build_object('_hHandled',true);end $$;

create or replace function ml_private.p3h_gear_public(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare result jsonb:='[]';cards jsonb;card text;a integer;owner integer;d text;v jsonb;begin if not ml_private.p3h_enabled(s) or not exists(select 1 from ml_private.arr(s->'players') q where q->>'character'='character-050') then return '{}';end if;
 for a in 0..3 loop cards:='[]';for card in select c#>>'{}' from ml_private.arr(ml_private.p3h_gear_cards(s,a)) c loop owner:=ml_private.p3h_gear_owner(s,card);if owner=a then continue;end if;d:=ml_private.stage4_equipment_definition(s,card);v:=jsonb_build_object('card',card,'owner',owner,'definition',d);if s#>array['stage4','durability',card] is not null then v:=v||jsonb_build_object('durability',s#>array['stage4','durability',card]);end if;if d='basic-054' then v:=v||jsonb_build_object('breadRemaining',greatest(0,coalesce((s#>>array['stage3','g','gearBreadReadyAt',card])::int,0)-ml_private.p3h_gear_starts(s,a,card)));end if;cards:=cards||jsonb_build_array(v);end loop;result:=result||jsonb_build_array(cards);end loop;return jsonb_build_object('sharedEquipment',result);
end $$;
-- N-08 private development interpretation. Authority stays in PostgreSQL.
create or replace function ml_private.p3h_circle_start(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare circles jsonb;permissions jsonb;begin
 if not ml_private.p3h_enabled(s) then return s;end if;
 select coalesce(jsonb_agg(c order by n),'[]') into circles from jsonb_array_elements(s#>'{stage3,h,circles}') with ordinality q(c,n) where (c->>'actor')::int<>a and (s#>>array['players',c->>'actor','hp'])::int>0;
 select coalesce(jsonb_object_agg(key,value),'{}') into permissions from jsonb_each(s#>'{stage3,h,circlePermissions}') p where exists(select 1 from ml_private.arr(circles) c where starts_with(p.key,c->>'id'||':'));
 s:=jsonb_set(s,'{stage3,h,circles}',circles);s:=jsonb_set(s,'{stage3,h,circlePermissions}',permissions);return jsonb_set(s,array['stage3','h','circleUsed',a::text],'false');end $$;
create or replace function ml_private.p3h_circle_action(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select jsonb_build_object('available',ml_private.p3h_enabled(s) and s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-011' and s#>>array['stage3','h','circleUsed',a::text]='false' and ml_private.p3h_active_allowed(s,a),'used',case when ml_private.p3h_enabled(s) then s#>array['stage3','h','circleUsed',a::text] else 'false'::jsonb end)$$;
create or replace function ml_private.p3h_circle(s jsonb,a integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare region text:=ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region'];regions jsonb;begin
 perform ml_private.need(ml_private.p3h_circle_action(s,a)->>'available'='true','画圆当前不可发动');
 select coalesce(jsonb_agg(r order by n),'[]') into regions from (select c->>'region' r,min(n) n from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(c,n) group by c->>'region') q where r=region or ml_private.neighbor_for_version(s->>'version',region,r);
 s:=jsonb_set(s,array['stage3','h','circleUsed',a::text],'true');s:=jsonb_set(s,'{stage3,h,circles}',(s#>'{stage3,h,circles}')||jsonb_build_array(jsonb_build_object('id','circle'||(s#>>'{stage3,turn}')||'-'||a,'actor',a,'regions',regions)));
 return ml_private.emit(s,'skill','S'||(a+1)||' 画圆：'||(select string_agg(r,'、' order by n) from jsonb_array_elements_text(regions) with ordinality q(r,n))||'，跨界每条链可付1AP');end $$;
create or replace function ml_private.p3h_circle_line(s jsonb,origin text,destination text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare map jsonb:=ml_private.game_data(s,'map');a jsonb:=map->origin;b jsonb:=map->destination;dr integer;dc integer;i integer;result jsonb:='[]';begin
 if a is null or b is null or a->'row'<>b->'row' and a->'col'<>b->'col' then return jsonb_build_array(destination);end if;dr:=sign((b->>'row')::int-(a->>'row')::int);dc:=sign((b->>'col')::int-(a->>'col')::int);
 for i in 1..ml_private.distance_for_version(s->>'version',origin,destination) loop result:=result||jsonb_build_array('r'||((a->>'row')::int+dr*i)||'c'||((a->>'col')::int+dc*i));end loop;return result;end $$;
create or replace function ml_private.p3h_circle_gate(s jsonb,a integer,destination text,resume jsonb,root text,placement boolean default false,route jsonb default null) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare c jsonb;p jsonb:=s->'players'->a;map jsonb:=ml_private.game_data(s,'map');inside boolean;next_inside boolean;crossed boolean;cell jsonb;key text;permission jsonb;begin
 if not ml_private.p3h_enabled(s) or placement or not ml_private.stage4_on_board(s,a) then return s||jsonb_build_object('_hCircleGate',null);end if;
 for c in select * from ml_private.arr(s#>'{stage3,h,circles}') loop
  if (s#>>array['players',c->>'actor','hp'])::int<=0 or p->>'character'='character-027' and jsonb_array_length(p->'hand')=1 or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',c->'actor','roleModifiers','[]'::jsonb),a,p->>'character') then continue;end if;
  inside:=c->'regions' ? (map->(p->>'cell')->>'region');crossed:=false;
  for cell in select * from ml_private.arr(coalesce(route,jsonb_build_array(destination))) loop next_inside:=coalesce(c->'regions' ? (map->(cell#>>'{}')->>'region'),false);if inside and not next_inside then crossed:=true;end if;inside:=next_inside;end loop;
  if not crossed then continue;end if;key:=(c->>'id')||':'||a||':'||root;permission:=s#>array['stage3','h','circlePermissions',key];if permission='true'::jsonb then continue;end if;if permission='false'::jsonb then return s||jsonb_build_object('_hCircleGate','[]'::jsonb);end if;
  if (p->>'ap')::int<1 then s:=jsonb_set(s,array['stage3','h','circlePermissions',key],'false');return s||jsonb_build_object('_hCircleGate','[]'::jsonb);end if;
  return s||jsonb_build_object('_hCircleGate',jsonb_build_array(ml_private.stage3_task('h-circle-boundary',jsonb_build_object('actor',a,'data',jsonb_build_object('circle',c->'id','source',c->'actor','root',root,'resume',resume)))));
 end loop;return s||jsonb_build_object('_hCircleGate',null);end $$;
create or replace function ml_private.p3h_circle_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare d jsonb:=t->'data';a integer:=(t->>'actor')::int;begin
 if not ml_private.p3h_enabled(s) or t->>'action'<>'h-circle-boundary' then return s||jsonb_build_object('_hHandled',false);end if;
 if ml_private.stage4_on_board(s,a) and exists(select 1 from ml_private.arr(s#>'{stage3,h,circles}') c where c->'id'=d->'circle' and (s#>>array['players',c->>'actor','hp'])::int>0) then s:=ml_private.select_choice(s,'h-circle-pay',a,at,jsonb_build_object('source',d->'source','data',d));else s:=ml_private.stage3_prepend(s,d->'resume');end if;return s||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_circle_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;d jsonb:=c->'data';key text:=(d->>'circle')||':'||a||':'||(d->>'root');accepted boolean:=not timeout and coalesce(cmd->>'accept'='true',false);begin
 if not ml_private.p3h_enabled(s) or c->>'kind'<>'h-circle-pay' then return s||jsonb_build_object('_hHandled',false);end if;
 perform ml_private.need(not accepted or ml_private.stage4_on_board(s,a) and (s#>>array['players',a::text,'ap'])::int>=1,'画圆越界需要1AP');if accepted then s:=ml_private.p3d_pay(s,a,1);end if;
 s:=jsonb_set(s,array['stage3','h','circlePermissions',key],to_jsonb(accepted));s:=jsonb_set(s,'{stage3,e,current}',d->'root');s:=ml_private.stage3_prepend(s,d->'resume');s:=ml_private.emit(s,'skill','S'||(a+1)||' 画圆：'||case when accepted then '支付1AP，允许本条位移链越界' else '拒绝本条位移链越界' end);return s||jsonb_build_object('_hHandled',true);end $$;
-- H030 preparation only. No public entry, runtime catalog activation or migration.
create or replace function ml_private.p3h_link_initial() returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$
 select '{"used":[false,false,false,false],"serial":0,"muted":false,"pending":null,"links":[]}'::jsonb
$$;
create or replace function ml_private.p3h_link_init(s jsonb) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$
 select case when s#>'{stage3,h,cooperation}' is null then jsonb_set(s,'{stage3,h,cooperation}',ml_private.p3h_link_initial()) else s end
$$;
create or replace function ml_private.p3h_cooperate_targets(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,n)
 where ml_private.p3h_enabled(s) and s#>>array['players',a::text,'character']='character-030' and ml_private.stage4_on_board(s,a)
 and jsonb_array_length(s#>array['players',a::text,'hand'])>0 and ml_private.p3h_active_allowed(s,a)
 and (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and jsonb_array_length(s#>array['players',v#>>'{}','hand'])>0
 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),(v#>>'{}')::int,s#>>array['players',v#>>'{}','character'])
$$;
create or replace function ml_private.p3h_cooperate_begin(s jsonb,a integer,target integer,cards jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare id integer;h jsonb;n integer:=jsonb_array_length(cards);begin
 perform ml_private.need(ml_private.p3h_enabled(s),'南南合作仅限H版本');s:=ml_private.p3h_link_init(s);h:=s#>'{stage3,h,cooperation}';
 perform ml_private.need(s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and h#>>array['used',a::text]='false' and h->'pending'='null'::jsonb and ml_private.p3h_cooperate_targets(s,a) @> jsonb_build_array(target),'南南合作次数、角色或目标不合法');
 perform ml_private.need(n>0 and n<=jsonb_array_length(s#>array['players',target::text,'hand']) and n=(select count(distinct v) from ml_private.arr(cards) v) and not exists(select 1 from ml_private.arr(cards) v where not(s#>array['players',a::text,'hand'] @> jsonb_build_array(v))),'请选择双方可等量交换的自己手牌');
 id:=(h->>'serial')::int+1;h:=jsonb_set(h,array['used',a::text],'true')||jsonb_build_object('serial',id,'pending',jsonb_build_object('id',id,'actor',a,'target',target,'cards',cards));s:=jsonb_set(s,'{stage3,h,cooperation}',h);
 return s||jsonb_build_object('_hLinkOffer',jsonb_build_object('source',a,'count',n,'cards',s#>array['players',target::text,'hand'],'data',jsonb_build_object('id',id)));
end $$;
create or replace function ml_private.p3h_cooperate_commit(s jsonb,a integer,id integer,cards jsonb,timeout boolean default false) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare h jsonb;d jsonb;n integer;chosen jsonb;actor integer;hand_a jsonb;hand_b jsonb;links jsonb;begin
 s:=ml_private.p3h_link_init(s);h:=s#>'{stage3,h,cooperation}';d:=h->'pending';
 perform ml_private.need(d<>'null'::jsonb and (d->>'id')::int=id and (d->>'target')::int=a,'南南合作交换已失效');actor:=(d->>'actor')::int;n:=jsonb_array_length(d->'cards');chosen:=cards;
 if timeout then select coalesce(jsonb_agg(v order by v),'[]') into chosen from (select v from ml_private.arr(s#>array['players',a::text,'hand']) v order by v limit n) q;end if;
 perform ml_private.need(ml_private.stage4_on_board(s,actor) and ml_private.stage4_on_board(s,a) and jsonb_array_length(chosen)=n and n=(select count(distinct v) from ml_private.arr(chosen) v) and not exists(select 1 from ml_private.arr(chosen) v where not(s#>array['players',a::text,'hand'] @> jsonb_build_array(v))) and not exists(select 1 from ml_private.arr(d->'cards') v where not(s#>array['players',actor::text,'hand'] @> jsonb_build_array(v))),'南南合作交换手牌已变化');
 select coalesce(jsonb_agg(v order by ord),'[]') into hand_a from jsonb_array_elements(s#>array['players',actor::text,'hand']) with ordinality q(v,ord) where not(d->'cards' @> jsonb_build_array(v));
 select coalesce(jsonb_agg(v order by ord),'[]') into hand_b from jsonb_array_elements(s#>array['players',a::text,'hand']) with ordinality q(v,ord) where not(chosen @> jsonb_build_array(v));
 s:=jsonb_set(jsonb_set(s,array['players',actor::text,'hand'],hand_a||chosen),array['players',a::text,'hand'],hand_b||(d->'cards'));
 select coalesce(jsonb_agg(v order by ord),'[]') into links from jsonb_array_elements(h->'links') with ordinality q(v,ord) where (v->>'actor')::int<>actor;
 h:=h||jsonb_build_object('pending',null,'links',links||jsonb_build_array(jsonb_build_object('actor',actor,'target',a,'untilEnd',(s#>>array['stage3','ends',actor::text])::int+2)));s:=jsonb_set(s,'{stage3,h,cooperation}',h);
 return s||jsonb_build_object('_hLinkResult',jsonb_build_object('actor',actor,'target',a,'count',n));
end $$;
create or replace function ml_private.p3h_cooperate_health(s jsonb,a integer,amount integer,kind text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare h jsonb:=s#>'{stage3,h,cooperation}';l jsonb;target integer;jobs jsonb:='[]';actor integer;begin
 if not ml_private.p3h_enabled(s) or amount<=0 or h is null or h->>'muted'='true' then return jobs;end if;
 for l in select v from ml_private.arr(h->'links') v loop
  actor:=(l->>'actor')::int;if not ml_private.stage4_on_board(s,actor) or s#>>array['stage4','offMap',l->>'target']='true' or (s#>>array['stage3','ends',l->>'actor'])::int>=(l->>'untilEnd')::int then continue;end if;
  target:=case when (l->>'target')::int=a then actor when kind='heal' and actor=a then (l->>'target')::int else null end;
  if target is null or not ml_private.stage4_on_board(s,target) then continue;end if;
  jobs:=jobs||jsonb_build_array(ml_private.stage3_task('h-link-mirror',jsonb_build_object('actor',actor,'target',target,'data',jsonb_build_object('amount',amount,'kind',kind))));
 end loop;return jobs;
end $$;
create or replace function ml_private.p3h_cooperate_start(s jsonb,a integer) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$
 select case when s->>'version'='web-v0.1.19' and s#>'{stage3,h,cooperation}' is not null then jsonb_set(s,array['stage3','h','cooperation','used',a::text],'false') else s end
$$;
create or replace function ml_private.p3h_cooperate_cleanup(s jsonb,deaths boolean default false) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare links jsonb;begin
 if not ml_private.p3h_enabled(s) or s#>'{stage3,h,cooperation}' is null then return s;end if;
 select coalesce(jsonb_agg(v order by n),'[]') into links from jsonb_array_elements(s#>'{stage3,h,cooperation,links}') with ordinality q(v,n)
 where case when deaths then (s#>>array['players',v->>'actor','hp'])::int>0 and (s#>>array['players',v->>'target','hp'])::int>0 else (s#>>array['stage3','ends',v->>'actor'])::int<(v->>'untilEnd')::int end;
 return jsonb_set(s,'{stage3,h,cooperation,links}',links);
end $$;
-- H030 private command integration, never installed by a numbered migration.
create or replace function ml_private.p3h_cooperate_action(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select jsonb_build_object('available',s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and not coalesce((s#>>array['stage3','h','cooperation','used',a::text])::boolean,false) and jsonb_array_length(ml_private.p3h_cooperate_targets(s,a))>0,'used',coalesce((s#>>array['stage3','h','cooperation','used',a::text])::boolean,false),'targets',ml_private.p3h_cooperate_targets(s,a))
$$;
create or replace function ml_private.p3h_cooperate_public(s jsonb) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$
 select case when s#>'{stage3,h,cooperation}' is null then 'null'::jsonb else jsonb_build_object('used',s#>'{stage3,h,cooperation,used}','links',s#>'{stage3,h,cooperation,links}') end
$$;
create or replace function ml_private.p3h_cooperate_skill(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$
declare a integer:=(cmd->>'actor')::int;target integer:=(cmd->>'target')::int;offer jsonb;begin
 s:=ml_private.p3h_cooperate_begin(s,a,target,coalesce(cmd->'cards','[]'));offer:=s->'_hLinkOffer';s:=s-'_hLinkOffer';
 s:=ml_private.emit(s,'skill','S'||(a+1)||' 南南合作：与S'||(target+1)||'交换'||(offer->>'count')||'张手牌，等待对方选牌');return ml_private.select_choice(s,'h-cooperate',target,at,offer);
end $$;
create or replace function ml_private.p3h_cooperate_choose(s jsonb,cmd jsonb,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$
declare result jsonb;begin
 if not ml_private.p3h_enabled(s) or s#>>'{choice,kind}'<>'h-cooperate' then return s||jsonb_build_object('_hHandled',false);end if;
 s:=ml_private.p3h_cooperate_commit(s,(s#>>'{choice,actor}')::int,(s#>>'{choice,data,id}')::int,coalesce(cmd->'cards','[]'),timeout);result:=s->'_hLinkResult';s:=s-'_hLinkResult';
 return ml_private.emit(s,'transfer','S'||((result->>'actor')::int+1)||' 南南合作：与S'||((result->>'target')::int+1)||'交换'||(result->>'count')||'张手牌，建立联系')||jsonb_build_object('_hHandled',true);
end $$;
create or replace function ml_private.p3h_cooperate_heal(s jsonb,a integer,amount integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare jobs jsonb:=ml_private.p3h_cooperate_health(s,a,amount,'heal');idx integer:=0;q jsonb:=s->'queue';head jsonb;tail jsonb;begin
 if jsonb_array_length(jobs)=0 then return s;end if;
 while q->idx->>'action'='h-link-mirror' loop idx:=idx+1;end loop;
 select coalesce(jsonb_agg(v order by n),'[]') into head from jsonb_array_elements(q) with ordinality z(v,n) where n<=idx;
 select coalesce(jsonb_agg(v order by n),'[]') into tail from jsonb_array_elements(q) with ordinality z(v,n) where n>idx;
 return jsonb_set(s,'{queue}',head||jobs||tail);
end $$;
create or replace function ml_private.p3h_cooperate_pending(s jsonb) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$
 select ml_private.p3h_enabled(s) and (coalesce(s#>>'{stage3,h,cooperation,muted}','false')='true' or exists(select 1 from ml_private.arr(s->'queue') t where t->>'action'='h-link-mirror'))
$$;
create or replace function ml_private.p3h_cooperate_task(s jsonb,t jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$
declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;d jsonb:=t->'data';begin
 if not ml_private.p3h_enabled(s) or t->>'action' not in ('h-link-mirror','h-link-done') then return s||jsonb_build_object('_hHandled',false);end if;
 s:=ml_private.p3h_link_init(s)||jsonb_build_object('_hHandled',true);
 if t->>'action'='h-link-done' then return jsonb_set(s,'{stage3,h,cooperation,muted}','false');end if;
 if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then return s;end if;
 perform ml_private.need(s#>>'{stage3,h,cooperation,muted}'='false','南南合作镜像不可递归');s:=jsonb_set(s,'{stage3,h,cooperation,muted}','true');s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('h-link-done','{}')));
 s:=ml_private.emit(s,'skill','S'||(a+1)||' 南南合作：向S'||(target+1)||'同步'||case when d->>'kind'='heal' then '治疗' else '失血' end||(d->>'amount'));
 if d->>'kind'='heal' then return ml_private.heal(s,target,(d->>'amount')::int);end if;
 s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',d->'amount','source',a,'category','response')));return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';
end $$;
