create or replace function ml_private.p3h_window(s jsonb,pending jsonb,w jsonb,kind text,a integer,choice_at double precision,at double precision,cmd jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$begin pending:=jsonb_set(pending,'{waiting}',w);s:=jsonb_set(s,'{stage3,g,dice}',pending);s:=ml_private.select_choice(s,kind,a,choice_at,jsonb_build_object('data',jsonb_build_object('owner',w->'owner','reason',w->'reason','value',w->'value')));s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);return jsonb_build_object('state',s,'ok',true);end $$;
create or replace function ml_private.finish(s jsonb,forced boolean,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare combos jsonb;result_state jsonb;rows jsonb;winners jsonb;last_idx text;result jsonb;tied boolean;begin if ml_private.p3h_cooperate_pending(s) then return s;end if;
 result_state:=ml_private.finish_before_stage3(s,forced,at);if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or result_state->>'phase'='over' then return result_state;end if;
 combos:=ml_private.stage3_combo_teams(s);if jsonb_array_length(combos)=0 then return s;end if;
 result_state:=ml_private.finish_before_stage3(s,true,at);rows:=result_state#>'{result,ranking}';tied:=jsonb_array_length(combos)>1;
 if not tied then
 select jsonb_agg(r order by winning desc,ord) into rows from (select r,ord,combos ? (s#>>array['players',r#>>'{players,0}','team']) winning from jsonb_array_elements(rows) with ordinality t(r,ord)) q;
 select jsonb_agg(r||jsonb_build_object('rank',ord) order by ord) into rows from jsonb_array_elements(rows) with ordinality t(r,ord);
 select jsonb_agg(p->'seat' order by ord) into winners from jsonb_array_elements(s->'players') with ordinality t(p,ord) where combos ? (p->>'team');else winners:='[]';end if;
 result:=jsonb_build_object('reason',case when tied then 'draw' else 'combo' end,'winners',winners,'ranking',rows);last_idx:=(jsonb_array_length(result_state->'events')-1)::text;
 result_state:=jsonb_set(result_state,'{result}',result);result_state:=jsonb_set(result_state,array['events',last_idx,'data'],result);
 return jsonb_set(result_state,array['events',last_idx,'text'],to_jsonb(case when tied then '对局结束：平局' else '对局结束：'||(rows->0->>'label')||' 获胜' end));
end $$;
create or replace function ml_private.resolve_attack(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare attack jsonb:=s->'attack'; d jsonb:=ml_private.rule_card(s,attack->>'card'); hits jsonb:='[]'; targets jsonb; p jsonb; a integer:=(attack->>'actor')::int; t integer; actor integer; roll integer:=0; paid integer; amount integer; before_hp jsonb; triggers jsonb; healing integer:=0; begin
 select coalesce(jsonb_agg(x),'[]') into targets from ml_private.arr(attack->'targets') x where not (attack->'cancelled' @> jsonb_build_array(x));
 if jsonb_array_length(targets)>0 and d->>'id' in ('basic-006','basic-009') then s:=ml_private.p3g_owned_die(s,d->>'name',a); roll:=(s->>'_roll')::int; s:=s-'_roll'; end if;
 for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop p:=s->'players'->t;
  if d ? 'power' then amount:=greatest(0,(d->>'power')::int-(p->>'ap')::int); paid:=least((d->>'power')::int,(p->>'ap')::int); p:=p||jsonb_build_object('ap',(p->>'ap')::int-paid); s:=ml_private.put_player(s,t,p); s:=ml_private.emit(s,'ap',ml_private.name(s,t)||' 被扣'||paid||'AP → '||(p->>'ap')); if amount>0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',amount,'source',a,'category','attack')); end if;
  elsif d->>'id'='basic-008' then
   if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack'));
   else paid:=case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then (p->>'ap')::int else least(2,(p->>'ap')::int) end; s:=ml_private.put_player(s,t,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('ap',(s->'players'->a->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.name(s,a)||' 头锤：从'||ml_private.name(s,t)||'吸收全部'||paid||'AP（目标AP '||paid||'→0）' else ml_private.name(s,a)||' 从'||ml_private.name(s,t)||'吸收'||paid||'AP' end); end if;
  elsif roll>=4 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack')); end if;
 end loop;
 for actor in select ml_private.n(x)::int from ml_private.arr(attack->'elbows') x loop p:=s->'players'->a;
  if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',actor,'category','response'));
  else paid:=least(2,(p->>'ap')::int); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,actor,(s->'players'->actor)||jsonb_build_object('ap',(s->'players'->actor->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',ml_private.name(s,actor)||' 肘击反吸'||paid||'AP'); end if;
 end loop;
 before_hp:=s->'players'; s:=ml_private.damage(s,hits); triggers:=s->'_triggers'; s:=s-'_triggers';
 if d->>'id'='basic-006' and (s->'players'->a->>'hp')::int>0 then for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop healing:=healing+(before_hp->t->>'hp')::int-(s->'players'->t->>'hp')::int; end loop; s:=ml_private.heal(s,a,healing); end if;
 if roll>0 and roll<4 then s:=ml_private.emit(s,'miss',(d->>'name')||' 未命中'); end if;
 return s||jsonb_build_object('queue',triggers||jsonb_build_array(jsonb_build_object('kind','cleanup'))||(s->'queue'));
end $$;
create or replace function ml_private.start_round(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.start_round_legacy(s,at);end if;
 s:=ml_private.pause(s,at);s:=jsonb_set(s,'{phase}','"resolving"');
 s:=jsonb_set(s,'{queue}',(s->'queue')||(select jsonb_agg(jsonb_build_object('kind','water','actor',x)) from ml_private.arr(s->'order') x)||jsonb_build_array(jsonb_build_object('kind','classic-start')));return ml_private.pump(s,at);
end $$;
create or replace function ml_private.next_turn(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then if coalesce(s#>>'{stage4,interruptSkipEnd}','false')<>'true' then s:=ml_private.stage3_turn_end(s,(s->>'active')::int);end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{stage4,interruptSkipEnd}','false');end if;end if;
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.next_turn_legacy(s,at);end if;
 s:=ml_private.pause(s,at);a:=(s->>'active')::int;s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('moved',false,'attacks',0));if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>'{stage4,interruptTurn}'<>'null'::jsonb then a:=(s#>>'{stage4,interruptTurn}')::int;s:=jsonb_set(s,'{stage4,interruptTurn}','null');if ml_private.p3h_enabled(s) then s:=jsonb_set(s,'{stage3,h,extraReturn}','null');end if;s:=s||jsonb_build_object('order',(select jsonb_agg((a+i)%4 order by i) from generate_series(0,3) i),'round',(s->>'round')::int+1,'cursor',0);return ml_private.start_round(s,at);end if;
 s:=ml_private.p3h_return_extra(s);if s->>'_hExtraReturned'='true' then return s-'_hExtraReturned';end if;s:=s-'_hExtraReturned';cursor:=(s->>'cursor')::int+1;
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1;end loop;s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue'));s:=ml_private.p3h_take_extra(s,s->'queue');return s-'_hExtraTaken';end if;
 s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.classic_environment(s);s:=ml_private.emit(s,'environment','第'||(s->>'round')||'轮末，轰炸：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,bombs}') x));s:=ml_private.damage(s,s->'_hits',true);s:=s-'_hits';
 s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','round-next')));return s-'_triggers';
end $$;
create or replace function ml_private.pump(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare t jsonb;a integer;p jsonb;due jsonb;guard integer:=0;allowed boolean;ap integer;countn integer;cells jsonb;cursor integer;kind text;begin at:=ml_private.p3g_now(s,at);s:=ml_private.p3g_at(s,at);
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.pump_before_stage3(s,at);end if;
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' loop at:=ml_private.p3g_now(s,at);s:=ml_private.p3h_observe_hp(s);
 due:=ml_private.stage3_overflow(s,s->'order')->0;
 if due is not null then a:=(due->>'actor')::int;s:=ml_private.select_choice(s,'xiao-overflow',a,at,jsonb_build_object('source',due->'collector','count',due->'count','cards',s#>array['players',a::text,'hand']));exit;end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_begin_interrupt(s,at);if s->>'_interruptBegan'='true' then s:=s-'_interruptBegan';continue;end if;s:=s-'_interruptBegan';end if;
 if ml_private.p3h_should_yield(s) then return ml_private.end_turn(s,at);end if;exit when jsonb_array_length(s->'queue')=0;guard:=guard+1;perform ml_private.need(guard<200,'内部流程未收敛');t:=s->'queue'->0;s:=jsonb_set(s,'{queue}',(s->'queue')-0);a:=coalesce((t->>'actor')::int,(s->>'active')::int);p:=s->'players'->a;
 case t->>'kind'
 when 'stage3' then s:=ml_private.stage3_handle_task(s,t,at);if s->>'phase'='action' and s->'choice'='null'::jsonb then s:=ml_private.resume(s,at);end if;
 when 'water' then if ml_private.classic_owes_water(s,a) or (t#>>'{data,entry}'='true' and (p->>'hp')::int>0 and jsonb_array_length(p->'hand')>0) then if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.stage4_combat_gear(s,a,'basic-069') is not null and coalesce(t#>>'{data,noTang}','false')<>'true' then if ml_private.stage4_ignore_location(s,a) then null;else s:=ml_private.select_choice(s,'gear-terrain',a,at,jsonb_build_object('data',jsonb_build_object('task',t)));end if;else s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;end if;
 when 'classic-start' then
 for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a)) then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);s:=ml_private.put_player(s,a,p);s:=ml_private.stage3_round_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';
 if allowed and (p->>'ap')::int<5 and p->>'character'<>'character-031' then s:=ml_private.stage3_gain_ap(s,a,ml_private.p3h_ren_round_ap(s,a,3));s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得'||ml_private.p3h_ren_round_ap(s,a,3)||'AP → '||(s#>>array['players',a::text,'ap']));end if;end if;end loop;
 s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when s#>>'{classic,farmClosed}'='true' then '；高唐农场已封闭' else '' end);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','after-env')));
 when 'round-next' then s:=ml_private.p3h_take_extra(s,jsonb_build_array(t)||(s->'queue'));if s->>'_hExtraTaken'='true' then s:=s-'_hExtraTaken';continue;end if;s:=s-'_hExtraTaken'; s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
 when 'walk' then if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_resume_walk(s,coalesce(t->'path','[]'),at);else s:=ml_private.classic_walk(s,coalesce(t->'path','[]'),at);end if;
 when 'after-env' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then cursor:=0;while not ml_private.stage3_alive(s,(s->'order'->>cursor)::int) loop cursor:=cursor+1;end loop;s:=s||jsonb_build_object('cursor',cursor);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor)));end if;
 when 'turn-start' then
 if t#>>'{data,resuming}' is distinct from 'true' then
 s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));
 s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at));s:=ml_private.put_player(s,a,p||jsonb_build_object('moved',false,'attacks',0));s:=ml_private.stage3_turn_start(s,a);if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['stage4','offMap',a::text]='true' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','turn-start','actor',a,'data',jsonb_build_object('resuming',true))));s:=ml_private.stage4_return(s,a,at);continue;end if;end if;
 if ml_private.p3f_enabled(s) and t#>>'{data,fDriftDone}' is distinct from 'true' and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-051' then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('f-drift',jsonb_build_object('actor',a,'data',jsonb_build_object('root','turn'||(s#>>'{stage3,turn}')))),jsonb_build_object('kind','turn-start','actor',a,'data',jsonb_build_object('resuming',true,'fDriftDone',true))));continue;end if;
 if ml_private.p3g_enabled(s) and t#>>'{data,gCubeDone}' is distinct from 'true' and jsonb_array_length(ml_private.p3g_cube_start_tasks(s,a))>0 then s:=ml_private.stage3_prepend(s,ml_private.p3g_cube_start_tasks(s,a)||jsonb_build_array(jsonb_build_object('kind','turn-start','actor',a,'data',coalesce(t->'data','{}')||jsonb_build_object('resuming',true,'gCubeDone',true))));continue;end if;
 if ml_private.p3h_enabled(s) and t#>>'{data,hStartDone}' is distinct from 'true' and jsonb_array_length(ml_private.p3h_start_tasks(s,a))>0 then s:=ml_private.stage3_prepend(s,ml_private.p3h_start_tasks(s,a)||jsonb_build_array(jsonb_build_object('kind','turn-start','actor',a,'data',coalesce(t->'data','{}')||jsonb_build_object('resuming',true,'hStartDone',true))));continue;end if;
 s:=ml_private.stage3_start_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';p:=s->'players'->a;
 if allowed and p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP');end if;
 ap:=case when allowed then ml_private.stage4_location_ap(s,a) else (p->>'ap')::int end;
 if ap>(p->>'ap')::int then s:=ml_private.stage3_gain_ap(s,a,ap-(p->>'ap')::int);s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(s#>>array['players',a::text,'ap']));end if;
 s:=ml_private.p3c_sleep(s,a,allowed);s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动');if (s->>'round')::int>1 and coalesce(s#>>array['stage4','drawBlocked',a::text],'false')<>'true' then if ml_private.p3g_enabled(s) and p->>'character'='character-009' then null;else s:=ml_private.draw(s,a,ml_private.stage4_location_draw(s,a)+ml_private.p3g_cube_draw(s,a));end if;elsif ml_private.p3g_cube_draw(s,a)>0 then s:=ml_private.draw(s,a,ml_private.p3g_cube_draw(s,a));end if;
 s:=ml_private.stage3_prepend(s,case when ml_private.p3g_enabled(s) and p->>'character'='character-009' and (s->>'round')::int>1 and coalesce(s#>>array['stage4','drawBlocked',a::text],'false')<>'true' then jsonb_build_array(ml_private.stage3_task('g-white-eye',jsonb_build_object('actor',a))) else '[]'::jsonb end||case when p->>'character'='character-010' then jsonb_build_array(ml_private.stage3_task('east',jsonb_build_object('actor',a))) else '[]'::jsonb end||jsonb_build_array(jsonb_build_object('kind','action')));if p->>'character'='character-027' and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or s#>>array['stage4','drawBlocked',a::text]<>'true') then s:=ml_private.select_choice(s,'draw-start',a,at);end if;
 when 'action' then if ml_private.p3h_enabled(s) and s#>array['stage3','h','frozenBy',a::text]<>'null'::jsonb then s:=jsonb_set(s,array['stage3','h','frozenBy',a::text],'null');s:=ml_private.emit(s,'skill','S'||(a+1)||' 冰封之力：跳过本次自由行动，继续个人结束结算');s:=ml_private.end_turn(s,at);else s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;
 when 'end-draw' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-end')));if p->>'character'='character-027' and (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a)) and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at);end if;
 when 'cave-end' then s:=ml_private.cave_ending(s,a);if jsonb_array_length(s->'_hits')>0 then s:=ml_private.damage(s,s->'_hits',true);s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));s:=s-'_triggers';else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));end if;s:=s-'_hits';
 when 'cave-after' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','discard','actor',a)));end if;
 when 'discard' then countn:=jsonb_array_length(p->'hand')-(p->>'hp')::int;s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand'));end if;
 when 'next' then s:=ml_private.next_turn(s,at);
 when 'trigger' then
 if (p->>'hp')::int<=0 then continue;end if;kind:=t->>'trigger';
 if kind='lemon-reward' then if t ? 'source' and not (s#>array['players',t->>'source','rewarded'] @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',t->'source'));end if;
 elsif p->>'skillUsed'='false' then
 if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at);end if;
 if kind='teleport' then cells:=ml_private.teleport_cells(s,a);if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells));end if;end if;end if;
 else raise exception '未知内部任务';end case;end loop;return s;
end $$;
create or replace function ml_private.end_turn(s jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; begin
 if s->'movement'<>'null'::jsonb then s:=ml_private.settle_movement(s);s:=ml_private.classic_relocated(s,a,s->'players'->a->>'cell',s#>>'{movement,lastEmpty}'); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',s#>'{movement,lastEmpty}')); s:=jsonb_set(s,'{movement}','null'); s:=ml_private.emit(s,'move','移动结束，落点'||(s->'players'->a->>'cell')||'，剩余额度作废'); end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('gear-end',jsonb_build_object('actor',a))));end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.stage4_desert(s,a) is not null then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('board-desert',jsonb_build_object('actor',a))));end if;
 s:=s||jsonb_build_object('phase','resolving','queue',(s->'queue')||ml_private.p3e_end_tasks(s)||ml_private.p3f_end_tasks(s)||ml_private.p3g_end_tasks(s)||jsonb_build_array(jsonb_build_object('kind',case when timeout then case when s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 'cave-end' else 'discard' end else 'end-draw' end))); return ml_private.pump(s,at);
end $$;
create or replace function ml_private.choose(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;card text:=cmd->>'card';parent jsonb;d jsonb;q jsonb;quoted jsonb;fee jsonb;child jsonb;idx text;begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or c->>'kind' not in ('card-counter','forced-card','board-path','board-cell','board-guess','board-tax','board-return','native-shore','gear-loss','gear-cloak','gear-reflect','gear-chalk','gear-plant','gear-react','gear-push','gear-terrain') then return ml_private.choose_before_stage4(s,cmd,at,timeout);end if;
 perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 if c->>'kind' in ('gear-react','gear-push','gear-terrain') then s:=ml_private.stage4_movement_choose(s,cmd,at,timeout);
 elsif c->>'kind' in ('gear-cloak','gear-reflect','gear-chalk','gear-plant') then s:=ml_private.stage4_combat_choose(s,cmd,at,timeout);
 elsif c->>'kind'='gear-loss' then s:=ml_private.stage4_gear_loss_choose(s,cmd,at,timeout);
 elsif c->>'kind' in ('board-path','board-cell','board-guess','board-tax','board-return','native-shore') then s:=ml_private.stage4_map_choose(s,cmd,at,timeout);
 elsif c->>'kind'='forced-card' then
  if card is not null and card<>'' then
   perform ml_private.need(c->'cards' ? card and s#>array['players',a::text,'hand'] ? card,'必须交出符合要求的手牌');s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=ml_private.exercise_discard(s,jsonb_build_array(card));s:=ml_private.emit(s,'deliver','S'||(a+1)||' 交出1张牌（不发动牌效）');
  else s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',c->'source','category','attack','directHp',true)));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 elsif card is not null and card<>'' and not timeout then
  parent:=s#>'{cardStack,stack,-1}';perform ml_private.need(ml_private.stage4_counter_cards(s,a,parent) ? card,'此牌不能反制当前效果');d:=ml_private.stage4_content()#>array['cards',split_part(card,'#',1)];q:=s#>array['stage4','costs','locks',card];
  if d#>>'{cost,kind}' in ('die','tiers') then perform ml_private.need(q->'turn'=s#>'{stage3,turn}','请先锁定响应牌费用');end if;
  quoted:=ml_private.stage3_card_cost(s,a,card,(q->>'cost')::int);fee:=ml_private.stage4_fee_plan((s#>>array['players',a::text,'ap'])::int,(quoted->>'cost')::int);
  s:=ml_private.p3d_pay(s,a,(fee->>'spend')::int);if (fee->>'gain')::int>0 then s:=ml_private.stage3_gain_ap(s,a,(fee->>'gain')::int);s:=s-'_gain';end if;
  s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));
  s:=ml_private.stage3_begin_card(s,a,card,d->>'id',jsonb_build_array(parent->'actor'),quoted->'effect',at,(parent->>'serial')::int);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;
  s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],jsonb_build_object('counter',case when d->>'id'='basic-027' then 'tactic' when d->>'id'='basic-028' then 'jianmin' else 'food' end));child:=s#>'{cardStack,stack,-1}';
  s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',child->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',child->'serial'))));
  s:=ml_private.emit(s,'response','S'||(a+1)||' 使用'||(d->>'name')||'，支付'||(fee->>'spend')||'AP'||case when (fee->>'gain')::int>0 then '，获得'||(fee->>'gain')||'AP' else '' end);
 end if;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;
 s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);
 if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
end $$;
create or replace function ml_private.validate(s jsonb) returns void language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer;b integer;begin perform ml_private.need(ml_private.p3g_equipment_valid(s),'G装备实体账本无效');
 perform ml_private.need(ml_private.p3f_valid(s),'F批角色状态无效');
 perform ml_private.need(ml_private.p3e_valid(s),'E批角色状态无效');
 perform ml_private.need(ml_private.p3d_valid(s),'D批角色状态无效');
 perform ml_private.need(ml_private.p3c_valid(s),'C批角色状态无效');
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then perform ml_private.validate_before_stage3(s);return;end if;
 perform ml_private.need(jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb,'状态版本/轮次/人数无效');
 perform ml_private.need((select count(distinct member->>'character') from ml_private.arr(s->'players') member)=4 and not exists(select 1 from ml_private.arr(s->'players') member where not (ml_private.game_data(s,'characterIds') ? (member->>'character'))),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a;zones:=zones||(p->'hand')||(s#>array['stage3','equipment',a::text]);
 perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int>=0 and case when ml_private.p3f_enabled(s) then (p->>'maxHp')::numeric=trunc((p->>'maxHp')::numeric) and (p->>'maxHp')::int>=0 and case when ml_private.p3f_uncapped(s,(p->>'seat')::int) then (p->>'maxHp')::int=2 else (p->>'hp')::int<=(p->>'maxHp')::int end else (p->>'hp')::int<=(p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp' end,'生命状态无效');
 perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::int between 0 and 2,'AP/护盾无效');perform ml_private.need((ml_private.game_data(s,'map') ? (p->>'cell') or ml_private.p3h_pending_birth(s,(p->>'seat')::int) and s#>>'{choice,kind}'='h-birth' and s#>'{choice,actor}'=p->'seat' and not exists(select 1 from ml_private.arr(s#>'{stage3,starts}') x where x<>'0'::jsonb) and not exists(select 1 from ml_private.arr(s->'players') x where jsonb_array_length(x->'hand')<>0)),'位置无效');
 if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb and s#>array['stage3','equipment',a::text]='[]'::jsonb,'淘汰清理无效');end if;
 for b in 0..a-1 loop if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,b) and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a) and ml_private.stage4_on_board(s,b)) and ml_private.p3h_blocks(s,a,b) and p->'cell'=s->'players'->b->'cell' then perform ml_private.need(ml_private.p3g_haki(s,(s->>'active')::int) and (s#>>'{movement,remaining}')::int>0 and (a=(s->>'active')::int or b=(s->>'active')::int) or s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and (s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠');end if;end loop;end loop;
 zones:=ml_private.p3g_equipment_zones(s,zones);perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'实体不守恒或实体重复');
 perform ml_private.need(jsonb_array_length(s#>'{classic,caveEnds}')=4 and not exists(select 1 from ml_private.arr(s#>'{classic,caveEnds}') n where (n#>>'{}')::int not between 0 and 2),'山洞计数无效');
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.occupied(s jsonb,cell text,except_actor integer default -1) returns boolean language sql immutable
set search_path=pg_catalog,ml_private as $$ select exists(select 1 from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and p->>'cell'=cell and ml_private.p3h_blocks(s,except_actor,(p->>'seat')::int) and (p->>'seat')::int<>except_actor) $$;
create or replace function ml_private.teleport_cells(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.stage3_mount_blocked(s,a) then return '[]';end if;if s->>'version' in ('web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.p3_potato_cells(s,a);end if;return ml_private.teleport_cells_before_stage3(s,a);
end $$;
create or replace function ml_private.legal_steps(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare result jsonb:='[]';c jsonb;a integer:=(s->>'active')::int;p jsonb:=s->'players'->a;cost integer;target integer;valid boolean;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.legal_steps_before_stage3(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return result;end if;
 for c in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop cost:=ml_private.classic_step_cost(s,a,c->>'id');
 if not ml_private.p3f_preview_move(s,a,c->>'id') or not ml_private.stage3_can_enter(s,a,c->>'id') or (s#>>'{movement,direction}' is not null and not ml_private.stage3_west_step(p->>'cell',c->>'id',s#>>'{movement,direction}')) then continue;end if;
 select (q->>'seat')::int into target from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and (q->>'seat')::int<>a and ml_private.p3h_blocks(s,a,(q->>'seat')::int) and q->'cell'=c->'id' limit 1;
 if target is not null and (p->>'character'='character-040' or s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and p->>'character'<>'character-045' and not ml_private.p3g_haki(s,a)) then continue;end if;
 if target is not null and p->>'character'='character-045' then valid:=not(ml_private.p3e_enabled(s) and s#>>array['players',target::text,'character']='character-016' and coalesce(s#>>array['stage3','e','permissions',ml_private.p3e_root(s)||':'||a||':'||target],'true')='false') and cost is not null and cost<=(s#>>'{movement,remaining}')::int and not ml_private.stage4_location_stops(s,a,c->>'id') and jsonb_array_length(ml_private.stage3_collision_path(ml_private.stage3_board(s),a,target,ml_private.stage3_direction(s,p->>'cell',c->>'id')))>0;
 else valid:=cost is not null and cost<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,a,c->>'id',(s#>>'{movement,remaining}')::int-cost);end if;
 if valid then result:=result||jsonb_build_array(c->'id');end if;end loop;return result;
end $$;
create or replace function ml_private.targets(s jsonb,a integer,card text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare d jsonb:=ml_private.rule_card(s,card);p jsonb:=s->'players'->a;result jsonb;lemon integer;lmm integer;begin if ml_private.p3g_cube_face(s,a)=1 then return '[]';end if;
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.targets_before_stage3(s,a,card);end if;
 if d is null or d->>'type'<>'attack' then return '[]';end if;if d->>'id'='basic-010' then return ml_private.stage3_monkey_targets(s,a);end if;
 select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality t(q,ord) where ml_private.p3g_card_target_allowed(s,a,(q->>'seat')::int,d->>'id') and (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(q->>'seat')::int) and (d->>'group'='true' or not ml_private.stage4_single_protected(s,a,(q->>'seat')::int))) and (q->>'seat')::int<>a and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or split_part(card,'#',1)<>'basic-006' or not ml_private.stage3_equipped(s,(q->>'seat')::int,'basic-057')) and (s->>'mode'='ffa' or q->'team'<>p->'team') and not (d->>'group'='true' and q->>'character'='character-027' and jsonb_array_length(q->'hand')=1) and (d->>'id'<>'basic-009' or ml_private.p3d_ball_allowed(s,a,(q->>'seat')::int)) and (not ml_private.p3c_feather(s,a) or q->>'character' not in ('character-026','character-044')) and ml_private.stage4_location_card(s,a,d->>'id') and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_card_range(s,a,d,q->>'cell') else (d->>'range'='global' or ml_private.game_data(s,'map')#>>array[q->>'cell','region']=ml_private.game_data(s,'map')#>>array[p->>'cell','region'] or (d->>'range'='adjacent' and ml_private.stage3_same_near(p->>'cell',q->>'cell'))) end);
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and coalesce(d->>'group','false')<>'true' then lmm:=ml_private.stage4_lmm_target(s,a,result);if lmm is not null then return jsonb_build_array(lmm);end if;end if;
 select (q->>'seat')::int into lemon from ml_private.arr(s->'players') q where q->>'character'='character-004' and result @> jsonb_build_array(q->'seat');if coalesce(d->>'group','false')<>'true' and lemon is not null then return jsonb_build_array(lemon);end if;return result;
end $$;
create or replace function ml_private.heal(s jsonb,a integer,amount integer,food boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; old integer:=(p->>'hp')::int; hp integer:=old; begin
 if hp>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a)) then amount:=case when food then ml_private.stage4_location_food(s,a,amount) else case when ml_private.p3f_enabled(s) then amount else least((p->>'maxHp')::int-hp,amount) end end;hp:=hp+case when s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_healing(s,a,amount,food) else amount end;end if;
 s:=ml_private.put_player(s,a,p||jsonb_build_object('hp',hp)); s:=ml_private.p3h_cooperate_heal(s,a,hp-old);s:=ml_private.p3h_observe_hp(s);return ml_private.emit(s,'heal',ml_private.name(s,a)||' 回复'||(hp-old)||'生命');
end $$;
create or replace function ml_private.select_choice(s jsonb,kind text,a integer,at double precision,extra jsonb default '{}') returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare paused boolean:=ml_private.playtest_role_choice(s,kind) or kind not in ('draw-start','draw-end'); serial integer:=(s->>'choiceSerial')::int+1; begin if ml_private.p3h_active_choice(kind) and not ml_private.p3h_active_allowed(s,a) then return s;end if;if kind='easy' and not ml_private.p3h_active_allowed(s,a) then return jsonb_set(s,array['cardStack','stack',(jsonb_array_length(s#>'{cardStack,stack}')-1)::text,'counter'],'null');end if; at:=ml_private.p3g_now(s,at);
 if paused then s:=ml_private.pause(s,at); else s:=ml_private.resume(s,at); end if;
 s:=s||jsonb_build_object('phase','choice','choiceSerial',serial,'choice',jsonb_build_object('id',serial,'kind',kind,'actor',a,'deadline',at+least(case when ml_private.playtest_role_choice(s,kind) then 30000 when (ml_private.p3g_enabled(s) and kind='g-discard' or kind='discard' or ml_private.p3f_enabled(s) and kind='f-discard' or ml_private.p3d_enabled(s) and kind='encourage-discard') and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 20000 else 10000 end,case when paused then (case when ml_private.playtest_role_choice(s,kind) then 30000 when (ml_private.p3g_enabled(s) and kind='g-discard' or kind='discard' or ml_private.p3f_enabled(s) and kind='f-discard' or ml_private.p3d_enabled(s) and kind='encourage-discard') and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 20000 else 10000 end) else ml_private.budget(s,at) end),'paused',paused)||extra);
 return ml_private.emit(s,'choice',ml_private.name(s,a)||' 等待选择：'||ml_private.p3h_choice_label(kind));
end $$;
create or replace function ml_private.damage(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.stage3_damage(s,hits,environment,false);end if;return ml_private.damage_before_stage3(s,hits,environment);
end $$;
create or replace function ml_private.p3h_create_development(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin perform ml_private.need(setup->>'ruleVersion'='web-v0.1.19','开发开局仅接受H版本');
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1,s->'_shuffle'->2,s->'_shuffle'->3) else s->'_shuffle' end; s:=s-'_shuffle'; end if;
 perform ml_private.need(case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_array_length(chars)=4 and (select count(distinct x) from ml_private.arr(chars) x)=4 and ml_private.game_data(s,'characterIds') @> chars else (select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x) end,'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if ml_private.p3d_enabled(s) and chars ? 'character-020' then select ord-1 into firstn from jsonb_array_elements(chars) with ordinality q(v,ord) where v='"character-020"';end if;
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and setup->>'mode'='team' then to_jsonb(case when teams->>a='A' then '机械猴子' else '帝汶家族' end) else c->'faction' end,'hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
 if rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('stage3',ml_private.stage3_initial(),'cardStack',jsonb_build_object('serial',0,'stack','[]'::jsonb));end if;
 if rulev in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('stage4',ml_private.stage4_initial(s->'players'));end if;
 if ml_private.p3d_enabled(s) then s:=ml_private.p3d_start(ml_private.p3c_start(s,firstn),firstn);end if;if ml_private.p3e_enabled(s) then s:=ml_private.p3e_start(s,firstn);end if;if ml_private.p3f_enabled(s) then s:=ml_private.p3f_start(s,firstn);end if;if ml_private.p3g_enabled(s) then s:=jsonb_set(s,'{stage3,g}',ml_private.p3g_initial_state());end if;if ml_private.p3c_enabled(s) and not(s#>'{stage3}' ? 'c') then s:=jsonb_set(s,'{stage3,c}','{"feather":[false,false,false,false],"blocked":[false,false,false,false],"used":[false,false,false,false],"sleep":[false,false,false,false]}'::jsonb);end if;if ml_private.p3h_enabled(s) then s:=jsonb_set(s,'{stage3,h}',ml_private.p3h_initial_state());s:=ml_private.p3h_observe_hp(s,true);end if;s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); s:=ml_private.p3h_birth_begin(s,at);if s#>>'{choice,kind}'='h-birth' then perform ml_private.validate(s);return s;end if;for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 if ml_private.p3g_enabled(s) then return ml_private.p3g_initial(s,at);end if;s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
create or replace function ml_private.create_game(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1,s->'_shuffle'->2,s->'_shuffle'->3) else s->'_shuffle' end; s:=s-'_shuffle'; end if;
 perform ml_private.need(case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_array_length(chars)=4 and (select count(distinct x) from ml_private.arr(chars) x)=4 and ml_private.game_data(s,'characterIds') @> chars else (select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x) end,'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if ml_private.p3d_enabled(s) and chars ? 'character-020' then select ord-1 into firstn from jsonb_array_elements(chars) with ordinality q(v,ord) where v='"character-020"';end if;
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
