 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
