create or replace function ml_private.public_view(s jsonb,viewer integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare v jsonb:=ml_private.public_view_before_stage4(s,viewer);begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return v;end if;
 if ml_private.p3e_enabled(s) then v:=jsonb_set(v,'{stage3,e}',jsonb_build_object('escapeUsed',s#>'{stage3,e,escapeUsed}'));end if;if ml_private.p3d_enabled(s) then v:=jsonb_set(v,'{stage3,d}',s#>'{stage3,d}');end if;if ml_private.p3c_enabled(s) then v:=jsonb_set(v,'{stage3,c}',s#>'{stage3,c}');end if;if ml_private.p3f_enabled(s) then v:=jsonb_set(v,'{stage3,f}',jsonb_build_object('firstDeath',s#>'{stage3,f,firstDeath}','wounds',s#>'{stage3,f,wounds}','unlimitedCeil',s#>'{stage3,f,unlimitedCeil}','home',s#>'{stage3,f,home}','executeUsed',s#>'{stage3,f,executeUsed}'));v:=jsonb_set(v,'{players}',(select jsonb_agg(case when member->>'character'='character-019' then member||jsonb_build_object('uncappedHp',true) else member end order by ord) from jsonb_array_elements(v->'players') with ordinality q(member,ord)));end if;v:=v||jsonb_build_object('stage4',ml_private.stage4_public_state(s));if ml_private.p3g_enabled(s) then if ml_private.p3h_enabled(s) then v:=jsonb_set(v,'{stage3,h}',jsonb_build_object('frozenBy',s#>'{stage3,h,frozenBy}','freezeReadyAt',s#>'{stage3,h,freezeReadyAt}','circles',s#>'{stage3,h,circles}','circleUsed',s#>'{stage3,h,circleUsed}','ren',ml_private.p3h_ren_public(s),'cooperation',ml_private.p3h_cooperate_public(s))||case when s#>'{stage3,h}' ? 'birth' then jsonb_build_object('birth',s#>'{stage3,h,birth}') else '{}'::jsonb end);end if;v:=jsonb_set(v-'exercise','{stage3,g}',ml_private.p3g_public_state(s,viewer));end if;return jsonb_set(v,'{actions,stage4}',ml_private.stage4_actions(s,viewer));
end $$;
create or replace function ml_private.settle_movement(s jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare m jsonb:=s->'movement';begin
 s:=ml_private.p3e_end_move(s);
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and jsonb_array_length(m->'path')>1 and jsonb_array_length(coalesce(m->'carry','[]'))>0 then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',s->'active','data',m->'carry'))));s:=jsonb_set(s,'{movement,carry}','[]');end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and jsonb_array_length(m->'path')>1 and coalesce(m->>'gearQueued','false')<>'true' then s:=jsonb_set(s,'{movement,gearQueued}','true');s:=jsonb_set(s,'{queue}',(s->'queue')||ml_private.stage4_landing_tasks(s,(s->>'active')::int,ml_private.stage3_direction(s,m#>>'{path,-2}',m#>>'{path,-1}')));end if;return ml_private.settle_movement_before_stage3(s);
end $$;
create or replace function ml_private.runtime_data(v text,k text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare profile jsonb:=ml_private.version_catalog(v); result jsonb; begin
 perform ml_private.need((profile#>>'{manifest,status}'='playable' or (v in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and profile#>>'{manifest,status}'='development')),'经典图仅完成数据基础，后续规则未启用');
 result:=profile->'runtimeData'->k; perform ml_private.need(result is not null,'未知版本数据键'); return result;
end $$;
create or replace function ml_private.safe_for_version(v text,r integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.runtime_data(v,'cells')) c where v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or r<=3 or (r<=5 and (c->>'col')::int between 2 and 7) or (r>5 and r<=7 and (c->>'col')::int between 3 and 6) or (r>7 and r<=9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 6) or (r>9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 5) $$;
create or replace function ml_private.allocate_spawns(v text,ids jsonb,s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare profile jsonb:=ml_private.version_catalog(v); id text; region text; groups integer; candidates jsonb; used jsonb:='[]'; cells jsonb:='[]'; cell jsonb; begin
 perform ml_private.need(v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19'),'旧版使用固定坐标出生');
 perform ml_private.need(jsonb_typeof(ids)='array' and jsonb_array_length(ids)=4 and (select count(distinct x) from ml_private.arr(ids) x)=4,'必须有四个不同角色');
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  if v='web-v0.1.19' and id='character-035' then continue;end if;candidates:=ml_private.spawn_candidates(v,id); region:=profile#>>array['sourceCatalog','characters',id,'spawnRegion'];
  select count(*) into groups from ml_private.arr(ids) x where profile#>>array['sourceCatalog','characters',x#>>'{}','spawnRegion']=region;
  perform ml_private.need(jsonb_array_length(candidates)>0 and groups<=jsonb_array_length(candidates),'出生地区空格不足');
 end loop;
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  if v='web-v0.1.19' and id='character-035' then cells:=cells||jsonb_build_array(''::text);continue;end if;select jsonb_agg(x) into candidates from ml_private.arr(ml_private.spawn_candidates(v,id)) x where not used @> jsonb_build_array(x);
  s:=ml_private.int(s,jsonb_array_length(candidates)); cell:=candidates->(s->>'_int')::int;
  used:=used||jsonb_build_array(cell); cells:=cells||jsonb_build_array(cell); s:=s-'_int';
 end loop;
 return s||jsonb_build_object('_spawns',cells);
end $$;
