end $$;
create or replace function ml_private.classic_relocated(s jsonb,a integer,origin text,cell text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.region_at(s->>'version',origin)<>ml_private.region_at(s->>'version',cell) then s:=jsonb_set(s,array['classic','exposure',a::text],jsonb_build_object('region',null,'streak',0));end if;
 if s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.region_at(s->>'version',origin)='山洞' and ml_private.region_at(s->>'version',cell)<>'山洞' then s:=jsonb_set(s,array['classic','caveEnds',a::text],'0');end if;
 return s;
end $$;
create or replace function ml_private.classic_owes_water(s jsonb,a integer,origin text default null) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not ml_private.stage4_ignore_location(s,a) and not ml_private.classic_native(s,a) and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_water(s,s->'players'->a->>'cell',a) else ml_private.classic_water(s,s->'players'->a->>'cell') end) and (origin is null or not (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_water(s,origin,a) else ml_private.classic_water(s,origin) end)) and (s->'players'->a->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a)) and jsonb_array_length(s->'players'->a->'hand')>0 $$;
create or replace function ml_private.classic_refresh(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare pool jsonb; safe jsonb; begin
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.classic_refresh_before_patch(s);end if;
 select coalesce(jsonb_agg(r),'[]') into pool from ml_private.arr(ml_private.patch_poison_regions(s->>'version')) r where not (s#>'{classic,poison}' ? (r#>>'{}'));
 s:=ml_private.classic_pick(s,pool,2);s:=jsonb_set(s,'{classic,poison}',(s#>'{classic,poison}')||(s->'_picked'));s:=s-'_picked';
 s:=jsonb_set(s,'{classic,farmClosed}',to_jsonb((s->>'round')::int>=5));
 select coalesce(jsonb_agg(c->'id'),'[]') into safe from ml_private.arr(ml_private.game_data(s,'cells')) c where not (s#>'{classic,poison}' ? (c->>'region'));
 s:=s||jsonb_build_object('safe',safe,'bomb',null,'forecast',null);return ml_private.p3g_reserve_forecast(s);
end $$;
create or replace function ml_private.classic_environment(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare hits jsonb:='[]';p jsonb;a integer;region text;old jsonb;danger boolean;streak integer;amount integer;loss integer;begin
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.classic_environment_before_patch(s);end if;
 if ml_private.p3g_enabled(s) and s#>>'{stage3,g,forecast,round}'=s->>'round' then s:=s||jsonb_build_object('_picked',s#>'{stage3,g,forecast,regions}');else s:=ml_private.classic_pick(s,ml_private.patch_bomb_regions(s),2,true);end if;s:=jsonb_set(s,'{classic,bombs}',s->'_picked');s:=s-'_picked';s:=jsonb_set(s,'{classic,bombRound}',s->'round');
 for a in 0..3 loop p:=s->'players'->a;if ((p->>'hp')::int<=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not ml_private.stage4_on_board(s,a)) then continue;end if;
  region:=ml_private.region_at(s->>'version',p->>'cell');old:=s#>array['classic','exposure',a::text];danger:=s#>'{classic,poison}' ? region or s#>'{classic,bombs}' ? region;
  streak:=case when not danger then 0 when old->>'region'=region then (old->>'streak')::int+1 else 1 end;
  amount:=case when danger then power(2,least(30,streak-1))::int else 0 end;loss:=least((p->>'hp')::int,greatest(0,amount-(p->>'shield')::int));
  s:=jsonb_set(s,array['classic','exposure',a::text],case when loss>0 then jsonb_build_object('region',region,'streak',streak) else jsonb_build_object('region',null,'streak',0) end);
  hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',amount,'source',null,'category','environment'));
 end loop;return s||jsonb_build_object('_hits',hits);
end $$;
create or replace function ml_private.classic_landings(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare origin jsonb; cell jsonb; nearc jsonb; dr integer; dc integer; r integer; coln integer; result jsonb:='[]'; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or not ml_private.classic_native(s,a) then return '[]'; end if;
 origin:=ml_private.game_data(s,'map')->(s->'players'->a->>'cell');if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_water(s,origin->>'id',a) else origin->>'terrain'<>'land' end) then return '[]'; end if;
 for dr,dc in select * from (values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) loop
  r:=(origin->>'row')::int+dr;coln:=(origin->>'col')::int+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then cell is null or not ml_private.stage4_board_water(s,cell->>'id',a) else cell->>'terrain' is distinct from 'water' end) then continue; end if;
  while (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then cell is not null and ml_private.stage4_board_water(s,cell->>'id',a) else cell->>'terrain'='water' end) loop if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not ml_private.p3g_haki(s,a) and ml_private.occupied(s,cell->>'id',a) then cell:=null;exit;end if;if (ml_private.p3g_haki(s,a) or ml_private.p3h_small(s,a)) and not ml_private.stage4_board_entry(s,a,cell->>'id') then cell:=null;exit;end if;r:=r+dr;coln:=coln+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);end loop;
  if cell is null then continue;end if;
  if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_entry(s,a,cell->>'id') else ml_private.classic_enter(s,cell->>'id') end) and (not ml_private.occupied(s,cell->>'id',case when ml_private.p3h_small(s,a) then a else -1 end) or ml_private.p3g_haki(s,a) and ml_private.occupied(s,cell->>'id',a)) then result:=result||jsonb_build_array(cell->'id');
  elsif s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.occupied(s,cell->>'id',case when ml_private.p3h_small(s,a) then a else -1 end) then
   for nearc in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then not ml_private.stage4_board_water(s,nearc->>'id',a) else nearc->>'terrain'='land' end) and ml_private.distance_for_version(s->>'version',cell->>'id',nearc->>'id')=1 and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_entry(s,a,nearc->>'id') else ml_private.classic_enter(s,nearc->>'id') end) and not ml_private.occupied(s,nearc->>'id',-1) then result:=result||jsonb_build_array(nearc->'id');end if;end loop;
  end if;
 end loop;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where result ? (c->>'id'));
end $$;
create or replace function ml_private.classic_step_cost(s jsonb,a integer,cell text) returns integer language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if not ml_private.classic_enter(s,cell) then return null;end if;
 if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.classic_native(s,a) and ml_private.stage4_board_water(s,cell,a) then return null;end if;
 if ml_private.classic_landings(s,a) ? cell then return 1;end if;
 if ml_private.distance_for_version(s->>'version',s->'players'->a->>'cell',cell)=1 then return case when (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_water(s,cell,a) else ml_private.classic_water(s,cell) end) and not ml_private.stage4_ignore_location(s,a) then 2 else 1 end;end if;return null;
end $$;
create or replace function ml_private.classic_walk(s jsonb,path jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int;p jsonb;m jsonb;check_s jsonb;cell text;origin text;cost integer;idx integer:=0;pushed jsonb;haki_tasks jsonb;tail jsonb;arrival jsonb;water_due boolean;f_path jsonb;f_exit text;e_target integer;e_gate jsonb;begin if ml_private.p3g_haki(s,(s->>'active')::int) or ml_private.p3h_small(s,(s->>'active')::int) then s:=ml_private.finish(s,false,at);if s->>'phase'='over' then return s;end if;if not ml_private.stage4_on_board(s,(s->>'active')::int) then return ml_private.end_turn(s,at);end if;end if;
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.classic_walk_before_stage3(s,path,at);end if;
 s:=jsonb_set(s,'{phase}','"moving"');check_s:=s;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(check_s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');check_s:=ml_private.stage3_collision(case when ml_private.p3e_enabled(check_s) then check_s||jsonb_build_object('_eProbe',true) else check_s end,cell)-'_eProbe';check_s:=check_s-'_pushedTasks';cost:=ml_private.classic_step_cost(check_s,a,cell);check_s:=jsonb_set(check_s,'{movement,remaining}',to_jsonb((check_s#>>'{movement,remaining}')::int-cost));check_s:=jsonb_set(check_s,array['players',a::text,'cell'],to_jsonb(cell));if ml_private.stage4_location_stops(check_s,a,cell) then check_s:=jsonb_set(check_s,'{movement,remaining}','0');end if;end loop;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');if ml_private.p3e_enabled(s) and not ml_private.p3g_haki(s,a) then select (v->>'seat')::int into e_target from ml_private.arr(s->'players') v where (v->>'seat')::int<>a and ml_private.p3h_blocks(s,a,(v->>'seat')::int) and v->>'cell'=cell and ml_private.stage4_on_board(s,(v->>'seat')::int);if e_target is not null then select coalesce(jsonb_agg(v order by n),'[]') into tail from jsonb_array_elements(path) with ordinality q(v,n) where n>idx;e_gate:=ml_private.p3e_gate(s,e_target,a,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)),ml_private.p3e_root(s));if e_gate is not null then return jsonb_set(ml_private.stage3_prepend(s,e_gate),'{phase}','"resolving"');end if;end if;end if;if ml_private.p3f_enabled(s) and s#>>array['players',a::text,'character']='character-045' and e_target is not null then f_path:=ml_private.stage3_collision_path(ml_private.stage3_board(s),a,e_target,ml_private.stage3_direction(s,s#>>array['players',a::text,'cell'],cell));select v#>>'{}' into f_exit from jsonb_array_elements(f_path) with ordinality q(v,n) where not ml_private.stage4_board_water(s,v#>>'{}',e_target) order by n limit 1;if f_exit is not null then s:=ml_private.p3f_move_gate(s,e_target,f_exit);s:=s-'_fMoveAllowed';end if;if not(ml_private.legal_steps(s) ? cell) then return ml_private.emit(s,'move','干枯阻止离水，保留剩余步数');end if;end if;select coalesce(jsonb_agg(v order by n),'[]') into tail from jsonb_array_elements(path) with ordinality q(v,n) where n>idx;
 s:=ml_private.p3h_circle_gate(s,a,cell,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)),ml_private.p3e_root(s),false,ml_private.p3h_circle_line(s,s#>>array['players',a::text,'cell'],cell));e_gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if e_gate<>'null'::jsonb then if jsonb_array_length(e_gate)>0 then return jsonb_set(ml_private.stage3_prepend(s,e_gate),'{phase}','"resolving"');else return ml_private.resume(ml_private.emit(s,'move','画圆阻止本条越界位移，保留剩余步数'),at);end if;end if;
 if s#>>array['players',a::text,'character']='character-045' and e_target is not null then f_path:=ml_private.stage3_collision_path(ml_private.stage3_board(s),a,e_target,ml_private.stage3_direction(s,s#>>array['players',a::text,'cell'],cell));s:=ml_private.p3h_circle_gate(s,e_target,f_path->>-1,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)),ml_private.p3e_root(s),false,f_path);e_gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if e_gate<>'null'::jsonb then if jsonb_array_length(e_gate)>0 then return jsonb_set(ml_private.stage3_prepend(s,e_gate),'{phase}','"resolving"');else return ml_private.resume(ml_private.emit(s,'move','画圆阻止本条越界位移，保留剩余步数'),at);end if;end if;end if;
 s:=ml_private.stage3_collision(s,cell);pushed:=s->'_pushedTasks';s:=s-'_pushedTasks';p:=s->'players'->a;m:=s->'movement';origin:=p->>'cell';cost:=ml_private.classic_step_cost(s,a,cell);
 s:=ml_private.p3g_haki_crossed(s,a,origin,cell);haki_tasks:=s->'_gHakiTasks';s:=s-'_gHakiTasks';s:=ml_private.p3h_small_crossed(s,a,origin,cell,true);haki_tasks:=haki_tasks||(s->'_hSmallTasks');s:=s-'_hSmallTasks';m:=s->'movement';m:=m||jsonb_build_object('remaining',(m->>'remaining')::int-cost,'path',(m->'path')||jsonb_build_array(cell));p:=p||jsonb_build_object('cell',cell);s:=ml_private.put_player(s,a,p);s:=ml_private.classic_relocated(s,a,origin,cell);if ml_private.p3e_enabled(s) then s:=ml_private.p3e_moved(s,origin,cell,'move'||(m->>'gearRoot'));s:=s-'_eggTasks';end if;s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell);end if;if ml_private.stage4_location_stops(s,a,cell) then m:=jsonb_set(m,'{remaining}','0');end if;s:=jsonb_set(s,'{movement}',m);s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||(m->>'remaining'));idx:=idx+1;
 select coalesce(jsonb_agg(x order by n),'[]') into tail from jsonb_array_elements(path) with ordinality t(x,n) where n>idx;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then if ml_private.p3f_enabled(s) then s:=ml_private.p3f_arrival(s,a,origin,cell);arrival:=ml_private.p3f_arrival_order(s,a,origin,cell,true);s:=s-'_fArrival';else arrival:=ml_private.stage4_arrival_tasks(s,a,origin,cell);end if;water_due:=ml_private.classic_owes_water(s,a,origin);
 if jsonb_array_length(haki_tasks)>0 or jsonb_array_length(pushed)>0 or water_due or jsonb_array_length(arrival)>0 or ml_private.p3f_enabled(s) and e_target is not null then s:=ml_private.stage3_prepend(s,haki_tasks||pushed||case when water_due then jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true))) else '[]'::jsonb end||arrival||jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return jsonb_set(s,'{phase}','"resolving"');end if;end if;
 if jsonb_array_length(pushed)>0 then s:=ml_private.stage3_prepend(s,pushed||jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return jsonb_set(s,'{phase}','"resolving"');end if;
 if ml_private.classic_owes_water(s,a,origin) then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;end loop;
 if (s#>>'{movement,remaining}')::int=0 then s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');end if;return ml_private.resume(s,at);
end $$;
create or replace function ml_private.validate_draft(s jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare chosen jsonb; a integer; i integer; o jsonb:=s->'offer'; pool jsonb; begin
 perform ml_private.need(s->>'status' in ('choosing','complete') and s->>'version'='draft-v1' and s->>'catalogVersion' in ('web-v0.1.4','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and jsonb_array_length(s->'selected')=4 and (select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb,'选角状态版本或座位无效');
 select coalesce(jsonb_agg(x),'[]') into chosen from ml_private.arr(s->'selected') x where x<>'null'::jsonb;
 perform ml_private.need(jsonb_array_length(chosen)=(s->>'cursor')::int and (select count(distinct x) from ml_private.arr(chosen) x)=jsonb_array_length(chosen) and not exists(select 1 from ml_private.arr(chosen) x where not ((ml_private.version_catalog(s->>'catalogVersion')#>'{sourceCatalog,characters}') ? (x#>>'{}'))),'已选角色无效或重复');
 if s->>'catalogVersion' in ('web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then for a in select (v#>>'{}')::int from ml_private.arr(s->'order') v where s->'selected'->(v#>>'{}')::int<>'null'::jsonb loop perform ml_private.need(ml_private.p3d_spawn_pool(jsonb_set(s,array['selected',a::text],'null'),jsonb_build_array(s->'selected'->a)) @> jsonb_build_array(s->'selected'->a),'已选角色超过出生地区容量');end loop;end if;for i in 0..3 loop a:=(s->'order'->>i)::int;perform ml_private.need((s->'selected'->a<>'null'::jsonb)=(i<(s->>'cursor')::int),'选角顺序不一致');end loop;
 for pool in select value from jsonb_each(s->'pools') loop perform ml_private.need(not exists(select 1 from ml_private.arr(pool) x where chosen @> jsonb_build_array(x)),'已选角色没有移出牌池');end loop;
 if s->>'status'='complete' then perform ml_private.need((s->>'cursor')::int=4 and o='null'::jsonb,'选角结束状态无效');
 else
  perform ml_private.need((s->>'cursor')::int between 0 and 3 and o<>'null'::jsonb and o->'actor'=s->'order'->(s->>'cursor')::int and o->'id'=s->'offerSerial' and jsonb_array_length(o->'candidates')=3 and (select count(distinct x) from ml_private.arr(o->'candidates') x)=3 and ml_private.p3d_spawn_pool(s,s->'pools'->(s->'teams'->>(o->>'actor')::int)) @> (o->'candidates') and (o->>'deadline')::double precision<'Infinity'::double precision,'当前候选或选择期限无效');
 end if;
end $$;
create or replace function ml_private.create_draft(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare catalogv text:=coalesce(setup->>'catalogVersion','web-v0.1.4');s jsonb; pool jsonb; i integer; a integer; overlap_count integer; key text; begin
 perform ml_private.need(jsonb_typeof(setup)='object','选角输入必须为对象');perform ml_private.need(catalogv in ('web-v0.1.4','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19'),'选角目录版本无效');
 perform ml_private.need(at>=0 and at<'Infinity'::double precision,'选角时钟无效');
 perform ml_private.need(jsonb_typeof(setup->'order')='array' and (select jsonb_agg(x order by x) from ml_private.arr(setup->'order') x)='[0,1,2,3]'::jsonb,'选角需要四个固定座位的行动顺序');
 perform ml_private.need(setup->>'mode' in ('ffa','team'),'选角模式无效');perform ml_private.need(jsonb_typeof(setup->'teams')='array' and jsonb_array_length(setup->'teams')=4,'选角阵营需要四个座位');
 if setup->>'mode'='team' then perform ml_private.need((select count(*) from ml_private.arr(setup->'teams') x where x='"机械猴子"')=2 and (select count(*) from ml_private.arr(setup->'teams') x where x='"帝汶家族"')=2,'选角须先分配两名机械猴子和两名帝汶家族');
 else perform ml_private.need(setup->'teams'='["S1","S2","S3","S4"]'::jsonb,'各自为战的选角身份无效');end if;
 perform ml_private.need(jsonb_typeof(setup->'pools')='object','角色阵营池尚未完整配置');
 perform ml_private.need((select jsonb_agg(k order by k) from jsonb_object_keys(setup->'pools') k)=(select jsonb_agg(x order by x) from (select distinct x from ml_private.arr(setup->'teams') x) t),'角色阵营池尚未完整配置');
 for pool in select value from jsonb_each(setup->'pools') loop
  perform ml_private.need(jsonb_typeof(pool)='array' and jsonb_array_length(pool)>=3 and (select count(distinct x) from ml_private.arr(pool) x)=jsonb_array_length(pool) and not exists(select 1 from ml_private.arr(pool) x where not ((ml_private.version_catalog(catalogv)#>'{sourceCatalog,characters}') ? (x#>>'{}'))),'角色池必须包含至少三个不同的已登记角色');
 end loop;
 for i in 0..3 loop
  a:=(setup->'order'->>i)::int;pool:=setup->'pools'->(setup->'teams'->>a);
  select count(*) into overlap_count from jsonb_array_elements(setup->'order') with ordinality t(other,n) where n<=i and exists(select 1 from ml_private.arr(setup->'pools'->(setup->'teams'->>(other#>>'{}')::int)) x where pool @> jsonb_build_array(x));
  perform ml_private.need(jsonb_array_length(pool)>=3+overlap_count,'角色池可能不足三个候选，请补齐阵营或中立分配');
 end loop;
 perform ml_private.need(jsonb_typeof(setup->'random'->'seed')='number' and (setup#>>'{random,seed}')::numeric=trunc((setup#>>'{random,seed}')::numeric) and (setup#>>'{random,seed}')::numeric between 0 and 4294967295,'选角随机源无效');
 s:=jsonb_build_object('mode',setup->'mode','order',setup->'order','teams',setup->'teams','pools',setup->'pools','random',setup->'random','version','draft-v1','catalogVersion',catalogv,'revision',0,'time',at,'status','choosing','cursor',0,'offerSerial',0,'offer',null,'selected','[null,null,null,null]'::jsonb,'events','[]'::jsonb,'requests','[]'::jsonb);
 perform ml_private.need(ml_private.p3d_spawn_safe(s),'出生容量过滤后角色池可能不足三个候选，请补齐角色池');s:=ml_private.draft_offer(s,at);perform ml_private.validate_draft(s);return s;
end $$;
create or replace function ml_private.cave_ending(s jsonb,a integer) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a;countn integer;paid integer;begin
 s:=s||jsonb_build_object('_hits','[]'::jsonb);
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ((p->>'hp')::int<=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not ml_private.stage4_on_board(s,a)) then return s;end if;
 countn:=case when ml_private.region_at(s->>'version',p->>'cell')='山洞' then (s#>>array['classic','caveEnds',a::text])::int+1 else 0 end;
 s:=jsonb_set(s,array['classic','caveEnds',a::text],to_jsonb(case when countn>=3 then 0 else countn end));
 if countn<3 or ml_private.stage4_ignore_location(s,a) then return s;end if;
 paid:=least(2,(p->>'ap')::int);s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-paid));
 s:=ml_private.emit(s,'cave','S'||(a+1)||' 山洞连续停留3个个人回合，野人扣'||paid||'AP并造成1伤害',jsonb_build_object('actor',a,'ap',paid,'amount',1));
 return s||jsonb_build_object('_hits',jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',null,'category','environment')));
end $$;
create or replace function ml_private.stage3_equipped(s jsonb,a integer,definition text) returns boolean language sql immutable
set search_path=pg_catalog,ml_private as $$ select exists(select 1 from ml_private.arr(ml_private.p3h_gear_cards(s,a)) c where ml_private.stage4_equipment_definition(s,c#>>'{}')=definition and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.character_effect_allowed(ml_private.p3h_gear_source(s,a,c#>>'{}')||jsonb_build_object('origin','equipment'),a,s#>>array['players',a::text,'character']))) $$;
create or replace function ml_private.stage3_mount_blocked(s jsonb,a integer) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select not ml_private.p3f_can_move(s,a) or (s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>array['stage4','tongBlocked',a::text] is not null and ml_private.stage4_board_effect(s,a,s#>array['stage4','tongBlocked',a::text])) or
 exists(select 1 from ml_private.arr(ml_private.p3h_gear_cards(s,a)) c where (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['cards',split_part(c#>>'{}','#',1),'slot']='mount')
 and exists(select 1 from ml_private.arr(s#>'{stage3,horseLocks}') c where (c#>>'{}')::int<>a and (s#>>array['players',c#>>'{}','hp'])::int>0 and ml_private.character_effect_allowed(s#>array['stage3','horseSources',c#>>'{}'],a,s#>>array['players',a::text,'character']) and (s#>>array['players',a::text,'character']<>'character-006' or s#>array['stage3','horseSources',c#>>'{}','actor']=to_jsonb(a) or s#>>array['stage3','horseSources',c#>>'{}','faction']='机械猴子')) $$;
create or replace function ml_private.stage3_can_enter(s jsonb,a integer,cell text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage4_board_entry(s,a,cell) else (
 (ml_private.runtime_data('web-v0.1.5','map') ? cell) and not (ml_private.stage3_equipped(s,a,'basic-063') and ml_private.runtime_data('web-v0.1.5','map')#>>array[cell,'terrain']='water')) end $$;
create or replace function ml_private.stage3_turn_start(s jsonb,a integer) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare gear text;prior jsonb;begin s:=ml_private.p3h_ren_start(s,a); s:=ml_private.p3h_cooperate_start(s,a); s:=ml_private.p3h_circle_start(s,a);
 s:=ml_private.stage3_turn_start_before_stage4(s,a);
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then
  for gear in select v#>>'{}' from ml_private.arr(s#>array['stage3','equipment',a::text]) v loop if ml_private.stage4_equipment_definition(s,gear)='basic-060' then prior:=s#>array['stage4','watches',gear];s:=jsonb_set(s,array['stage4','watches',gear],jsonb_build_object('current',s#>array['players',a::text,'cell'],'previous',prior->'current','usedTurn',null));end if;end loop;
  s:=ml_private.p3h_gear_watch_start(s,a);s:=jsonb_set(s,'{stage4,gearMarks}','{}');s:=jsonb_set(s,'{stage4,tongBlocked}',(s#>'{stage4,tongBlocked}')-a::text);if s#>array['stage4','tongPending',a::text] is not null then s:=jsonb_set(s,array['stage4','tongBlocked',a::text],s#>array['stage4','tongPending',a::text]);end if;s:=jsonb_set(s,'{stage4,tongPending}',(s#>'{stage4,tongPending}')-a::text);
  s:=jsonb_set(s,'{stage4,costs}',ml_private.stage4_cost_turn(s#>'{stage4,costs}',(s#>>'{stage3,turn}')::bigint));
  s:=jsonb_set(s,array['stage4','drawBlocked',a::text],s#>array['stage4','downPending',a::text]);
  s:=jsonb_set(s,array['stage4','downPending',a::text],'false');s:=ml_private.stage4_expire_board(s,a);
 end if;return s;
end $$;
create or replace function ml_private.stage3_turn_end(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare r jsonb:=s->'stage3'; b text:=a::text; begin
 r:=jsonb_set(r,array['ends',b],to_jsonb((r#>>array['ends',b])::int+1));r:=jsonb_set(r,'{completedTurn}',r->'turn');
 r:=jsonb_set(r,array['previousBasic',b],to_jsonb((r#>>array['basicUsed',b])::int>0));r:=jsonb_set(r,array['jjFree',b],'false');
 if (s#>>array['players',b,'hp'])::int>0 and ml_private.stage3_equipped(s,a,'basic-067') and r#>array['voluntaryMoved',b]='false'::jsonb and not (r->'horseLocks' @> jsonb_build_array(a)) then r:=jsonb_set(r,'{horseLocks}',(r->'horseLocks')||jsonb_build_array(a));r:=jsonb_set(r,array['horseSources',b],(select ml_private.p3h_gear_source(s,a,c#>>'{}')||jsonb_build_object('origin','equipment') from ml_private.arr(ml_private.p3h_gear_cards(s,a)) c where ml_private.stage4_equipment_definition(s,c#>>'{}')='basic-067' limit 1));end if;
 return ml_private.p3h_cooperate_cleanup(ml_private.p3c_end(jsonb_set(s,'{stage3}',r),a));
end $$;
create or replace function ml_private.stage3_card_cost(s jsonb,a integer,card text,random_cost integer default null) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',split_part(card,'#',1)]; n integer; effect jsonb; begin
 perform ml_private.need(d is not null,'卡牌不在阶段三牌池');n:=case when d->>'randomCost'='true' then random_cost else (d->>'cost')::int end;
 perform ml_private.need(n is not null and (n>=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and n>=-1),'请先锁定该实体牌的随机费用');
 effect:=jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers','[]'::jsonb);
 if n>0 and ((p->>'character'='character-006' and ml_private.p3h_active_allowed(s,a) and ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',d->>'id','tags'] ? '帝汶') or (p->>'character'='character-048' and d->>'id' in ('basic-054','basic-063','basic-066','basic-067','basic-071','basic-072')) or s#>>array['stage3','jjFree',a::text]='true') then
 n:=0;effect:=jsonb_set(effect,'{roleModifiers}',jsonb_build_array(jsonb_build_object('actor',a,'kind','cost')));end if;
 return ml_private.p3g_prime_quote(s,a,ml_private.p3g_free_quote(s,a,d->>'id',n,effect));
end $$;
create or replace function ml_private.stage3_gain_ap(s jsonb,a integer,amount integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; collector integer; taken integer:=0; result jsonb; begin
 perform ml_private.need(amount>=0,'新增AP必须为非负整数');
 if (p->>'hp')::int<=0 then return s||jsonb_build_object('_gain',jsonb_build_object('gained',0,'collector',null,'taken',0));end if;
 select (q->>'seat')::int into collector from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(q->>'seat')::int) and not ml_private.stage3_equipped(s,a,'basic-065')) and q->>'character'='character-043' and ml_private.p3h_active_allowed(s,(q->>'seat')::int) and (q->>'seat')::int<>a and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',q->'seat','roleModifiers','[]'::jsonb),a,p->>'character') limit 1;
 if collector is not null then taken:=least(amount,greatest(0,(p->>'ap')::int+amount-7));end if;
 s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((p->>'ap')::int+amount-taken));
 if collector is not null then s:=jsonb_set(s,array['players',collector::text,'ap'],to_jsonb((s#>>array['players',collector::text,'ap'])::int+taken));end if;
 return s||jsonb_build_object('_gain',jsonb_build_object('gained',amount-taken,'collector',case when taken>0 then collector else null end,'taken',taken));
end $$;
create or replace function ml_private.stage3_overflow(s jsonb,action_order jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare collector integer; a jsonb; p jsonb; n integer; result jsonb:='[]'; begin
 select (q->>'seat')::int into collector from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and q->>'character'='character-043' and ml_private.p3h_active_allowed(s,(q->>'seat')::int) limit 1;if collector is null then return result;end if;
 for a in select * from ml_private.arr(action_order) loop p:=s->'players'->(a#>>'{}')::int;n:=jsonb_array_length(p->'hand')-(p->>'hp')::int;
 if (p->>'hp')::int>0 and (a#>>'{}')::int<>collector and n>0 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',collector,'roleModifiers','[]'::jsonb),(a#>>'{}')::int,p->>'character') then result:=result||jsonb_build_array(jsonb_build_object('actor',a,'count',n,'collector',collector));end if;end loop;return result;
end $$;
create or replace function ml_private.stage3_death(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare r jsonb:=s->'stage3'; c jsonb; locks jsonb; begin
 r:=jsonb_set(r,array['deathTurns',a::text],r->'turn');r:=jsonb_set(r,array['jjFree',a::text],'false');r:=jsonb_set(r,array['jjExposed',a::text],'false');
 for c in select * from ml_private.arr(r#>array['equipment',a::text]) loop s:=ml_private.p3h_gear_forget(s,c#>>'{}');s:=ml_private.exercise_discard(s,jsonb_build_array(c));if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,array['stage4','terrainIgnore',a::text],'false');s:=jsonb_set(s,'{stage4,watches}',(s#>'{stage4,watches}')-(c#>>'{}'));s:=jsonb_set(s,'{stage4,copies}',(s#>'{stage4,copies}')-(c#>>'{}'));s:=jsonb_set(s,'{stage4,durability}',(s#>'{stage4,durability}')-(c#>>'{}'));end if;r:=jsonb_set(r,'{equipmentSources}',(r->'equipmentSources')-(c#>>'{}'));end loop;
 r:=jsonb_set(r,array['equipment',a::text],'[]');select coalesce(jsonb_agg(x),'[]') into locks from ml_private.arr(r->'horseLocks') x where (x#>>'{}')::int<>a;
 r:=jsonb_set(r,'{horseLocks}',locks);r:=jsonb_set(r,'{horseSources}',(r->'horseSources')-a::text);if ml_private.p3g_enabled(s) then r:=jsonb_set(r,'{g}',s#>'{stage3,g}');end if;if ml_private.p3h_enabled(s) then r:=jsonb_set(r,'{h}',s#>'{stage3,h}');end if;return ml_private.p3h_gear_refresh(jsonb_set(s,'{stage3}',r));
end $$;
create or replace function ml_private.stage3_revival_cells(s jsonb,a integer,farm_closed boolean) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; region text; result jsonb; begin
 if (p->>'hp')::int>0 or s#>array['stage3','deathTurns',a::text]='null'::jsonb or (s#>>'{stage3,completedTurn}')::int>(s#>>array['stage3','deathTurns',a::text])::int then return '[]';end if;
 region:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['characters',p->>'character','spawnRegion'];
 if ml_private.p3f_enabled(s) then if (p->>'maxHp')::int<=0 or (s#>>array['stage3','deathTurns',a::text])::int=-1 then return '[]';end if;region:=ml_private.version_catalog(s->>'version')#>>array['sourceCatalog','characters',p->>'character','spawnRegion'];end if;
 if ml_private.p3h_leap_role(s,a) then region:=ml_private.region_at(s->>'version',s#>>array['stage3','h','birth',a::text]);end if;select coalesce(jsonb_agg(c->'id' order by ord),'[]') into result from jsonb_array_elements(ml_private.runtime_data('web-v0.1.5','cells')) with ordinality t(c,ord) where (s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or not ml_private.classic_native(s,a) or not ml_private.stage4_board_water(s,c->>'id',a) or jsonb_array_length(ml_private.playtest_nearest_shore(jsonb_set(jsonb_set(s,array['players',a::text,'hp'],'1'),array['players',a::text,'cell'],c->'id'),a))>0) and c->>'region'=region and not (farm_closed and region='高唐农场') and not exists(select 1 from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and ml_private.p3h_blocks(s,a,(q->>'seat')::int) and q->>'cell'=c->>'id');return result;
end $$;
create or replace function ml_private.stage3_revive(s jsonb,a integer,cell text,farm_closed boolean) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 perform ml_private.need(ml_private.stage3_revival_cells(s,a,farm_closed) ? cell,'复活已过期或出生地区没有合法空格');
 s:=jsonb_set(s,array['players',a::text],(s->'players'->a)||jsonb_build_object('hp',1,'ap',0,'shield',0,'hand','[]'::jsonb,'cell',cell,'eliminated',null));return ml_private.p3h_gear_refresh(jsonb_set(s,array['stage3','deathTurns',a::text],'null'));
end $$;
create or replace function ml_private.stage3_equipment_options(s jsonb,a integer,card text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare definition text:=split_part(card,'#',1); d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',definition]; cards jsonb; begin
 if d is null or d->>'type'<>'equipment' or (not ml_private.p3g_prime(s,a) and case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then exists(select 1 from ml_private.arr(s#>array['stage3','equipment',a::text]) item where split_part(item#>>'{}','#',1)=definition) else ml_private.stage3_equipped(s,a,definition) end) then return '{"allowed":false,"required":false,"cards":[]}'::jsonb;end if;
 select coalesce(jsonb_agg(c),'[]') into cards from ml_private.arr(s#>array['stage3','equipment',a::text]) c where (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['cards',split_part(c#>>'{}','#',1),'slot']=d->>'slot';
 return jsonb_build_object('allowed',true,'required',jsonb_array_length(cards)>=case when ml_private.p3g_prime(s,a) or d->>'slot'='hand' then 2 else 1 end,'cards',cards);
end $$;
create or replace function ml_private.stage3_card_allowed(s jsonb,target integer,card text,effect jsonb) returns boolean language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->target; tags jsonb; begin
 if ml_private.p3h_small(s,target) and split_part(card,'#',1)='basic-009' then return false;end if;if (s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['stage4','offMap',target::text]='true') or p is null or not ml_private.character_effect_allowed(effect,target,p->>'character') then return false;end if;
 if s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and p->>'character'='character-006' and (effect->>'actor')::int<>target and effect->>'faction'<>'机械猴子' then return false;end if;
 tags:=ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',split_part(card,'#',1),'tags'];
 if ml_private.p3_yinghao_immune(s,target,card) then return false;end if;
 if p->>'character'='character-005' and tags ? '建民' then return false;end if;return true;
end $$;
create or replace function ml_private.stage3_role_targets(s jsonb,a integer,origin text) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(p->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality t(p,ord) where (origin<>'role-active' or ml_private.p3h_active_allowed(s,a)) and (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and (p->>'seat')::int<>a and ml_private.character_effect_allowed(jsonb_build_object('origin',origin,'actor',a,'roleModifiers','[]'::jsonb),(p->>'seat')::int,p->>'character') $$;
create or replace function ml_private.stage3_jj_targets(s jsonb,a integer,card text,targets jsonb,effect jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',split_part(card,'#',1)]; jj integer; begin
 if d is null or d->>'type'='equipment' or (d->>'type'='response' and not (d->>'id'='basic-002' and (s#>>array['players',a::text,'character']='character-023' or s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and coalesce((s#>>array['stage4','tea',a::text])::boolean,false)))) or d->>'id'='basic-037' then return jsonb_build_object('targets',targets,'effect',effect);end if;
 if s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and d->>'type'<>'attack' and d->>'id'<>'basic-002' then return jsonb_build_object('targets',targets,'effect',effect);end if;
 select (p->>'seat')::int into jj from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and p->>'character'='character-003' and (p->>'seat')::int<>a and s#>>array['stage3','jjExposed',p->>'seat']='true' limit 1;
 if jj is null or not ml_private.p3g_card_target_allowed(s,a,jj,d->>'id') or (s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and (not ml_private.stage4_on_board(s,jj) or (d->>'type'='attack' or s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and d->>'id'='basic-002') and coalesce(d->>'group','false')<>'true' and (ml_private.stage4_single_protected(s,a,jj) or ml_private.stage4_lmm_target(s,a,targets) is not null))) or targets @> jsonb_build_array(jj) then return jsonb_build_object('targets',targets,'effect',effect);end if;
 effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',jj,'kind','target')));return jsonb_build_object('targets',targets||jsonb_build_array(jj),'effect',effect);
end $$;
create or replace function ml_private.stage3_monkey_targets(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; boost boolean:=p->>'character'='character-045'; result jsonb; begin
 if not boost and (case when s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then not ml_private.location_card_allowed(s->>'version',p->>'cell','basic-010') and not (coalesce((s#>>array['stage4','terrainIgnore',a::text])::boolean,false) and ml_private.stage3_equipped(s,a,'basic-069')) else ml_private.runtime_data('web-v0.1.5','map')#>>array[p->>'cell','region'] in ('教学楼','秀松苑') end) then return '[]';end if;
 select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(q->>'seat')::int)) and not ml_private.p3_yinghao_immune(s,(q->>'seat')::int,'basic-010') and (q->>'seat')::int<>a and (s->>'mode'='ffa' or q->'team'<>p->'team') and not (q->>'character'='character-027' and jsonb_array_length(q->'hand')=1) and (not ml_private.p3c_feather(s,a) or q->>'character' not in ('character-026','character-044')) and (boost or ml_private.p3c_feather(s,a) or ml_private.stage3_same_near(p->>'cell',q->>'cell'));return result;
end $$;
create or replace function ml_private.stage3_ledger_candidates(s jsonb,xie integer,card_user integer,participants jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->xie; result jsonb:='[]'; a jsonb; q jsonb; begin
 if not ml_private.p3h_active_allowed(s,xie) or (p->>'hp')::int<=0 or p->>'character'<>'character-044' then return result;end if;
 for a in select * from ml_private.arr(jsonb_build_array(card_user)||participants) loop q:=s->'players'->(a#>>'{}')::int;
 if (a#>>'{}')::int<>xie and (q->>'hp')::int>0 and not (result @> jsonb_build_array(a)) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',xie,'roleModifiers','[]'::jsonb),(a#>>'{}')::int,q->>'character') and (ml_private.runtime_data('web-v0.1.5','map')#>>array[q->>'cell','region']=ml_private.runtime_data('web-v0.1.5','map')#>>array[p->>'cell','region'] or ml_private.distance_for_version('web-v0.1.5',p->>'cell',q->>'cell')=1) then result:=result||jsonb_build_array(a);end if;end loop;return result;
end $$;
create or replace function ml_private.stage3_empty_entry(s jsonb,a integer,cell text,ignored jsonb default '[]') returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select ml_private.p3f_preview_move(s,a,cell) and (s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],cell,ignored) is not null) and coalesce(ml_private.runtime_data('web-v0.1.5','map') ? cell and not (coalesce((s->>'farmClosed')::boolean,false) and ml_private.runtime_data('web-v0.1.5','map')#>>array[cell,'region']='高唐农场') and ml_private.stage3_can_enter(s,a,cell) and not exists(select 1 from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and ml_private.p3h_blocks(s,a,(p->>'seat')::int) and p->>'cell'=cell and not (ignored @> jsonb_build_array(p->'seat'))),false) $$;
create or replace function ml_private.stage3_elbow_targets(s jsonb,a integer,converted boolean) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(t order by ord),'[]') from jsonb_array_elements(ml_private.stage3_role_targets(s,a,case when converted then 'role-active' else 'role-locked' end)) with ordinality x(t,ord) where ml_private.p3g_card_target_allowed(s,a,(t#>>'{}')::int,'basic-002') and (s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or not ml_private.stage4_single_protected(s,a,(t#>>'{}')::int)) and s#>>array['players',a::text,'character']='character-023' and ml_private.runtime_data('web-v0.1.5','map')#>>array[s#>>array['players',a::text,'cell'],'region']=ml_private.runtime_data('web-v0.1.5','map')#>>array[s#>>array['players',t#>>'{}','cell'],'region'] $$;
create or replace function ml_private.stage3_begin_card(s jsonb,a integer,card text,definition text,targets jsonb,effect jsonb,at double precision,response_to integer default null) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare flow jsonb:=s->'cardStack'; parent jsonb:=(flow->'stack')->-1; easy integer; pending jsonb;begin at:=ml_private.p3g_now(s,at);
 perform ml_private.need(at>=0 and at<'Infinity'::double precision,'卡牌窗口时钟无效');
 perform ml_private.need(s->'resolving' ? card and not exists(select 1 from ml_private.arr(flow->'stack') c where c->>'card'=card),'待结算实体牌无效');
 if response_to is not null then perform ml_private.need((parent->>'serial')::int=response_to and parent->'counter'='null'::jsonb,'父牌尚不可响应');end if;
 select (p->>'seat')::int into easy from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and p->>'character'='character-002' and ml_private.p3h_active_allowed(s,(p->>'seat')::int) and (p->>'ap')::int>=1 limit 1;
 pending:=jsonb_build_object('serial',(flow->>'serial')::int+1,'actor',a,'card',card,'definition',definition,'targets',targets,'effect',effect,'cancelled','[]'::jsonb,'elbows','[]'::jsonb,'countered',false,'counter',case when easy is null then null else jsonb_build_object('actor',easy,'deadline',at+case when s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 30000 else 10000 end) end,'responseTo',response_to,'responseActor',case when response_to is null then null else a end);
 if ml_private.p3g_prime(s,a) and (ml_private.p3h_active_allowed(s,a) or s->>'_hPrimeSecond'='true') then pending:=pending||jsonb_build_object('g',jsonb_build_object('copy',1,'targets',targets));if ml_private.rule_card(s,definition)->>'type'='equipment' then s:=ml_private.p3g_begin_pair(s,card);end if;end if;s:=ml_private.p3c_mark_card(s,a);
 s:=jsonb_set(s,'{cardStack}',jsonb_build_object('serial',pending->'serial','stack',(flow->'stack')||jsonb_build_array(pending)));return ml_private.p3f_cast_heal(s,a,definition);
end $$;
create or replace function ml_private.stage3_counter_card(s jsonb,a integer,accept boolean,at double precision,rolled integer) returns jsonb language plpgsql immutable
set search_path=pg_catalog,ml_private as $$ declare stack jsonb:=s#>'{cardStack,stack}'; position text:=(jsonb_array_length(stack)-1)::text; pending jsonb:=stack->-1; counter_window jsonb:=pending->'counter'; p jsonb:=s->'players'->a; result jsonb; begin
 perform ml_private.need(counter_window<>'null'::jsonb and (counter_window->>'actor')::int=a,'不是当前反制者');perform ml_private.need(at<=(counter_window->>'deadline')::double precision,'反制窗口已过期');
 if not accept or not ml_private.p3h_active_allowed(s,a) or at=(counter_window->>'deadline')::double precision then pending:=jsonb_set(pending,'{counter}','null');result:='{"attempted":false,"roll":null,"cancelled":false,"done":true}';
 else
  perform ml_private.need((p->>'hp')::int>0 and p->>'character'='character-002' and (p->>'ap')::int>=1,'反制费用不足');perform ml_private.need(rolled between 1 and 6,'反制骰子无效');
  s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((p->>'ap')::int-1));pending:=jsonb_set(pending,'{countered}',to_jsonb(rolled>=3));
  if rolled>=3 or (p->>'ap')::int=1 then pending:=jsonb_set(pending,'{counter}','null');end if;
  result:=jsonb_build_object('attempted',true,'roll',rolled,'cancelled',pending->'countered','done',pending->'counter'='null'::jsonb);
 end if;
 return jsonb_set(s,array['cardStack','stack',position],pending)||jsonb_build_object('_counterResult',result);
end $$;
create or replace function ml_private.stage3_close_card(s jsonb) returns jsonb language plpgsql immutable
set search_path=pg_catalog,ml_private as $$ declare cards jsonb:=s#>'{cardStack,stack}';c jsonb:=cards->-1;parent jsonb:=cards->-2;begin if ml_private.p3g_enabled(s) and s#>'{cardStack,stack,-1,g}' is not null then return ml_private.p3g_close_card(s);end if;
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or c#>'{stage4,counter}' is null then return ml_private.stage3_close_card_before_stage4(s);end if;
 perform ml_private.need(c->'counter'='null'::jsonb,'反制尚未结束');perform ml_private.need(parent->'serial'=c->'responseTo','响应父牌已过期');
 if c->>'countered'<>'true' and c#>>'{stage4,counterEffective}'='true' then cards:=jsonb_set(cards,array[(jsonb_array_length(cards)-2)::text,'countered'],'true');end if;
 s:=jsonb_set(s,'{cardStack,stack}',cards-(jsonb_array_length(cards)-1));s:=jsonb_set(s,'{resolving}',(s->'resolving')-(c->>'card'));
 return ml_private.exercise_discard(s,jsonb_build_array(c->'card'))||jsonb_build_object('_closed',c);
end $$;
create or replace function ml_private.create_game_before_stage3(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',c->'faction','hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
 s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
create or replace function ml_private.pump_before_stage3(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare task jsonb; a integer; p jsonb; countn integer; cards jsonb; kind text; cells jsonb; cursor integer; guard integer:=0; begin
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' and jsonb_array_length(s->'queue')>0 loop
  guard:=guard+1; perform ml_private.need(guard<200,'内部流程未收敛'); task:=s->'queue'->0; s:=jsonb_set(s,'{queue}',(s->'queue')-0); a:=coalesce((task->>'actor')::int,(s->>'active')::int); p:=s->'players'->a;
  case task->>'kind'
   when 'water' then if ml_private.classic_owes_water(s,a) then s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
   when 'classic-start' then
    for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);if (p->>'ap')::int<5 and (s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or p->>'character'<>'character-031') then p:=p||jsonb_build_object('ap',(p->>'ap')::int+3);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(p->>'ap'));end if;s:=ml_private.put_player(s,a,p);end if;end loop;
    s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when (s#>>'{classic,farmClosed}')::boolean then '；高唐农场已封闭' else '' end);s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','after-env'))||(s->'queue'));
   when 'round-next' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
   when 'walk' then s:=ml_private.classic_walk(s,coalesce(task->'path','[]'),at);
   when 'after-env' then s:=ml_private.finish(s,false,at); if s->>'phase'<>'over' then cursor:=0; while (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1; end loop; s:=s||jsonb_build_object('cursor',cursor,'queue',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue')); end if;
   when 'turn-start' then
    if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));end if;
    s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at)); p:=p||jsonb_build_object('moved',false,'attacks',0); s:=ml_private.put_player(s,a,p);
    if p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP'); end if;
    if ml_private.stage4_location_ap(s,a)>(p->>'ap')::int then p:=p||jsonb_build_object('ap',ml_private.stage4_location_ap(s,a)); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(p->>'ap')); end if;
    s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动'); if (s->>'round')::int>1 then s:=ml_private.draw(s,a,ml_private.stage4_location_draw(s,a)); end if;
    s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','action'))||(s->'queue')); if p->>'character'='character-027' then s:=ml_private.select_choice(s,'draw-start',a,at); end if;
   when 'action' then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at);
   when 'end-draw' then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind',case when s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 'cave-end' else 'discard' end))||(s->'queue')); if p->>'character'='character-027' and (p->>'hp')::int>0 and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at); end if;
   when 'cave-end' then s:=ml_private.cave_ending(s,a);if jsonb_array_length(s->'_hits')>0 then s:=ml_private.damage(s,s->'_hits',true);s:=jsonb_set(s,'{queue}',(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a))||(s->'queue'));s:=s-'_triggers';else s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a))||(s->'queue'));end if;s:=s-'_hits';
   when 'cave-after' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','discard','actor',a))||(s->'queue'));end if;
   when 'discard' then countn:=jsonb_array_length(p->'hand')-greatest(0,floor((p->>'hp')::numeric)::int); s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand')); end if;
   when 'next' then s:=ml_private.next_turn(s,at);
   when 'response' then if not (s#>'{attack,cancelled}' @> jsonb_build_array(a)) and s->'attack'<>'null'::jsonb and (p->>'hp')::int>0 then
    select coalesce(jsonb_agg(c),'[]') into cards from ml_private.arr(p->'hand') c where ((ml_private.rule_card(s,c#>>'{}')->>'id'='basic-001' and (s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.rule_card(s,s#>>'{attack,card}')->>'id'<>'basic-009')) or (ml_private.rule_card(s,c#>>'{}')->>'id'='basic-002' and ml_private.rule_card(s,s#>>'{attack,card}')->>'id'='basic-008')) and (p->>'ap')::int>=(ml_private.rule_card(s,c#>>'{}')->>'cost')::int;
    if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',a,at,jsonb_build_object('cards',cards)); end if; end if;
   when 'resolve' then s:=ml_private.resolve_attack(s);
   when 'cleanup' then s:=ml_private.exercise_discard(s,s->'resolving')||jsonb_build_object('resolving','[]'::jsonb,'attack',null); s:=ml_private.finish(s,false,at);
    if s->>'phase'<>'over' then if (s->'players'->(s->>'active')::int->>'hp')::int>0 then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at); else s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); end if; end if;
   when 'trigger' then
    if (p->>'hp')::int<=0 then continue; end if; kind:=task->>'trigger';
    if kind='lemon-reward' then if task ? 'source' and not (s->'players'->(task->>'source')::int->'rewarded' @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',task->'source')); end if;
    elsif not (p->>'skillUsed')::boolean then
     if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at); end if;
     if kind='teleport' then cells:=ml_private.teleport_cells(s,a); if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells)); end if; end if;
    end if;
   else raise exception '未知内部任务';
  end case;
 end loop; return s;
end $$;
create or replace function ml_private.damage_before_stage3(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare h jsonb; p jsonb; a integer; src integer; blocked integer; loss integer; injured jsonb:='[]'; triggers jsonb:='[]'; begin
 s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));
 for h in select * from ml_private.arr(hits) loop
  a:=(h->>'target')::int; p:=s->'players'->a; if (p->>'hp')::int<=0 or (h->>'amount')::int<=0 then continue; end if;
  blocked:=case when environment and s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 0 else least((p->>'shield')::int,(h->>'amount')::int) end; loss:=least((p->>'hp')::int,(h->>'amount')::int-blocked);
  p:=p||jsonb_build_object('shield',(p->>'shield')::int-blocked,'hp',(p->>'hp')::int-loss); s:=ml_private.put_player(s,a,p); src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s->'players'->src->>'damage')::int+loss,'kills',(s->'players'->src->>'kills')::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end)); end if;
  s:=ml_private.emit(s,'damage',ml_private.name(s,a)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',s->'batch'));
  if loss>0 then injured:=injured||jsonb_build_array(h||jsonb_build_object('loss',loss)); end if;
 end loop;
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=ml_private.exercise_discard(s,p->'hand'); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop; return s||jsonb_build_object('_triggers',triggers);
end $$;
create or replace function ml_private.finish_before_stage3(s jsonb,forced boolean,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare groups jsonb:='[]'; rows jsonb:='[]'; ids jsonb; p jsonb; rowj jsonb; a integer; alive_count integer; hp integer; max_hp integer; kills integer; dmg integer; elim bigint; survivors integer:=0; i integer; j integer; cmp bigint; leftj jsonb; rightj jsonb; winners jsonb:='[]'; rankn integer; tied boolean; begin
 if s->>'mode'='ffa' then for a in 0..3 loop groups:=groups||jsonb_build_array(jsonb_build_array(a)); end loop;
 else groups:=jsonb_build_array((select jsonb_agg(member->'seat') from ml_private.arr(s->'players') member where member->>'team'='A'),(select jsonb_agg(member->'seat') from ml_private.arr(s->'players') member where member->>'team'='B')); end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then select coalesce(jsonb_agg(g),'[]') into groups from ml_private.arr(groups) g where g<>'null'::jsonb and g<>'[]'::jsonb;end if;
 for ids in select * from ml_private.arr(groups) loop
  alive_count:=0; hp:=0; max_hp:=0; kills:=0; dmg:=0; elim:=0;
  for a in select ml_private.n(x)::int from ml_private.arr(ids) x loop p:=s->'players'->a;
   alive_count:=alive_count+case when (p->>'hp')::int>0 then 1 else 0 end; hp:=hp+(p->>'hp')::int; max_hp:=max_hp+(p->>'maxHp')::int; kills:=kills+(p->>'kills')::int; dmg:=dmg+(p->>'damage')::int; elim:=greatest(elim,coalesce((p->>'eliminated')::bigint,1000000000000000)); end loop;
  if alive_count>0 then survivors:=survivors+1; end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('label',case when s->>'mode'='ffa' then ml_private.name(s,(ids->>0)::int) else (s->'players'->(ids->>0)::int->>'team')||'队' end,'players',ids,'rank',0,'alive',alive_count,'hp',hp,'maxHp',max_hp,'kills',kills,'damage',dmg,'_elim',elim));
 end loop;
 if not forced and survivors>1 then return s; end if;
 -- Stable insertion sort, using exact integer cross multiplication for HP ratios.
 for i in 1..jsonb_array_length(rows)-1 loop j:=i;
  while j>0 loop leftj:=rows->(j-1); rightj:=rows->j;
   if (leftj->>'alive')::int>0 and (rightj->>'alive')::int>0 then
    cmp:=(rightj->>'alive')::bigint-(leftj->>'alive')::bigint;
    if cmp=0 then cmp:=(rightj->>'hp')::bigint*(leftj->>'maxHp')::bigint-(leftj->>'hp')::bigint*(rightj->>'maxHp')::bigint; end if;
    if cmp=0 then cmp:=(rightj->>'kills')::bigint-(leftj->>'kills')::bigint; end if;
    if cmp=0 then cmp:=(rightj->>'damage')::bigint-(leftj->>'damage')::bigint; end if;
   elsif (leftj->>'alive')::int>0 then cmp:=-1; elsif (rightj->>'alive')::int>0 then cmp:=1; else cmp:=(rightj->>'_elim')::bigint-(leftj->>'_elim')::bigint; end if;
   exit when cmp<=0;
   rows:=jsonb_set(rows,array[(j-1)::text],rightj); rows:=jsonb_set(rows,array[j::text],leftj); j:=j-1;
  end loop;
 end loop;
 for i in 0..jsonb_array_length(rows)-1 loop
  rowj:=rows->i; rankn:=i+1;
  if i>0 then leftj:=rows->(i-1);
   if ((leftj->>'alive')::int=0 and (rowj->>'alive')::int=0 and leftj->'_elim'=rowj->'_elim') or
   ((leftj->>'alive')::int>0 and (rowj->>'alive')::int>0 and leftj->'alive'=rowj->'alive' and (leftj->>'hp')::bigint*(rowj->>'maxHp')::bigint=(rowj->>'hp')::bigint*(leftj->>'maxHp')::bigint and leftj->'kills'=rowj->'kills' and leftj->'damage'=rowj->'damage') then rankn:=(leftj->>'rank')::int; end if;
  end if;
  rows:=jsonb_set(rows,array[i::text],rowj||jsonb_build_object('rank',rankn));
 end loop;
 tied:=survivors=0 or (select count(*) from ml_private.arr(rows) r where (r->>'rank')::int=1)>1;
 if not tied then for rowj in select * from ml_private.arr(rows) loop if (rowj->>'rank')::int=1 then winners:=winners||(rowj->'players'); end if; end loop; end if;
 select jsonb_agg(r-'_elim') into rows from ml_private.arr(rows) r;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_discard_interrupts(s);end if;
 s:=s||jsonb_build_object('result',jsonb_build_object('reason',case when tied then 'draw' when forced then 'round-limit' else 'natural' end,'winners',winners,'ranking',rows),'phase','over','choice',null,'queue','[]'::jsonb,'movement',null);
 s:=ml_private.pause(s,at); return ml_private.emit(s,'result',case when tied then '对局结束：平局' else '对局结束：'||(rows->0->>'label')||' 获胜' end,s->'result');
end $$;
create or replace function ml_private.validate_before_stage3(s jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer; b integer; begin
 perform ml_private.need(s->>'version' in ('web-v0.1.1','web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or (s->>'round')::int<=12),'状态版本/轮次/人数无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb and (select jsonb_agg(member->'character' order by member->'character') from ml_private.arr(s->'players') member)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a; zones:=zones||(p->'hand');
  perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int>=0 and case when ml_private.p3f_enabled(s) then (p->>'maxHp')::numeric=trunc((p->>'maxHp')::numeric) and (p->>'maxHp')::int>=0 and case when ml_private.p3f_uncapped(s,(p->>'seat')::int) then (p->>'maxHp')::int=2 else (p->>'hp')::int<=(p->>'maxHp')::int end else (p->>'hp')::int<=(p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp' end,'生命状态无效');
  perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::numeric=trunc((p->>'shield')::numeric) and (p->>'shield')::int between 0 and 2,'AP/护盾无效');
  perform ml_private.need(ml_private.game_data(s,'map') ? (p->>'cell'),'位置无效');
  if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb,'淘汰清理无效'); end if;
  for b in 0..a-1 loop if (p->>'hp')::int>0 and (s->'players'->b->>'hp')::int>0 and p->'cell'=s->'players'->b->'cell' then perform ml_private.need((s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠'); end if; end loop;
 end loop;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'64张实体不守恒或实体重复');
 if s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then perform ml_private.need(jsonb_array_length(s#>'{classic,caveEnds}')=4 and not exists(select 1 from ml_private.arr(s#>'{classic,caveEnds}') n where jsonb_typeof(n)<>'number' or (n#>>'{}')::numeric<>trunc((n#>>'{}')::numeric) or (n#>>'{}')::int not between 0 and 2),'山洞计数无效');end if;
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.dispatch_before_stage3(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous; a integer; p jsonb; d jsonb; c jsonb; m jsonb; v jsonb; typ text:=cmd->>'type'; card text:=cmd->>'card'; cells jsonb; cell text; cost integer; left_steps integer; deadline double precision; guard integer:=0; changed boolean:=false; targets jsonb; txt text; begin
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');
 perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array','出牌/目标输入无效'); for v in select * from ml_private.arr(cmd->'targets') loop perform ml_private.need(jsonb_typeof(v)='number' and (v#>>'{}')::numeric=trunc((v#>>'{}')::numeric) and ml_private.n(v) between 0 and 3,'目标输入无效'); end loop; end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array','路径必须为数组'); for v in select * from ml_private.arr(cmd->'path') loop perform ml_private.need(jsonb_typeof(v)='string','路径格无效'); end loop; end if;
 if typ='choose' then
  perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号无效');
  if cmd ? 'accept' then perform ml_private.need(jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值'); end if;
  if cmd ? 'card' then perform ml_private.need(jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效'); end if;
  if cmd ? 'cell' then perform ml_private.need(jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效'); end if;
  if cmd ? 'cards' then perform ml_private.need(jsonb_typeof(cmd->'cards')='array','弃牌必须为数组'); for v in select * from ml_private.arr(cmd->'cards') loop perform ml_private.need(jsonb_typeof(v)='string','弃牌输入无效'); end loop; end if;
 end if;
 perform ml_private.need(at>=(s->>'time')::double precision,'时钟必须单调'); perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期'); perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令'); perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 a:=(cmd->>'actor')::int;
 if typ='tick' then
  while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision); exit when deadline is null or deadline>at;
   exit when s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and guard>=999;guard:=guard+1; perform ml_private.need(guard<1000,'超时流程未收敛'); s:=ml_private.expire(s,deadline); changed:=true;
  end loop;
  if not changed then return jsonb_build_object('state',previous,'ok',true); end if;
 else
  perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时');
  if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口'); s:=ml_private.choose(s,cmd,at);
  else
   p:=s->'players'->a; perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作'); perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');
   case typ
    when 'step' then if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb and jsonb_array_length(cmd->'path')>0,'尚未开始移动或路径为空');s:=ml_private.classic_walk(s,cmd->'path',at);else
     perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空'); m:=s->'movement';
     for cell in select x#>>'{}' from ml_private.arr(cmd->'path') x loop
      perform ml_private.need(ml_private.game_data(s,'map') ? cell and ml_private.distance_for_version(s->>'version',p->>'cell',cell)=1,'只能正交移动到棋盘内相邻格'); cost:=case when ml_private.game_data(s,'map')->cell->>'terrain'='water' then 2 else 1 end; left_steps:=(m->>'remaining')::int-cost;
      perform ml_private.need(left_steps>=0,'移动步数不足'); perform ml_private.need(ml_private.escape(s,a,cell,left_steps),'此路径会困在占用格');
      p:=p||jsonb_build_object('cell',cell); m:=m||jsonb_build_object('remaining',left_steps,'path',(m->'path')||to_jsonb(cell)); if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell); end if;
      s:=ml_private.put_player(s,a,p); if ml_private.stage4_location_stops(s,a,cell) then left_steps:=0; m:=jsonb_set(m,'{remaining}','0'); end if;
      s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||left_steps);
     end loop;
     s:=jsonb_set(s,'{movement}',m); if (m->>'remaining')::int=0 then s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); end if;
    end if;
    when 'stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格'); s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
    when 'end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动'); s:=ml_private.end_turn(s,at);
    else
     perform ml_private.need(s->>'phase'='action','请先完成移动');
     if typ='location' then
      v:=s||jsonb_build_object('shipUsed',coalesce(s#>'{classic,shipUsed}','[]'),'farmClosed',coalesce(s#>'{classic,farmClosed}','false'));cell:=cmd->>'cell';
      perform ml_private.need(ml_private.location_destinations(v,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');
      if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||to_jsonb(a));else s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',0));end if;
      s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',cell));s:=ml_private.classic_relocated(s,a,p->>'cell',cell);
      s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
      if ml_private.classic_owes_water(s,a,p->>'cell') then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(jsonb_build_object('kind','action')));s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
     elsif typ='move' then perform ml_private.need(not (p->>'moved')::boolean,'本个人回合已使用基础移动'); perform ml_private.need((p->>'ap')::int>=ml_private.stage4_location_move_cost(s,a),'移动需要1AP'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-case when s->>'version'='web-v0.1.1' then 1 else 0 end,'moved',true)); s:=ml_private.p3g_owned_die(s,'基础移动',a); left_steps:=ceil((s->>'_roll')::numeric/2)::int; s:=s-'_roll'; s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',left_steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'))||case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_object('costDue',ml_private.stage4_location_move_cost(s,a)>0) else '{}'::jsonb end,'phase','moving'); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when ml_private.stage4_location_move_cost(s,a)=0 then ' 操场免费移动，获得' when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ' 移动结束扣费，获得' else ' 移动支付1AP，获得' end||left_steps||'步');
     elsif typ='play' then
      d:=ml_private.rule_card(s,card); perform ml_private.need(ml_private.location_card_allowed(s->>'version',p->>'cell',card),'当前位置禁止使用此牌'); targets:=cmd->'targets'; perform ml_private.need(p->'hand' ? card,'手中没有该实体牌'); perform ml_private.need(d is not null and d->>'type'<>'response','响应牌只能在对应窗口使用'); cost:=(d->>'cost')::int; perform ml_private.need((p->>'ap')::int>=cost,'行动点不足');
      if d->>'type'='attack' then perform ml_private.need(s->>'version' in ('web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or (p->>'attacks')::int<2,'本回合最多两张攻击'); perform ml_private.need(jsonb_array_length(targets) between 1 and case when coalesce((d->>'group')::boolean,false) then case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 3 else 2 end else 1 end and (select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标数量无效'); perform ml_private.need(ml_private.targets(s,a,card) @> targets,'目标不合法：检查范围、队伍、lemon嘲讽或群体免疫');
      else perform ml_private.need(targets='[]'::jsonb,'补给只能对自己'); end if;
      if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{clock}',jsonb_build_object('remaining',60000,'since',at)); end if;
      p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card); s:=ml_private.put_player(s,a,p); s:=jsonb_set(s,'{resolving}',(s->'resolving')||to_jsonb(card)); txt:=ml_private.name(s,a)||' 使用'||(d->>'name')||'，支付'||cost||'AP'; if d->>'type'='attack' then txt:=txt||'，目标'||(select string_agg(ml_private.name(s,ml_private.n(x)::int),'、') from ml_private.arr(targets) x); end if; s:=ml_private.emit(s,'play',txt,jsonb_build_object('actor',a,'card',card,'targets',targets));
      if d->>'type'='attack' then
       s:=ml_private.put_player(s,a,p||jsonb_build_object('attacks',(p->>'attacks')::int+1));
       select coalesce(jsonb_agg(jsonb_build_object('kind','response','actor',x)),'[]') into cells from ml_private.arr(s->'order') x where targets @> jsonb_build_array(x);
       s:=s||jsonb_build_object('attack',jsonb_build_object('actor',a,'card',card,'targets',targets,'cancelled',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(targets) x where not ml_private.location_effect_allowed(s->>'version',s->'players'->(x#>>'{}')::int->>'cell',card)),'elbows','[]'::jsonb),'phase','resolving','queue',(s->'queue')||cells||jsonb_build_array(jsonb_build_object('kind','resolve'))); s:=ml_private.pump(s,at);
      else s:=ml_private.heal(s,a,case when d->>'id'='basic-046' then 2 else 1 end,true);
       if d->>'id'='basic-045' then p:=s->'players'->a; cost:=least(1,2-(p->>'shield')::int); p:=p||jsonb_build_object('shield',(p->>'shield')::int+cost); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'shield',ml_private.name(s,a)||' 获得'||cost||'护盾 → '||(p->>'shield')); end if;
       if d->>'id'='basic-047' then s:=ml_private.draw(s,a,2); end if; s:=ml_private.exercise_discard(s,s->'resolving')||jsonb_build_object('resolving','[]'::jsonb); s:=ml_private.finish(s,false,at);
      end if;
     else raise exception '未知命令'; end if;
   end case;
  end if;
 end if;
 s:=s||jsonb_build_object('seen',(s->'seen')||to_jsonb(cmd->>'id'),'revision',(s->>'revision')::bigint+1,'time',at); perform ml_private.validate(s); return jsonb_build_object('state',s,'ok',true);
exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.choose_before_stage3(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice'; a integer:=(c->>'actor')::int; p jsonb:=s->'players'->a; kind text:=c->>'kind'; card text:=cmd->>'card'; cell text:=cmd->>'cell'; cards jsonb; actor integer; paid integer; begin
 perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期'); perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 case kind
  when 'draw-start','draw-end' then if coalesce((cmd->>'accept')::boolean,false) then s:=ml_private.draw(s,a,1); end if;
  when 'response' then if card is not null and card<>'' then perform ml_private.need(c->'cards' ? card,'此牌不能响应'); paid:=(ml_private.rule_card(s,card)->>'cost')::int; p:=p||jsonb_build_object('ap',(p->>'ap')::int-paid,'hand',(p->'hand')-card); s:=ml_private.put_player(s,a,p); s:=s||jsonb_build_object('resolving',(s->'resolving')||to_jsonb(card)); s:=jsonb_set(s,'{attack,cancelled}',(s#>'{attack,cancelled}')||to_jsonb(a)); if ml_private.rule_card(s,card)->>'id'='basic-002' then s:=jsonb_set(s,'{attack,elbows}',(s#>'{attack,elbows}')||to_jsonb(a)); end if; s:=ml_private.emit(s,'response',ml_private.name(s,a)||' 使用'||(ml_private.rule_card(s,card)->>'name')||'，支付'||paid||'AP'); else s:=ml_private.emit(s,'response',ml_private.name(s,a)||' 放弃响应'); end if;
  when 'lemon-reward' then if coalesce((cmd->>'accept')::boolean,false) then actor:=(c->>'source')::int; s:=ml_private.put_player(s,actor,(s->'players'->actor)||jsonb_build_object('rewarded',(s->'players'->actor->'rewarded')||to_jsonb(a))); s:=ml_private.draw(s,a,1); end if;
  when 'lemon-support' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=1 and not (p->>'skillUsed')::boolean,'支援不可用'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-1,'skillUsed',true)); for actor in 0..3 loop if (s->'players'->actor->>'hp')::int>0 and (actor=a or (s->>'mode'='team' and s->'players'->actor->>'team'=p->>'team')) then s:=ml_private.draw(s,actor,1); end if; end loop; s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 支援，支付1AP'); end if;
  when 'runner-roll' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=2 and not (p->>'skillUsed')::boolean,'恢复判定不可用'); s:=ml_private.put_player(s,a,p||jsonb_build_object('skillUsed',true)); s:=ml_private.p3g_owned_die(s,'跑者恢复',a); paid:=(s->>'_roll')::int; s:=s-'_roll'; if paid>=4 then s:=jsonb_set(s,'{choice}','null'); return ml_private.select_choice(s,'runner-pay',a,at); end if; end if;
  when 'runner-pay' then if coalesce((cmd->>'accept')::boolean,false) then perform ml_private.need((p->>'ap')::int>=2,'恢复费用不足'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-2)); s:=ml_private.heal(s,a,1); s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 恢复支付2AP'); end if;
  when 'teleport' then if cell is not null and cell<>'' then perform ml_private.need(c->'cells' ? cell and ml_private.teleport_cells(s,a) ? cell,case when s->>'version' in ('web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then '传送须为全图合法空格' else '传送须为距离≤3的空陆地' end); s:=ml_private.put_player(s,a,p||jsonb_build_object('cell',cell,'skillUsed',true));s:=ml_private.classic_relocated(s,a,p->>'cell',cell); s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' 传送至'||cell||case when s->'safe' ? cell then '' else '（毒圈外）' end); end if;
  when 'discard','water-discard' then cards:=coalesce(cmd->'cards','[]'); perform ml_private.need(jsonb_array_length(cards)=(c->>'count')::int and (select count(distinct x) from ml_private.arr(cards) x)=jsonb_array_length(cards) and p->'hand' @> cards,'请选择准确数量的不同手牌弃置'); select coalesce(jsonb_agg(x),'[]') into p from ml_private.arr(p->'hand') x where not (cards @> jsonb_build_array(x)); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('hand',p)); s:=ml_private.exercise_discard(s,cards); s:=ml_private.emit(s,case when timeout then 'timeout-discard' else 'discard' end,ml_private.name(s,a)||case when timeout then ' 超时代弃' else ' 自选弃牌' end||jsonb_array_length(cards)||'张',cards);
  else raise exception '未知选择';
 end case;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||kind); end if;
 s:=s||jsonb_build_object('choice',null,'phase','resolving'); return ml_private.pump(s,at);
end $$;
create or replace function ml_private.legal_steps_before_stage3(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.legal_steps_legacy(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return '[]';end if;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,(s->>'active')::int,c->>'id',(s#>>'{movement,remaining}')::int-ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')));
end $$;
create or replace function ml_private.settle_movement_before_stage3(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; m jsonb:=s->'movement'; p jsonb; begin
 if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and coalesce((m->>'costDue')::boolean,false) then
  if jsonb_array_length(m->'path')>1 then p:=s->'players'->a; perform ml_private.need((s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or (p->>'ap')::int>=1),'移动结算需要1AP'); s:=ml_private.p3d_pay(s,a,least(1,(p->>'ap')::int)); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||' 移动结束支付'||least(1,(p->>'ap')::int)||'AP'); end if;
  s:=jsonb_set(s,'{movement,costDue}','false');
 end if; return s;
end $$;
create or replace function ml_private.next_turn_before_stage3(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.next_turn_legacy(s,at);end if;
 s:=ml_private.pause(s,at);a:=(s->>'active')::int;s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('moved',false,'attacks',0));cursor:=(s->>'cursor')::int+1;
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1;end loop;s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then return jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue'));end if;
 s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.classic_environment(s);s:=ml_private.emit(s,'environment','第'||(s->>'round')||'轮末，轰炸：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,bombs}') x));s:=ml_private.damage(s,s->'_hits',true);s:=s-'_hits';
 s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','round-next')));return s-'_triggers';
end $$;
create or replace function ml_private.stage3_actions(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a;free boolean:=s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and (p->>'hp')::int>0;revival jsonb:='[]';bread jsonb:='[]';cards jsonb:='{}';elbow jsonb:='{}';card text;d jsonb;quote integer;cost jsonb;targets jsonb;converted jsonb;equipment jsonb;member jsonb;cells jsonb;options jsonb;target integer;begin
 for member in select * from ml_private.arr(s->'players') loop if jsonb_array_length(ml_private.stage3_revival_cells(s,(member->>'seat')::int,(s#>>'{classic,farmClosed}')::boolean))>0 then revival:=revival||jsonb_build_array(member->'seat');end if;end loop;
 if free and (case when ml_private.p3g_enabled(s) then ml_private.p3g_bread_equipment(s,a) is not null else ml_private.stage3_equipped(s,a,'basic-054') and (s#>>array['stage3','starts',a::text])::int>=(s#>>array['stage3','breadReadyAt',a::text])::int end) then select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into bread from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (q->>'seat')::int<>a;end if;
 for card in select x#>>'{}' from ml_private.arr(p->'hand') x loop d:=ml_private.rule_card(s,card);quote:=case when s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then (s#>>array['stage3','costLocks',card,'cost'])::int else null end;cost:=case when s#>>'{choice,kind}'='response' and (s#>>'{choice,actor}')::int=a and s#>'{choice,cards}' ? card and ml_private.exercise_response(s,s#>>'{cardStack,stack,-1,definition}',card) then case when ml_private.p3h_enabled(s) and ml_private.p3h_prime_active(s,a) then '1'::jsonb else '0'::jsonb end when d->>'randomCost'='true' and quote is null then 'null'::jsonb else ml_private.stage3_card_cost(s,a,card,quote)->'cost' end;
 if d->>'id'='basic-002' and p->>'character'='character-023' then targets:=ml_private.stage3_elbow_targets(s,a,false);elsif d->>'type'='attack' then targets:=ml_private.targets(s,a,card);elsif d->>'id'='basic-037' then targets:=revival;elsif d->>'id'='basic-016' then select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (q->>'seat')::int<>a and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,q->>'cell',jsonb_build_array(a,q->'seat')) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),(q->>'seat')::int,p->>'cell',jsonb_build_array(a,q->'seat'));else targets:='[]';end if;
 converted:=case when not ml_private.p3h_active_allowed(s,a) then '[]'::jsonb when p->>'character'='character-023' then ml_private.stage3_elbow_targets(s,a,true) when ml_private.p3d_enabled(s) and p->>'character'='character-029' then ml_private.p3d_dodge_targets(s,a) else '[]'::jsonb end;equipment:=case when d->>'type'='equipment' then ml_private.stage3_equipment_options(s,a,card) else 'null'::jsonb end;
  cards:=cards||jsonb_build_object(card,jsonb_build_object('cost',cost,'needsQuote',coalesce(d->>'randomCost'='true' and quote is null,false),'targets',targets,'convertTargets',converted,'equipment',equipment,'blocked',s#>array['stage3','breadBlocked',a::text]));end loop;
 if p->>'character'='character-023' then for target in select (x#>>'{}')::int from ml_private.arr(ml_private.stage3_elbow_targets(s,a,false)) x loop cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);select coalesce(jsonb_object_agg(direction,cell),'{}') into options from (select direction,ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],direction) cell from unnest(array['up','right','down','left']) direction) q where cell is not null and cells ? cell;elbow:=jsonb_set(elbow,array[target::text],options);end loop;end if;
 return jsonb_build_object('elbowPush',elbow,'jj',free and ml_private.p3h_active_allowed(s,a) and p->>'character'='character-003' and s#>>array['stage3','jjUsed',a::text]<>'true','breadTargets',bread,'revivalTargets',revival,'cards',cards,'movementBlocked',ml_private.stage3_mount_blocked(s,a) or coalesce((s#>>array['stage3','c','blocked',a::text])::boolean,false),'moveCost',case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a)) end,'locations',jsonb_build_object('ship',ml_private.stage3_locations(s,a,'ship'),'commute',ml_private.stage3_locations(s,a,'commute')),'directionRequired',p->>'character'='character-040','basicMovesRemaining',greatest(0,case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end-(s#>>array['stage3','basicUsed',a::text])::int)) || case when s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_object('mayi',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and p->>'character'='character-025' and (p->>'ap')::int>=3,'targets',ml_private.p3_mayi_targets(s,a),'cost',3)) else '{}'::jsonb end || case when ml_private.p3c_enabled(s) then jsonb_build_object('feather',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-046' and not ml_private.p3c_feather(s,a),'active',coalesce((s#>>array['stage3','c','feather',a::text])::boolean,false)),'primitive',jsonb_build_object('used',s#>array['stage3','c','used',a::text],'sleep',s#>array['stage3','c','sleep',a::text])) else '{}'::jsonb end || case when ml_private.p3d_enabled(s) then jsonb_build_object('clan',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-053' and s#>>array['stage3','d','clanUsed',a::text]='false' and jsonb_array_length(p->'hand')>0,'used',s#>array['stage3','d','clanUsed',a::text],'targets',ml_private.p3d_clan_targets(s,a,true))) else '{}'::jsonb end || case when ml_private.p3e_enabled(s) then jsonb_build_object('gas',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-014' and (p->>'ap')::int>=1),'escape',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-038' and (p->>'ap')::int>=2 and s#>>array['stage3','e','escapeUsed',a::text]='false','used',s#>array['stage3','e','escapeUsed',a::text],'regions',(select jsonb_agg(region order by first_ord) from (select c->>'region' region,min(ord) first_ord from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(c,ord) group by c->>'region') q))) else '{}'::jsonb end || case when ml_private.p3f_enabled(s) then jsonb_build_object('execute',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-007' and s#>>array['stage3','f','executeUsed',a::text]='false' and jsonb_array_length(p->'hand')>0,'used',s#>array['stage3','f','executeUsed',a::text],'targets',ml_private.p3f_targets(s,a,true)),'magma',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-052' and (p->>'ap')::int>=2)) else '{}'::jsonb end || case when ml_private.p3g_enabled(s) then jsonb_build_object('cube',jsonb_build_object('face',ml_private.p3g_cube_face(s,a),'teleportCells',ml_private.p3g_cube_cells(s,a)),'dog',jsonb_build_object('available',free and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and p->>'character'='character-022' and (p->>'ap')::int>=1,'targets',ml_private.p3g_dog_targets(s,a))) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('freeze',ml_private.p3h_freeze_action(s,a)) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('activeBlocker',ml_private.p3h_active_blocker(s,a)) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('circle',ml_private.p3h_circle_action(s,a)) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('cooperate',ml_private.p3h_cooperate_action(s,a)) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('ren',ml_private.p3h_ren_action(s,a)) else '{}'::jsonb end || case when ml_private.p3h_enabled(s) then jsonb_build_object('leap',jsonb_build_object('cells',ml_private.p3h_leap_cells(s,a))) else '{}'::jsonb end;end $$;
create or replace function ml_private.stage3_skill(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ begin if cmd->>'kind'='ren' then return ml_private.p3h_ren_skill(s,cmd);end if; if cmd->>'kind'='cooperate' then return ml_private.p3h_cooperate_skill(s,cmd,at);end if; if cmd->>'kind'='circle' then return ml_private.p3h_circle(s,(cmd->>'actor')::int);end if; perform ml_private.need(not ml_private.p3h_active_skill(cmd->>'kind') or ml_private.p3h_active_allowed(s,(cmd->>'actor')::int),'又开始叫了：当前地区不能发动主动技能'); if ml_private.p3h_enabled(s) and cmd->>'kind'='freeze' then return ml_private.p3h_freeze(s,(cmd->>'actor')::int,(cmd->>'target')::int);end if; if ml_private.p3g_enabled(s) and cmd->>'kind'='dog' then return ml_private.p3g_dog(s,(cmd->>'actor')::int,(cmd->>'target')::int,cmd->>'direction');end if;
 if cmd->>'kind' in ('execute','magma') then return ml_private.p3f_skill(s,cmd);end if;
 if cmd->>'kind' in ('gas','escape') then return ml_private.p3e_skill(s,(cmd->>'actor')::int,cmd->>'kind',cmd->>'region');end if;
 if cmd->>'kind'='clan' then return ml_private.p3d_clan(s,(cmd->>'actor')::int);end if;
 if cmd->>'kind'='feather' then return ml_private.p3c_skill(s,(cmd->>'actor')::int);end if;
 if cmd->>'kind'='mayi' then return ml_private.p3_mayi_skill(s,cmd);end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and cmd->>'kind' in ('watch','flight','gift','terrain') then s:=ml_private.stage4_equipment_skill(s,cmd,at);return s-'_equipmentSkill';end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and cmd->>'kind'='quote-cost' then return ml_private.stage4_quote(s,(cmd->>'actor')::int,cmd->>'card');end if;
 return ml_private.stage3_skill_before_stage4(s,cmd,at);
end $$;
create or replace function ml_private.stage3_available_targets(s jsonb,pending jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(t order by ord),'[]') from jsonb_array_elements(pending->'targets') with ordinality x(t,ord) where ml_private.stage3_alive(s,(t#>>'{}')::int) and not (pending->'cancelled' @> jsonb_build_array(t)) and ml_private.stage3_card_allowed(s,(t#>>'{}')::int,pending->>'definition',pending->'effect') and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then not(coalesce(pending#>'{stage4,officeExempt}','[]') @> jsonb_build_array(t)) else ml_private.location_effect_allowed('web-v0.1.5',s#>>array['players',t#>>'{}','cell'],pending->>'definition') end) $$;
create or replace function ml_private.stage3_responses(s jsonb,a integer,pending jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(card order by ord),'[]') from jsonb_array_elements(s#>array['players',a::text,'hand']) with ordinality x(card,ord) where ml_private.p3g_card_target_allowed(s,a,case when split_part(card#>>'{}','#',1)='basic-001' then a else (pending->>'actor')::int end,split_part(card#>>'{}','#',1)) and case when ml_private.exercise_response(s,pending->>'definition',card#>>'{}') then (s#>>array['players',a::text,'ap'])::int>=case when ml_private.p3h_prime_active(s,a) then 1 else 0 end else ((split_part(card#>>'{}','#',1)='basic-001' and pending->>'definition'<>'basic-009') or (split_part(card#>>'{}','#',1)='basic-002' and pending->>'definition'='basic-008')) and (s#>>array['players',a::text,'ap'])::int>=(ml_private.stage3_card_cost(s,a,card#>>'{}')->>'cost')::int end $$;
create or replace function ml_private.stage3_handle_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s#>'{cardStack,stack,-1}';definition text:=c->>'definition';d jsonb;targets jsonb;exercise boolean;target integer;paid integer;power integer;amount integer;hits jsonb:='[]';after_tasks jsonb:='[]';begin s:=ml_private.p3h_gear_task(s,t,at);if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_small_task(s,t,at);end if;if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_leap_task(s,t,at);end if;if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_ren_task(s,t,at);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_cooperate_task(s,t);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_circle_task(s,t,at);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_task(s,t,at);end if;if s->>'_hHandled'='true' then return s-'_hHandled';end if;s:=s-'_hHandled'; s:=ml_private.p3g_dual_task(s,t,at);if s->>'_gDualHandled'='true' then return s-'_gDualHandled';end if;s:=s-'_gDualHandled'; s:=ml_private.p3g_card_task(s,t,at);if s->>'_gCardHandled'='true' then return s-'_gCardHandled';end if;s:=s-'_gCardHandled';s:=ml_private.p3g_observer_task(s,t,at);if s->>'_gObserverHandled'='true' then return s-'_gObserverHandled';end if;s:=s-'_gObserverHandled'; s:=ml_private.p3g_cube_task(s,t,at);if s->>'_gCubeHandled'='true' then return s-'_gCubeHandled';end if;s:=s-'_gCubeHandled';s:=ml_private.p3g_haki_task(s,t,at);if s->>'_gHakiHandled'='true' then return s-'_gHakiHandled';end if;s:=s-'_gHakiHandled'; s:=ml_private.p3g_food_task(s,t,at);if s->>'_gFoodHandled'='true' then return s-'_gFoodHandled';end if;s:=s-'_gFoodHandled';
 if ml_private.p3f_enabled(s) and t->>'action' like 'f-%' then return ml_private.p3f_task(s,t,at);end if;
 if ml_private.p3e_enabled(s) and t->>'action' like 'e-%' then return ml_private.p3e_task(s,t,at);end if;
 if ml_private.p3d_enabled(s) and t->>'action' in ('encourage','encourage-discard','nailong-shake') then return ml_private.p3d_task(s,t,at);end if;
 if t->>'action'='primitive-food' then return ml_private.p3c_food_task(s,(t->>'actor')::int,at);end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_movement_task(s,t,at);if s->>'_movementHandled'='true' then return s-'_movementHandled';end if;s:=s-'_movementHandled';s:=ml_private.stage4_combat_task(s,t,at);if s->>'_combatHandled'='true' then return s-'_combatHandled';end if;s:=s-'_combatHandled';s:=ml_private.stage4_equipment_task(s,t,at);if s->>'_gearHandled'='true' then return s-'_gearHandled';end if;s:=s-'_gearHandled';s:=ml_private.stage4_counter_task(s,t,at);if s->>'_stage4Handled'='true' then return s-'_stage4Handled';end if;s:=s-'_stage4Handled';s:=ml_private.stage4_interrupt_task(s,t,at);if s->>'_interruptHandled'='true' then return s-'_interruptHandled';end if;s:=s-'_interruptHandled';s:=ml_private.stage4_map_task(s,t,at);if s->>'_boardHandled'='true' then return s-'_boardHandled';end if;s:=s-'_boardHandled';end if;
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or t->>'action'<>'effect' then return ml_private.stage3_handle_task_before_stage4(s,t,at);end if;
 exercise:=definition in ('basic-003','basic-004','basic-005') and exists(select 1 from ml_private.arr(c->'targets') v where s#>>array['stage4','exerciseGuard',v#>>'{}']='true');
 if definition not in ('basic-007','basic-011','basic-012','basic-014','basic-018','basic-019','basic-022','basic-025','basic-029','basic-030','basic-035','basic-036','basic-040','basic-042','basic-043','basic-044','basic-048','basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034') and not(definition='basic-009' and c#>>'{stage4,dodge}'='true') and not exercise then return ml_private.stage3_handle_task_before_stage4(s,t,at);end if;
 d:=ml_private.stage4_content()#>array['cards',definition];s:=ml_private.stage3_record_combo(s,(c->>'actor')::int,definition);targets:=ml_private.stage3_available_targets(s,c);s:=ml_private.p3c_mark_food(s,targets);
 for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop
  if definition in ('basic-011','basic-012','basic-014') then null;
  elsif definition='basic-007' then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',case when (s#>>array['players',target::text,'character']='character-037' or ml_private.p3f_enabled(s) and s#>>array['players',target::text,'character'] in ('character-051','character-052')) then 3 else 2 end,'source',c->'actor','category','attack'));
  elsif definition='basic-009' then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',2,'source',c->'actor','category','attack'));
  elsif exercise then
   if s#>>array['stage4','exerciseGuard',target::text]='true' then s:=jsonb_set(s,array['stage4','exerciseGuard',target::text],'false');s:=ml_private.emit(s,'buff','S'||(target+1)||' 农夫三拳免本次搏击操AP扣减');
   else power:=(ml_private.rule_card(s,c->>'card')->>'power')::int;paid:=least((s#>>array['players',target::text,'ap'])::int,power);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-paid));
    if paid<power then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',power-paid,'source',c->'actor','category','attack'));end if;end if;
  elsif definition='basic-018' then s:=jsonb_set(s,array['stage4','downPending',target::text],'true');s:=jsonb_set(s,array['stage3','coffeeRound',target::text],'true');s:=jsonb_set(s,array['stage3','coffeeUntilStart',target::text],to_jsonb((s#>>array['stage3','starts',target::text])::int+1));
  elsif definition='basic-019' then amount:=least(2,(s#>>array['players',target::text,'ap'])::int);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-amount));s:=ml_private.stage3_gain_ap(s,(c->>'actor')::int,amount);s:=ml_private.emit(s-'_gain','ap','借我张纸拿取'||amount||'AP');
  elsif definition='basic-022' then s:=jsonb_set(s,array['stage3','breadPending',target::text],'true');
  elsif definition='basic-025' then s:=ml_private.draw(s,target,coalesce((c#>>'{stage4,x}')::int,0));
  elsif definition in ('basic-029','basic-030','basic-035','basic-036') then s:=ml_private.stage4_change_faction(s,target,case when definition='basic-029' then 'monkey' when definition='basic-030' then 'dimon' else null end);s:=ml_private.emit(s,'faction','S'||(target+1)||' 当前归属：'||(s#>>array['players',target::text,'faction'])||case when s->>'mode'='team' then '／'||(s#>>array['players',target::text,'team'])||'队' else '' end);
  elsif definition='basic-048' then s:=ml_private.p3g_owned_die(s,'油泼',(c->>'actor')::int);amount:=(s->>'_roll')::int;s:=s-'_roll';
   if amount=6 then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',c->'actor','category','attack')));after_tasks:=after_tasks||(s->'_triggers');s:=s-'_triggers';
   else s:=ml_private.heal(s,target,case when ml_private.p3f_uncapped(s,target) then 2 else (s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int end,true);end if;
  else s:=ml_private.heal(s,target,case when definition='basic-040' and s#>>array['players',target::text,'character']='character-040' then (s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int else 1 end,true);
   if definition='basic-042' then s:=jsonb_set(s,array['stage4','buffSources',target||':tea'],c->'effect');s:=jsonb_set(s,array['stage4','tea',target::text],'true');end if;
   if definition='basic-043' then s:=jsonb_set(s,array['stage4','buffSources',target||':dodge'],c->'effect');s:=jsonb_set(s,array['stage4','dodge',target::text],'true');end if;
   if definition='basic-044' then s:=jsonb_set(s,array['stage4','buffSources',target||':exerciseFree'],c->'effect');s:=jsonb_set(s,array['stage4','exerciseFree',target::text],'true');s:=jsonb_set(s,array['stage4','exerciseGuard',target::text],'true');end if;
  end if;
 end loop;
 if definition in ('basic-007','basic-009') or exercise then s:=ml_private.damage(s,hits);after_tasks:=after_tasks||(s->'_triggers');s:=s-'_triggers';end if;
 if definition in ('basic-011','basic-012','basic-014') then for target in select (x#>>'{}')::int from ml_private.arr(s->'order') x where targets @> jsonb_build_array(x) loop after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('stage4-deliver',jsonb_build_object('actor',target,'serial',c->'serial')));end loop;end if;
 s:=ml_private.emit(s,'effect',(d->>'name')||'结算');return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));
end $$;
create or replace function ml_private.stage3_locations(s jsonb,a integer,kind text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare input jsonb;result jsonb;begin
 if ml_private.stage4_ignore_location(s,a) or ml_private.stage3_mount_blocked(s,a) then return '[]';end if;
 input:=ml_private.stage3_board(s)||jsonb_build_object('shipUsed',s#>'{classic,shipUsed}');if kind='ship' and s#>>array['stage3','jjFree',a::text]='true' then input:=jsonb_set(input,array['players',a::text,'ap'],to_jsonb(greatest(1,(s#>>array['players',a::text,'ap'])::int)));end if;
 select coalesce(jsonb_agg(c order by ord),'[]') into result from jsonb_array_elements(ml_private.location_destinations(input,a,kind)) with ordinality t(c,ord) where ml_private.stage3_can_enter(s,a,c#>>'{}') and (s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],c#>>'{}') is not null);return result;
end $$;
create or replace function ml_private.stage3_play(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$
declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;card text:=cmd->>'card';definition text:=split_part(card,'#',1);
 d jsonb;tea boolean;free boolean;targets jsonb:=cmd->'targets';cells jsonb;raw integer;quoted jsonb;effect jsonb;exposed jsonb;fee jsonb;pending jsonb;idx text;begin perform ml_private.need(coalesce(cmd->>'as','') not in ('elbow','dodge') or ml_private.p3h_active_allowed(s,(cmd->>'actor')::int),'又开始叫了：当前地区不能发动主动转换');
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.stage3_play_before_stage4(s,cmd,at);end if;
 d:=ml_private.stage4_content()#>array['cards',definition];
 perform ml_private.need(d is not null and p->'hand' ? card,'手中没有该实体牌');
 perform ml_private.need(s#>>array['stage3','breadBlocked',a::text]<>'true','本回合不能主动出牌');
 tea:=definition='basic-002' and not(cmd ? 'as') and s#>>array['stage4','tea',a::text]='true';
 perform ml_private.need(ml_private.p3g_cube_face(s,a)<>1 or not(d->>'type'='attack' or tea or coalesce(cmd->>'as' in ('elbow','dodge'),false)),'魔法有方1：本个人回合不能主动使用攻击牌');if not(cmd ? 'as') and d->>'type'='equipment' then perform ml_private.stage4_validate_equipment(s,cmd);end if;
 if d->>'inherited'='true' and not tea or cmd->>'as' in ('elbow','dodge') then
  free:=not(cmd ? 'as') and definition in ('basic-003','basic-004','basic-005') and s#>>array['stage4','exerciseFree',a::text]='true';
  -- Cost override is an internal flag consumed by the generated frozen delegate.
  if free then s:=s||jsonb_build_object('_stage4Free',true);end if;
  s:=ml_private.stage3_play_before_stage4(s,cmd,at);s:=s-'_stage4Free';
  if free then s:=jsonb_set(s,array['stage4','exerciseFree',a::text],'false');end if;
  if (not(cmd ? 'as') or cmd->>'as'='dodge') and (definition='basic-009' or cmd->>'as'='dodge') and s#>>array['stage4','dodge',a::text]='true' then
   idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],jsonb_build_object('dodge',true));s:=jsonb_set(s,array['cardStack','stack',idx,'effect','roleModifiers'],(s#>array['cardStack','stack',idx,'effect','roleModifiers'])||coalesce(s#>array['stage4','buffSources',a||':dodge','roleModifiers'],'[]'));s:=jsonb_set(s,array['stage4','dodge',a::text],'false');
  end if;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],coalesce(s#>array['cardStack','stack',idx,'stage4'],'{}')||jsonb_build_object('officeExempt',(select coalesce(jsonb_agg(v->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality q(v,ord) where not ml_private.stage4_location_effect(s,(v->>'seat')::int,s#>>array['cardStack','stack',idx,'definition']))));return s;
 end if;
 perform ml_private.need(tea or d->>'type'='equipment' or definition in ('basic-024','basic-007','basic-011','basic-012','basic-014','basic-018','basic-019','basic-022','basic-025','basic-029','basic-030','basic-035','basic-036','basic-040','basic-042','basic-043','basic-044','basic-048','basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034'),'该牌的阶段四里程碑尚未接通');
 perform ml_private.need(not(cmd ? 'as'),'转换请按牢大肘击流程');
 perform ml_private.need(p->>'character'<>'character-005' or not(d->'tags' ? '建民'),'QB不能使用建民牌');
 perform ml_private.need(ml_private.stage4_location_card(s,a,definition),'当前位置禁止使用此牌');
 perform ml_private.need((select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标不能重复');
 if tea then
  perform ml_private.need(jsonb_array_length(targets)=1 and exists(select 1 from ml_private.arr(s->'players') v where v->'seat'=targets->0 and (v->>'seat')::int<>a and ml_private.stage4_on_board(s,(v->>'seat')::int) and not ml_private.stage4_single_protected(s,a,(v->>'seat')::int) and ml_private.game_data(s,'map')#>>array[v->>'cell','region']=ml_private.game_data(s,'map')#>>array[p->>'cell','region']),'冰红茶肘击须指定同地区其他角色');
  cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,(targets->>0)::int);
  perform ml_private.need(jsonb_array_length(cells)=0 or (cmd ? 'direction') and cells ? ml_private.stage3_direction_cell(s#>>array['players',targets->>0,'cell'],cmd->>'direction'),'请先指定合法撞飞方向');
 elsif definition in ('basic-007','basic-018','basic-019','basic-022','basic-029','basic-030','basic-035','basic-036','basic-021','basic-024') then
  perform ml_private.need(jsonb_array_length(targets)=1 and ml_private.stage4_targets(s,a,card) @> targets,'目标不合法');
 else
  perform ml_private.need(targets='[]'::jsonb,'此牌不接受外部目标');
  if definition in ('basic-011','basic-012','basic-014','basic-013','basic-031','basic-026') then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(v,ord) where ml_private.stage4_on_board(s,(v->>'seat')::int) and (definition not in ('basic-013','basic-031','basic-026') and (s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or definition not in ('basic-012','basic-014')) or (v->>'seat')::int<>a) and (definition<>'basic-026' or s->>'mode'='ffa' or v->'team'<>p->'team') and not(v->>'character'='character-027' and jsonb_array_length(v->'hand')=1);elsif definition='basic-040' then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(v,ord) where (v->>'hp')::int>0 and v->>'faction'='帝汶家族';else targets:=jsonb_build_array(a);end if;
 end if;
 targets:=ml_private.playtest_north_targets(s,targets,cmd->>'northGroup',not tea and definition not in ('basic-007','basic-018','basic-019','basic-022','basic-029','basic-030','basic-035','basic-036','basic-021','basic-024'));
 if definition='basic-024' then perform ml_private.stage4_validate_steal(s,cmd);end if;
 if definition in ('basic-023','basic-032','basic-033') then perform ml_private.need(jsonb_typeof(cmd->'region')='string' and ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}' ? (cmd->>'region'),'请选择合法地区');end if;
 if tea then raw:=0;
 elsif d#>>'{cost,kind}'='variable' then
  perform ml_private.need(jsonb_typeof(cmd->'x')='number' and (cmd->>'x')::numeric=trunc((cmd->>'x')::numeric),'X必须为正整数');
  raw:=(ml_private.stage4_cost_quote(s#>'{stage4,costs}',a,card,p->'hand',null,(cmd->>'x')::bigint)#>>'{quote,cost}')::int;
 elsif d#>>'{cost,kind}'='fixed' then raw:=(d#>>'{cost,value}')::int;
 else raw:=(s#>>array['stage4','costs','locks',card,'cost'])::int;end if;
 perform ml_private.need(raw is not null,'请先锁定随机费用');
 if tea or d#>>'{cost,kind}'='variable' then quoted:=jsonb_build_object('cost',raw,'effect',jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers',case when tea then coalesce(s#>array['stage4','buffSources',a||':tea','roleModifiers'],'[]')||case when p->>'character'='character-023' then jsonb_build_array(jsonb_build_object('actor',a,'kind','other')) else '[]'::jsonb end else '[]'::jsonb end));
 else quoted:=ml_private.stage3_card_cost(s,a,card,raw);end if;
 quoted:=ml_private.p3g_prime_quote(s,a,quoted);fee:=ml_private.stage4_fee_plan((p->>'ap')::int,(quoted->>'cost')::int,false,d#>>'{cost,kind}'='variable');
 exposed:=ml_private.stage3_jj_targets(s,a,card,targets,ml_private.stage4_attack_effect(s,a,card,quoted->'effect'));
 perform ml_private.playtest_north_targets(s,exposed->'targets');
 p:=p||jsonb_build_object('ap',(p->>'ap')::int-(fee->>'spend')::int,'hand',(p->'hand')-card);if d->>'type'='attack' or tea then p:=p||jsonb_build_object('attacks',(p->>'attacks')::int+1);end if;s:=ml_private.put_player(s,a,p);s:=ml_private.p3d_paid(s,a,(p->>'ap')::int+(fee->>'spend')::int,(fee->>'spend')::int);
 if (fee->>'gain')::int>0 then s:=ml_private.stage3_gain_ap(s,a,(fee->>'gain')::int);s:=s-'_gain';end if;
 s:=s||jsonb_build_object('resolving',(s->'resolving')||jsonb_build_array(card),'clock',jsonb_build_object('remaining',60000,'since',at));
 s:=ml_private.stage3_begin_card(s,a,card,definition,exposed->'targets',exposed->'effect',at);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;pending:=s#>array['cardStack','stack',idx];
 pending:=pending||jsonb_build_object('stage4',jsonb_build_object('officeExempt',(select coalesce(jsonb_agg(v->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality q(v,ord) where not ml_private.stage4_location_effect(s,(v->>'seat')::int,definition)))||case when d#>>'{cost,kind}'='variable' then jsonb_build_object('x',raw) else '{}'::jsonb end||case when cmd ? 'region' then jsonb_build_object('region',cmd->'region') else '{}'::jsonb end);
 if pending->'g' is not null and d->>'type'='equipment' then pending:=jsonb_set(pending,'{g,replacements}',coalesce(cmd->'replacements',case when cmd ? 'replacement' then jsonb_build_array(cmd->'replacement') else '[]'::jsonb end));end if;if cmd ? 'replacement' then pending:=pending||jsonb_build_object('replacement',cmd->'replacement');end if;
 if definition='basic-024' then pending:=jsonb_set(pending,'{stage4}',(pending->'stage4')||jsonb_build_object('take',cmd->'take')||case when cmd ? 'item' then jsonb_build_object('item',cmd->'item') else '{}'::jsonb end);end if;
 if definition='basic-073' then pending:=jsonb_set(pending,'{stage4,copy}',to_jsonb(split_part(cmd->>'copy','#',1)));pending:=jsonb_set(pending,'{effect,roleModifiers}',(pending#>'{effect,roleModifiers}')||(s#>array['stage3','equipmentSources',cmd->>'copy','roleModifiers']));end if;
 if tea then if cmd ? 'direction' then pending:=pending||jsonb_build_object('pushDirection',cmd->'direction');end if;s:=jsonb_set(s,array['stage4','tea',a::text],'false');end if;
 s:=jsonb_set(s,array['cardStack','stack',idx],pending);
 s:=ml_private.emit(s,'play','S'||(a+1)||' 使用'||(d->>'name')||'，支付'||(fee->>'spend')||'AP'||case when (fee->>'gain')::int>0 then '，获得'||(fee->>'gain')||'AP' else '' end,jsonb_build_object('actor',a,'card',card,'targets',exposed->'targets'));
 s:=jsonb_set(s,'{phase}','"resolving"');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage3_relocate(s jsonb,a integer,cell text,voluntary boolean,carry boolean default true) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare origin text:=s#>>array['players',a::text,'cell']; snapshots jsonb; tasks jsonb:='[]';e_source integer;e_root text;e_gate jsonb;h_requested text:=cell;h_placement boolean:=coalesce((s->>'_fPlacement')::boolean,false);begin
 if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then cell:=ml_private.playtest_relocation_cell(s,a,origin,cell);if cell is null then return (case when ml_private.p3f_enabled(s) then s-'_fPlacement'-'_eCause' else s end)||jsonb_build_object('_relocationTasks',tasks);end if;end if;
 if origin=cell or voluntary and ml_private.stage3_mount_blocked(s,a) then return (case when ml_private.p3f_enabled(s) then s-'_fPlacement'-'_eCause' else s end)||jsonb_build_object('_relocationTasks',tasks);end if;
 if ml_private.p3e_enabled(s) then e_source:=case when s ? '_eCause' then (s#>>'{_eCause,source}')::int when voluntary then a else coalesce((s#>>'{choice,actor}')::int,(s#>>'{cardStack,stack,-1,actor}')::int,(s->>'active')::int) end;e_root:=coalesce(s#>>'{_eCause,root}',ml_private.p3e_root(s));s:=ml_private.p3f_move_gate(s,a,cell,coalesce((s->>'_fPlacement')::boolean,false),e_root);if s->>'_fMoveAllowed'='false' then return (s-'_fMoveAllowed'-'_eCause'-'_fPlacement')||jsonb_build_object('_relocationTasks',tasks);end if;s:=s-'_fMoveAllowed'-'_fPlacement';s:=s-'_eCause';e_gate:=ml_private.p3e_gate(s,a,e_source,jsonb_build_array(ml_private.stage3_task('e-relocate',jsonb_build_object('actor',a,'data',jsonb_build_object('cell',cell,'voluntary',voluntary,'carry',carry,'reactive',coalesce(s->>'_gearReactiveSkip','false')<>'true','source',e_source,'root',e_root)))),e_root);if e_gate is not null then return s||jsonb_build_object('_relocationTasks',e_gate);end if;s:=jsonb_set(s,'{stage3,e,current}',to_jsonb(e_root));end if;
 if coalesce(s->>'_eProbe','false')<>'true' then s:=ml_private.p3h_circle_gate(s,a,cell,jsonb_build_array(ml_private.stage3_task('e-relocate',jsonb_build_object('actor',a,'data',jsonb_build_object('cell',h_requested,'voluntary',voluntary,'carry',carry,'reactive',coalesce(s->>'_gearReactiveSkip','false')<>'true','source',e_source,'root',e_root)))),e_root,h_placement,case when h_requested<>cell then ml_private.p3h_circle_line(s,origin,cell) else null end);e_gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if e_gate<>'null'::jsonb then return s||jsonb_build_object('_relocationTasks',e_gate);end if;end if;
 snapshots:=case when carry then ml_private.stage3_carry_candidates(s,a,origin) else '[]'::jsonb end;
 s:=ml_private.classic_relocated(s,a,origin,cell);s:=jsonb_set(s,array['players',a::text,'cell'],to_jsonb(cell));if voluntary then s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');end if;s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell);
 if not h_placement then s:=ml_private.p3h_small_crossed(s,a,origin,cell,false,e_root);tasks:=tasks||(s->'_hSmallTasks');s:=s-'_hSmallTasks';end if;if ml_private.classic_owes_water(s,a,origin) then tasks:=tasks||jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true)));end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then if ml_private.p3f_enabled(s) then s:=ml_private.p3f_arrival(s,a,origin,cell);tasks:=tasks||ml_private.p3f_arrival_order(s,a,origin,cell,coalesce(s->>'_gearReactiveSkip','false')<>'true');s:=s-'_fArrival';else tasks:=tasks||ml_private.stage4_arrival_tasks(s,a,origin,cell);end if;if voluntary and coalesce(s->>'_gearReactiveSkip','false')<>'true' then tasks:=tasks||ml_private.stage4_landing_tasks(s,a);end if;end if;
 if jsonb_array_length(snapshots)>0 then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',a,'data',snapshots)));end if;
 if ml_private.p3e_enabled(s) then s:=ml_private.p3e_moved(s,origin,cell,e_root);tasks:=tasks||(s->'_eggTasks');s:=s-'_eggTasks';end if;return s||jsonb_build_object('_relocationTasks',tasks);
end $$;
create or replace function ml_private.stage3_collision(s jsonb,cell text) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int;target integer;path jsonb;snapshots jsonb;tasks jsonb:='[]';c jsonb;f_exit text;begin
 select (p->>'seat')::int into target from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (p->>'seat')::int<>a and ml_private.p3h_blocks(s,a,(p->>'seat')::int) and p->>'cell'=cell limit 1;
 if target is null or s#>>array['players',a::text,'character']<>'character-045' then return s||jsonb_build_object('_pushedTasks',tasks);end if;
 path:=ml_private.stage3_collision_path(ml_private.stage3_board(s),a,target,ml_private.stage3_direction(s,s#>>array['players',a::text,'cell'],cell));if ml_private.p3f_enabled(s) and s->>'_eProbe'='true' then select v#>>'{}' into f_exit from jsonb_array_elements(path) with ordinality q(v,n) where not ml_private.stage4_board_water(s,v#>>'{}',target) order by n limit 1;if f_exit is not null then s:=ml_private.p3f_move_gate(s,target,f_exit);s:=s-'_fMoveAllowed';end if;end if;perform ml_private.need(jsonb_array_length(path)>0,'角色或地形阻挡冲撞');snapshots:=ml_private.stage3_carry_candidates(s,target,s#>>array['players',target::text,'cell']);
 for c in select * from ml_private.arr(path) loop if ml_private.p3e_enabled(s) then s:=ml_private.p3e_relocate(s,target,c#>>'{}',false,false,true,case when s->>'_eProbe'='true' then target else a end,ml_private.p3e_root(s));else s:=ml_private.stage3_relocate(s,target,c#>>'{}',false,false);end if;tasks:=tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';end loop;
 if jsonb_array_length(snapshots)>0 then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',target,'data',snapshots)));end if;return s||jsonb_build_object('_pushedTasks',tasks);
end $$;
create or replace function ml_private.stage3_complete_draft(r ml_private.rooms,at bigint) returns ml_private.rooms language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare setup jsonb;start_at double precision;teams jsonb;begin
 if r.status<>'drafting' or r.draft->>'status'<>'complete' then return r;end if;
 start_at:=(r.draft#>>'{events,-1,at}')::double precision;
 select jsonb_agg(to_jsonb(case when x#>>'{}'='机械猴子' then 'A' else 'B' end) order by ord) into teams from jsonb_array_elements(r.draft->'teams') with ordinality q(x,ord);
 setup:=jsonb_build_object('mode',r.mode,'ruleVersion',case when r.draft->>'catalogVersion' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then r.draft->>'catalogVersion' else 'web-v0.1.6' end,'seed',r.draft#>'{random,seed}','seats','[0,1,2,3]'::jsonb,'characters',r.draft->'selected','first',r.draft#>'{order,0}','secure',coalesce(r.draft#>'{random,secure}','false'),'dice',r.draft#>'{random,dice}','bombs',r.draft#>'{random,bombs}','reshuffles',r.draft#>'{random,reshuffles}','sortedReshuffles',r.draft#>'{random,sortedReshuffles}');
 if r.mode='team' then setup:=setup||jsonb_build_object('teams',teams);end if;
 r.game:=ml_private.create_game(setup,start_at);r.status:='playing';r.revision:=r.revision+1;r.updated_at:=at;return r;
end $$;
create or replace function ml_private.stage4_board_effect(s jsonb,a integer,effect jsonb,tag text default null) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select s->'players'->a is not null and ml_private.character_effect_allowed(effect,a,s#>>array['players',a::text,'character'])
 and not(s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['players',a::text,'character']='character-006' and (effect->>'actor')::int<>a and effect->>'faction'<>'机械猴子')
 and not(s#>>array['players',a::text,'character']='character-005' and coalesce(tag,'')='建民') $$;
create or replace function ml_private.stage4_board_entry(s jsonb,a integer,cell text) returns boolean language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=ml_private.game_data(s,'map')->cell;b jsonb;begin
 if c is null or coalesce((s#>>'{classic,farmClosed}')::boolean,(s->>'farmClosed')::boolean,false) and c->>'region'='高唐农场' then return false;end if;
 if ml_private.stage4_board_water(s,cell,a) and exists(select 1 from ml_private.arr(coalesce(ml_private.p3h_gear_cards(s,a),'[]')) v where ml_private.stage4_equipment_definition(s,v#>>'{}') in ('basic-063','basic-064')) then return false;end if;
 for b in select * from ml_private.arr(coalesce(s#>'{stage4,blocks}','[]')) loop
  if b->>'region'=c->>'region' and (s#>>array['players',b->>'owner','hp'])::int>0 and (s#>>array['stage3','starts',b->>'owner'])::int<(b->>'until')::int and a<>(b->>'owner')::int
   and not(s->>'mode'='team' and s#>array['players',a::text,'team']=s#>array['players',b->>'owner','team']) and not(b->'exempt' @> jsonb_build_array(a)) and ml_private.stage4_board_effect(s,a,b->'effect','建民') then return false;end if;
 end loop;return true;
end $$;
create or replace function ml_private.stage4_board_empty(s jsonb,a integer,cell text,ignored jsonb default '[]') returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select (coalesce(s->>'_fPlacement','false')='true' or ml_private.p3f_preview_move(s,a,cell)) and (s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],cell,ignored) is not null) and ml_private.stage4_board_entry(s,a,cell) and not exists(select 1 from ml_private.arr(s->'players') p where ml_private.stage4_on_board(s,(p->>'seat')::int) and ml_private.p3h_blocks(s,a,(p->>'seat')::int) and p->>'cell'=cell and not(ignored @> jsonb_build_array(p->'seat'))) $$;
create or replace function ml_private.stage4_ignore_location(s jsonb,a integer) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select case when ml_private.p3g_enabled(s) then exists(select 1 from ml_private.arr(ml_private.p3h_gear_cards(s,a)) v where ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-069' and s#>>array['stage3','g','gearTerrain',v#>>'{}']='true' and ml_private.stage3_card_allowed(s,a,v#>>'{}',ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment'))) else coalesce(s#>>array['stage4','terrainIgnore',a::text],'false')='true' and ml_private.stage3_equipped(s,a,'basic-069') end $$;
create or replace function ml_private.stage4_location_move_cost(s jsonb,a integer) returns integer language sql stable
set search_path=pg_catalog,ml_private as $$ select case when ml_private.p3h_pending_birth(s,a) then 1 when ml_private.stage4_ignore_location(s,a) then 1 else ml_private.location_basic_cost(s->>'version',s#>>array['players',a::text,'cell']) end $$;
create or replace function ml_private.choose_before_stage4(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';kind text:=c->>'kind';a integer:=(c->>'actor')::int;target integer:=(cmd->>'target')::int;card text:=cmd->>'card';cell text:=cmd->>'cell';pending jsonb;quoted jsonb;result jsonb;cards jsonb;cells jsonb;amount integer;snapshot jsonb;tasks jsonb:='[]';old text;begin if ml_private.p3h_enabled(s) and kind='h-birth' then return ml_private.p3h_birth_choose(s,cmd,at,timeout);end if; if ml_private.p3g_enabled(s) then perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');end if;s:=ml_private.p3h_gear_choose(s,cmd,at,timeout);if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_small_choose(s,cmd,at,timeout);end if;if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_leap_choose(s,cmd,at,timeout);end if;if s->>'_hHandled'<>'true' then s:=s-'_hHandled';s:=ml_private.p3h_ren_choose(s,cmd,at,timeout);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_cooperate_choose(s,cmd,timeout);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_circle_choose(s,cmd,at,timeout);end if;if s->>'_hHandled'<>'true' then s:=ml_private.p3h_choose(s,cmd,at,timeout);end if;if s->>'_hHandled'='true' then s:=s-'_hHandled';if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||ml_private.p3h_choice_label(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=ml_private.resume(jsonb_set(s,'{phase}','"action"'),at);end if;return s;end if;s:=s-'_hHandled';s:=ml_private.p3g_haki_choose(s,cmd,at,timeout);if s->>'_gHakiHandled'='true' then s:=s-'_gHakiHandled';if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=ml_private.resume(jsonb_set(s,'{phase}','"action"'),at);end if;return s;end if;s:=s-'_gHakiHandled';s:=ml_private.p3g_food_choose(s,cmd,at,timeout);if s->>'_gFoodHandled'='true' then s:=s-'_gFoodHandled';if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=ml_private.resume(jsonb_set(s,'{phase}','"action"'),at);end if;return s;end if;s:=s-'_gFoodHandled';s:=ml_private.p3g_observer_choose(s,cmd,at,timeout);if s->>'_gObserverHandled'='true' then s:=s-'_gObserverHandled';if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=ml_private.resume(jsonb_set(s,'{phase}','"action"'),at);end if;return s;end if;s:=s-'_gObserverHandled';s:=ml_private.p3g_card_choose(s,cmd,at,timeout);if s->>'_gCardHandled'='true' then s:=s-'_gCardHandled';if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and s->'queue'='[]'::jsonb and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=ml_private.resume(jsonb_set(s,'{phase}','"action"'),at);end if;return s;end if;s:=s-'_gCardHandled';
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.choose_before_stage3(s,cmd,at,timeout);end if;perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 case kind
 when 'f-tenacity','f-discard','f-target','f-self-harm','f-bccb','f-sting' then s:=ml_private.p3f_choose(s,cmd,at,timeout);if s#>'{choice,id}'<>c->'id' then return s;end if;
 when 'move-consent','egg-move','force-step' then s:=ml_private.p3e_choose(s,cmd,at,timeout);
 when 'encourage','encourage-discard' then s:=ml_private.p3d_choose(s,cmd,at,timeout);
 when 'primitive-food' then if cmd->>'accept'='true' and not timeout and ml_private.stage4_on_board(s,a) then s:=ml_private.p3g_owned_die(s,'你要不要吃',a);amount:=(s->>'_roll')::int;s:=s-'_roll';if amount>=5 then s:=ml_private.heal(s,a,1,false);end if;end if;
 when 'easy' then
 amount:=1;if cmd->>'accept'='true' and not timeout and at<(c->>'deadline')::double precision then s:=ml_private.p3g_owned_die(s,'easy 太简单了',a);amount:=(s->>'_roll')::int;s:=s-'_roll';end if;s:=ml_private.stage3_counter_card(s,a,cmd->>'accept'='true' and not timeout,at,amount);result:=s->'_counterResult';s:=s-'_counterResult';s:=ml_private.emit(s,'skill',case when result->>'attempted'='true' then 'S'||(a+1)||' 反制支付1AP，'||case when result->>'cancelled'='true' then '整牌失效' else '判定失败' end else 'S'||(a+1)||' 结束反制' end);if result->>'done'<>'true' then return s;end if;
 when 'response' then if card is not null and card<>'' then perform ml_private.need(c->'cards' ? card,'响应牌不可用');pending:=s#>'{cardStack,stack,-1}';perform ml_private.need(ml_private.stage3_responses(s,a,pending) ? card,'响应牌已失效');quoted:=case when ml_private.exercise_response(s,pending->>'definition',card) then jsonb_build_object('cost',0,'effect',jsonb_build_object('origin','card','actor',a,'faction',s#>array['players',a::text,'faction'],'roleModifiers','[]'::jsonb)) else ml_private.stage3_card_cost(s,a,card) end;quoted:=ml_private.p3g_prime_quote(s,a,quoted);s:=ml_private.p3d_pay(s,a,(quoted->>'cost')::int);s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));s:=ml_private.stage3_begin_card(s,a,card,split_part(card,'#',1),'[]',quoted->'effect',at,(pending->>'serial')::int);pending:=s#>'{cardStack,stack,-1}';s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));s:=ml_private.emit(s,'response','S'||(a+1)||' 使用'||(ml_private.rule_card(s,card)->>'name')||'，支付'||(quoted->>'cost')||'AP');end if;
 when 'xiao-overflow' then
 if timeout then select coalesce(jsonb_agg(x order by x),'[]') into cards from (select x from ml_private.arr(s#>array['players',a::text,'hand']) x order by x limit (c->>'count')::int) q;else cards:=coalesce(cmd->'cards','[]');end if;s:=ml_private.stage3_transfer_overflow(s,a,(c->>'source')::int,cards);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 超限'||jsonb_array_length(cards)||'张交给S'||((c->>'source')::int+1));
 when 'qb-pursuit' then if cmd->>'accept'='true' and ml_private.stage3_alive(s,(c->>'source')::int) then s:=ml_private.p3g_owned_die(s,'QB 纯菜',a);target:=case when (s->>'_roll')::int>=3 then (c->>'source')::int else a end;s:=s-'_roll';s:=ml_private.stage3_damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')),false,true);s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'east-start' then if cmd ? 'action' then perform ml_private.need(ml_private.stage3_east_targets(s,a,cmd->>'action') @> jsonb_build_array(target),'领袖风范目标不合法');if cmd->>'action'='draw' then s:=ml_private.draw(s,a,1);s:=ml_private.draw(s,target,1);else cards:=s#>array['players',target::text,'hand'];s:=ml_private.int(s,jsonb_array_length(cards));amount:=(s->>'_int')::int;s:=s-'_int';s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(cards->amount));s:=jsonb_set(s,array['players',target::text,'hand'],cards-amount);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 从S'||(target+1)||' 随机拿1张');end if;end if;
 when 'xie-ledger' then if target is not null then perform ml_private.need(c->'targets' @> jsonb_build_array(target) and ml_private.stage3_alive(s,target),'阎王薄目标不合法');s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'elbow-push' then target:=(c->>'source')::int;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if timeout then cell:=cells->>0;end if;if cell is null then perform ml_private.need(jsonb_array_length(cells)=0,'请选择一个撞飞方向');else perform ml_private.need(cells ? cell,'撞飞落点已失效');if ml_private.p3e_enabled(s) then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('e-elbow',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('cell',cell,'root',ml_private.p3e_root(s))))));else s:=ml_private.stage3_relocate(s,target,cell,false);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,c#>>'{data,origin}',true);tasks:=tasks||(s->'_relocationTasks');s:=ml_private.stage3_prepend(s-'_relocationTasks',tasks);end if;end if;
 when 'west-carry' then if target is not null then select x into snapshot from ml_private.arr(c->'data') x where (x->>'actor')::int=target;perform ml_private.need(snapshot is not null and cell is not null and ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,target,snapshot->>'origin') ? cell,'同行对象或落点不合法');s:=ml_private.stage3_relocate(s,target,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'equipment-loss' then old:=split_part(c#>>'{data,card}','#',1);if old='basic-054' and cmd->>'accept'='true' then s:=ml_private.heal(s,a,2);elsif old='basic-063' and cell is not null then perform ml_private.need(c->'cells' ? cell,'山洞落点不合法');s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'revival-confirm' then if cmd->>'accept'='true' then s:=ml_private.stage3_play(s,jsonb_build_object('type','play','id',cmd->'id','revision',cmd->'revision','actor',a,'card',c#>'{data,card}','targets',jsonb_build_array(c->'source')),at);end if;
 when 'teleport' then if cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.teleport_cells(s,a) ? cell,case when s->>'version' in ('web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then '传送须为全图合法空格' else '传送须为距离≤3的空陆地' end);s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' 传送至'||cell||case when s->'safe' ? cell then '' else '（毒圈外）' end);end if;
 when 'lemon-support' then if cmd->>'accept'='true' then perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=1 and s#>>array['players',a::text,'skillUsed']='false','支援不可用');s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-1));s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');for target in 0..3 loop if ml_private.stage3_alive(s,target) and (target=a or (s->>'mode'='team' and s#>array['players',target::text,'team']=s#>array['players',a::text,'team'])) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.draw(s,target,1);end if;end loop;s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 支援，支付1AP');end if;
 else s:=ml_private.choose_before_stage3(s,cmd,at,timeout);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
 end case;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||kind);end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
end $$;
create or replace function ml_private.public_view_before_stage4(s jsonb,viewer integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare v jsonb:=ml_private.public_view_before_stage3(s,viewer);r jsonb:=s->'stage3';safe jsonb;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return v;end if;select jsonb_object_agg(key,value) into safe from jsonb_each(r) where key in ('turn','equipment','basicUsed','breadBlocked','breadReadyAt','jjFree','jjExposed','horseLocks','combos');
 v:=(v-'cardStack'-'stage3')||jsonb_build_object('stage3',safe);return jsonb_set(v,'{actions,stage3}',ml_private.stage3_actions(s,viewer));
end $$;
create or replace function ml_private.stage3_damage_before_stage4(s jsonb,hits jsonb,environment boolean default false,skip_pursuit boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare h jsonb; p jsonb; a integer; src integer; blocked integer; loss integer; injured jsonb:='[]'; triggers jsonb:='[]'; begin
 s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));
 for h in select * from ml_private.arr(hits) loop
  a:=(h->>'target')::int; p:=s->'players'->a; if (p->>'hp')::int<=0 or (h->>'amount')::int<=0 then continue; end if;
  if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_prepare_hit(s,h,environment);h:=s->'_hit';s:=s-'_hit';if h='null'::jsonb then continue;end if;end if;
 if s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ((not environment and p->>'character'='character-037') or ml_private.stage3_equipped(s,a,'basic-059')) then h:=h||jsonb_build_object('amount',least(1,(h->>'amount')::int));end if;
 blocked:=case when h->>'trueDamage'='true' then 0 when environment and s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then 0 else least((p->>'shield')::int,(h->>'amount')::int) end; loss:=least((p->>'hp')::int,(h->>'amount')::int-blocked);
  p:=p||jsonb_build_object('shield',(p->>'shield')::int-blocked,'hp',(p->>'hp')::int-loss); s:=ml_private.put_player(s,a,p); src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s->'players'->src->>'damage')::int+loss,'kills',(s->'players'->src->>'kills')::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end)); end if;
  s:=ml_private.emit(s,'damage',ml_private.name(s,a)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',s->'batch'));
  if loss>0 then injured:=injured||jsonb_build_array(h||jsonb_build_object('loss',loss)); end if;
 end loop;
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=ml_private.exercise_discard(s,p->'hand'); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage3_death(s,a);end if;s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_after_damage(s,injured,environment);triggers:=s->'_gearTriggers';s:=s-'_gearTriggers';end if;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) and (s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',a,'roleModifiers','[]'::jsonb),src,s#>>array['players',src::text,'character'])) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop;
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not skip_pursuit then
 for h in select * from ml_private.arr(injured) loop src:=(h->>'source')::int;a:=(h->>'target')::int;
 if src is null or src=a or (s#>>array['players',src::text,'hp'])::int<=0 or (s#>>array['players',a::text,'hp'])::int<=0 or s#>>array['players',src::text,'character']<>'character-005' or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',src,'roleModifiers','[]'::jsonb),a,s#>>array['players',a::text,'character']) then continue;end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then
 if coalesce(s#>'{cardStack,stack,0,pursuits}','[]') @> jsonb_build_array(a) then continue;end if;
 s:=jsonb_set(s,'{cardStack,stack,0,pursuits}',coalesce(s#>'{cardStack,stack,0,pursuits}','[]')||jsonb_build_array(a));end if;
 triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','stage3','action','qb','actor',src,'target',a));end loop;end if;
 return s||jsonb_build_object('_triggers',triggers||ml_private.p3d_injury(s,injured));
end $$;
create or replace function ml_private.stage3_skill_before_stage4(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;kind text:=cmd->>'kind';target integer:=(cmd->>'target')::int;gear text;effect jsonb;cost integer;prior jsonb;card text:=cmd->>'card';begin
 if kind='jj' then perform ml_private.need(p->>'character'='character-003' and s#>>array['stage3','jjUsed',a::text]<>'true','懒得喷本回合已使用或角色不符');s:=jsonb_set(s,array['stage3','jjUsed',a::text],'true');s:=jsonb_set(s,array['stage3','jjFree',a::text],'true');s:=jsonb_set(s,array['stage3','jjExposed',a::text],'true');return ml_private.emit(s,'skill','S'||(a+1)||' 懒得喷：固定费用免费，暴露至下次个人回合开始');end if;
 if kind='bread' and ml_private.p3g_enabled(s) then gear:=ml_private.p3g_bread_equipment(s,a,card);effect:=ml_private.p3h_gear_source(s,a,gear);perform ml_private.need(gear is not null and target<>a and ml_private.stage3_alive(s,target),'面包技能或目标不可用');cost:=ml_private.stage3_fixed_cost(s,a,2);perform ml_private.need((p->>'ap')::int>=cost,'面包技能需要2AP');s:=ml_private.p3d_pay(s,a,cost);effect:=effect||jsonb_build_object('origin','equipment');if s#>>array['stage3','jjFree',a::text]='true' then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','cost')));end if;prior:=s#>array['stage3','breadPending',target::text];s:=ml_private.p3g_bread(s,a,target,gear);if not ml_private.stage3_card_allowed(s,target,'basic-054',effect) then s:=jsonb_set(s,array['stage3','breadPending',target::text],prior);end if;return ml_private.emit(s,'skill','S'||(a+1)||' 面包黏稠，支付'||cost||'AP');end if;if kind='bread' then
 select c#>>'{}' into gear from ml_private.arr(s#>array['stage3','equipment',a::text]) c where split_part(c#>>'{}','#',1)='basic-054' limit 1;effect:=s#>array['stage3','equipmentSources',gear];perform ml_private.need(gear is not null and effect is not null and (s#>>array['stage3','starts',a::text])::int>=(s#>>array['stage3','breadReadyAt',a::text])::int and target<>a and ml_private.stage3_alive(s,target),'面包技能或目标不可用');cost:=ml_private.stage3_fixed_cost(s,a,2);perform ml_private.need((p->>'ap')::int>=cost,'面包技能需要2AP');s:=ml_private.p3d_pay(s,a,cost);effect:=effect||jsonb_build_object('origin','equipment');if s#>>array['stage3','jjFree',a::text]='true' then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','cost')));end if;
 prior:=s#>array['stage3','breadPending',target::text];s:=ml_private.stage3_bread(s,a,target);if not ml_private.stage3_card_allowed(s,target,'basic-054',effect) then s:=jsonb_set(s,array['stage3','breadPending',target::text],prior);end if;return ml_private.emit(s,'skill','S'||(a+1)||' 面包黏稠，支付'||cost||'AP');end if;
 perform ml_private.need(split_part(card,'#',1)='basic-037' and jsonb_array_length(ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean))>0,'当前没有合法紫檀木复活目标');
 if s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then cost:=(s#>>array['stage3','costLocks',card,'cost'])::int;else s:=ml_private.p3g_owned_die(s,'紫檀木费用',a);cost:=(s->>'_roll')::int;s:=s-'_roll';s:=ml_private.stage3_lock_cost(s,a,card,cost);s:=s-'_cost';end if;return ml_private.select_choice(s,'revival-confirm',a,at,jsonb_build_object('source',target,'data',jsonb_build_object('card',card,'cost',cost)));
end $$;
create or replace function ml_private.stage3_handle_task_before_stage4(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer;origin text;targets jsonb;cells jsonb;valid jsonb;pending jsonb;d jsonb;after_tasks jsonb:='[]';cards jsonb;hits jsonb:='[]';roll integer:=0;paid integer;amount integer;before_hp jsonb;xie integer;ledger jsonb:='[]';old text;old_source jsonb;closed jsonb;idx text;gained integer;begin
 if action='east' then targets:=ml_private.stage3_east_targets(s,a,'draw');if jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'east-start',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='elbow-hit' then target:=(t->>'target')::int;if not ml_private.stage3_alive(s,a) or not ml_private.stage3_alive(s,target) then return s;end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack')));s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(ml_private.stage3_task('elbow-push',jsonb_build_object('actor',a,'target',target,'data',jsonb_strip_nulls(jsonb_build_object('origin',origin,'direction',s#>'{cardStack,stack,-1,pushDirection}'))))));return s-'_triggers';end if;
 if action='qb' then target:=(t->>'target')::int;if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,target) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.select_choice(s,'qb-pursuit',a,at,jsonb_build_object('source',target));end if;return s;end if;
 if action='ledger' then select coalesce(jsonb_agg(x order by ord),'[]') into targets from jsonb_array_elements(t->'data') with ordinality q(x,ord) where ml_private.stage3_alive(s,(x#>>'{}')::int);if ml_private.stage3_alive(s,a) and jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'xie-ledger',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='carry' then select coalesce(jsonb_agg(x order by ord),'[]') into valid from jsonb_array_elements(t->'data') with ordinality q(x,ord) where jsonb_array_length(ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin'))>0;if ml_private.stage3_alive(s,a) and jsonb_array_length(valid)>0 then select jsonb_agg(x->'actor' order by ord) into targets from jsonb_array_elements(valid) with ordinality q(x,ord);s:=ml_private.select_choice(s,'west-carry',a,at,jsonb_build_object('targets',targets,'data',valid,'options',(select jsonb_object_agg(x->>'actor',ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin')) from ml_private.arr(valid) x)));end if;return s;end if;
 if action='elbow-push' then target:=(t->>'target')::int;origin:=t#>>'{data,origin}';if not ml_private.stage3_alive(s,a) then return s;end if;if not ml_private.stage3_alive(s,target) then if ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,origin) then s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if jsonb_array_length(cells)>0 and t#>>'{data,direction}' is not null and cells ? ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],t#>>'{data,direction}') then if ml_private.p3e_enabled(s) then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('e-elbow',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('cell',ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],t#>>'{data,direction}'),'root',ml_private.p3e_root(s))))));end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.stage3_relocate(s,target,ml_private.stage3_direction_cell(origin,t#>>'{data,direction}'),false);after_tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,after_tasks||(s->'_relocationTasks'));return s-'_relocationTasks';end if;if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'elbow-push',a,at,jsonb_build_object('source',target,'cells',cells,'data',jsonb_build_object('origin',s#>array['players',target::text,'cell'])));end if;return s;end if;
 pending:=s#>'{cardStack,stack,-1}';perform ml_private.need(pending is not null,'没有待结算卡牌');perform ml_private.need(not (t ? 'serial') or t->'serial'=pending->'serial','卡牌结算编号过期');a:=(pending->>'actor')::int;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;d:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',pending->>'definition'];
 if action='equip-install' then if ml_private.stage3_alive(s,a) then s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])||jsonb_build_array(pending->'card'));s:=jsonb_set(s,array['stage3','equipmentSources',pending->>'card'],pending->'effect');s:=jsonb_set(s,'{resolving}',(s->'resolving')-(pending->>'card'));s:=jsonb_set(s,array['cardStack','stack',idx,'installed'],'true');valid:=to_jsonb(coalesce(ml_private.stage3_equipped(s,a,'basic-066') and s#>array['stage3','previousBasic',a::text]='false'::jsonb,false));s:=jsonb_set(s,array['stage3','doubleMove',a::text],valid);s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when valid='true'::jsonb then 2 else 1 end));s:=ml_private.emit(s,'equip','S'||(a+1)||' 装备'||(d->>'name'));end if;return s;end if;
 if action='counter' then if pending->'counter'<>'null'::jsonb then s:=ml_private.select_choice(s,'easy',(pending#>>'{counter,actor}')::int,at,jsonb_build_object('deadline',pending#>'{counter,deadline}','data',jsonb_build_object('serial',pending->'serial')));end if;return s;end if;
 if action='continue' then if ml_private.p3f_enabled(s) and pending->>'countered'='false' and pending->'responseTo'='null'::jsonb then s:=ml_private.p3f_card_targets(s);after_tasks:=s->'_fTargets';s:=s-'_fTargets';pending:=s#>'{cardStack,stack,-1}';if jsonb_array_length(after_tasks)>0 then return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('f-card-resume',jsonb_build_object('serial',pending->'serial'))));end if;end if;
 if pending->>'countered'='true' or pending->'responseTo'<>'null'::jsonb then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));end if;
 if d->>'type'='attack' or pending->>'definition'='basic-002' then s:=jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));targets:=ml_private.stage3_available_targets(s,pending);s:=ml_private.p3c_mark_food(s,targets);select coalesce(jsonb_agg(ml_private.stage3_task('response',jsonb_build_object('actor',x,'serial',pending->'serial')) order by ord),'[]') into after_tasks from jsonb_array_elements(s->'order') with ordinality q(x,ord) where targets @> jsonb_build_array(x);end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('effect',jsonb_build_object('serial',pending->'serial'))));end if;
 if action='response' then target:=(t->>'actor')::int;if ml_private.stage3_available_targets(s,pending) @> jsonb_build_array(target) then cards:=ml_private.stage3_responses(s,target,pending);if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',target,at,jsonb_build_object('cards',cards,'data',jsonb_build_object('serial',pending->'serial')));end if;end if;return s;end if;
 if action='cleanup' then s:=ml_private.stage3_close_card(s);closed:=s->'_closed';s:=s-'_closed';s:=ml_private.p3c_food_tasks(s,closed);if closed->>'installed'='true' then s:=jsonb_set(s,'{discard}',(s->'discard')-(closed->>'card'));end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then pending:=s#>'{cardStack,stack,-1}';return jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));end if;s:=jsonb_set(s,'{attack}','null');s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then if ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;end if;return s;end if;
 perform ml_private.need(action='effect','未知阶段三结算任务');s:=ml_private.stage3_record_combo(s,a,pending->>'definition');targets:=ml_private.stage3_available_targets(s,pending);s:=ml_private.p3c_mark_food(s,targets);
 if pending->>'definition'='basic-002' then select coalesce(jsonb_agg(ml_private.stage3_task('elbow-hit',jsonb_build_object('actor',a,'target',x)) order by ord),'[]') into after_tasks from jsonb_array_elements(targets) with ordinality q(x,ord);
 elsif d->>'type'='attack' then
 select jsonb_agg(member->'hp' order by ord) into before_hp from jsonb_array_elements(s->'players') with ordinality q(member,ord);select (member->>'seat')::int into xie from ml_private.arr(s->'players') member where (member->>'hp')::int>0 and member->>'character'='character-044' limit 1;if xie is not null and pending->>'definition'='basic-010' then ledger:=ml_private.stage3_ledger_candidates(s,xie,a,targets);end if;
 if jsonb_array_length(targets)>0 and pending->>'definition' in ('basic-006','basic-009') then s:=ml_private.p3g_owned_die(s,d->>'name',(pending->>'actor')::int);roll:=(s->>'_roll')::int;s:=s-'_roll';end if;
 for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop
 if d ? 'power' then paid:=least((s#>>array['players',target::text,'ap'])::int,(d->>'power')::int);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-paid));s:=ml_private.emit(s,'ap','S'||(target+1)||' 被扣'||paid||'AP → '||(s#>>array['players',target::text,'ap']));if paid<(d->>'power')::int then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',(d->>'power')::int-paid,'source',a,'category','attack'));end if;
 elsif pending->>'definition'='basic-008' then amount:=(s#>>array['players',target::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));else s:=jsonb_set(s,array['players',target::text,'ap'],'0');s:=ml_private.stage3_gain_ap(s,a,amount);s:=ml_private.emit(s,'ap','S'||(a+1)||' 头锤吸收全部'||amount||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end if;
 else
 if pending->>'definition'='basic-010' then s:=ml_private.p3g_owned_die(s,'S'||(target+1)||' 猴子游戏',target);valid:=to_jsonb((s->>'_roll')::int%2=1);s:=s-'_roll';else valid:=to_jsonb(roll>=4);end if;if valid='true'::jsonb then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));end if;end if;end loop;
 for target in select (x#>>'{}')::int from ml_private.arr(pending->'elbows') x loop if not ml_private.stage3_alive(s,target) then continue;end if;amount:=(s#>>array['players',a::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',target,'category','response'));else amount:=least(2,amount);s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-amount));s:=ml_private.stage3_gain_ap(s,target,amount);s:=s-'_gain';end if;end loop;
 s:=ml_private.damage(s,hits);after_tasks:=s->'_triggers';s:=s-'_triggers';if pending->>'definition'='basic-006' and ml_private.stage3_alive(s,a) then if ml_private.p3f_enabled(s) then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('f-vampire',jsonb_build_object('actor',a,'data',jsonb_build_object('token',s#>'{stage3,f,hitSerial}','targets',targets))));else select coalesce(sum((before_hp->>(x#>>'{}')::int)::int-(s#>>array['players',x#>>'{}','hp'])::int),0)::int into amount from ml_private.arr(targets) x;s:=ml_private.heal(s,a,amount);end if;end if;
 if jsonb_array_length(ledger)>0 and xie is not null then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('ledger',jsonb_build_object('actor',xie,'data',ledger)));end if;
 elsif d->>'type'='food' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.heal(s,target,case when pending->>'definition'='basic-046' then 2 else 1 end,true);if pending->>'definition'='basic-045' then s:=jsonb_set(s,array['players',target::text,'shield'],to_jsonb(least(2,(s#>>array['players',target::text,'shield'])::int+1)));end if;if pending->>'definition'='basic-047' then s:=ml_private.draw(s,target,2);end if;end loop;
 elsif pending->>'definition'='basic-015' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.stage3_coffee(s,target);s:=ml_private.emit(s,'ap','S'||(target+1)||' 咖啡获得'||(s#>>'{_gain,gained}')||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end loop;
 elsif pending->>'definition'='basic-016' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop if not ml_private.stage3_card_allowed(s,a,pending->>'definition',pending->'effect') or not ml_private.stage3_can_enter(s,a,s#>>array['players',target::text,'cell']) or not ml_private.stage3_can_enter(s,target,s#>>array['players',a::text,'cell']) then continue;end if;if ml_private.p3e_enabled(s) then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('e-swap',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('root',ml_private.p3e_root(s)))));continue;end if;origin:=s#>>array['players',a::text,'cell'];old:=s#>>array['players',target::text,'cell'];if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then cells:=jsonb_build_array(ml_private.playtest_relocation_cell(s,a,origin,old,jsonb_build_array(target)),ml_private.playtest_relocation_cell(s,target,old,origin,jsonb_build_array(a)));if cells->0='null'::jsonb or cells->1='null'::jsonb or cells->0=cells->1 then continue;end if;old:=cells->>0;origin:=cells->>1;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');end if;s:=ml_private.stage3_relocate(s,a,old,true);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,array['stage4','offMap',target::text],'false');end if;s:=ml_private.stage3_relocate(s,target,origin,false);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';end loop;
 elsif pending->>'definition'='basic-037' then for target in select (x#>>'{}')::int from ml_private.arr(pending->'targets') x loop if not ml_private.stage3_card_allowed(s,target,pending->>'definition',pending->'effect') then continue;end if;cells:=ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean);if jsonb_array_length(cells)=0 then continue;end if;s:=ml_private.int(s,jsonb_array_length(cells));old:=cells->>(s->>'_int')::int;s:=s-'_int';s:=ml_private.stage3_revive(s,target,old,(s#>>'{classic,farmClosed}')::boolean);if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.classic_native(s,target) and ml_private.stage4_board_water(s,old,target) then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('board-shore',jsonb_build_object('actor',target,'data',jsonb_build_object('cells',ml_private.playtest_nearest_shore(s,target)))));end if;s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');s:=ml_private.emit(s,'revive','S'||(target+1)||' 紫檀木复活于'||old||'：1HP、0AP、空手');end loop;
 elsif d->>'type'='equipment' then
 if pending ? 'replacement' then old:=pending->>'replacement';old_source:=s#>array['stage3','equipmentSources',old];s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])-old);s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-old);s:=ml_private.exercise_discard(s,jsonb_build_array(old));if old_source is not null and ml_private.stage3_card_allowed(s,a,old,old_source||jsonb_build_object('origin','equipment')) then cells:=null;if split_part(old,'#',1)='basic-063' then select coalesce(jsonb_agg(cell->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(cell,ord) where cell->>'region'='山洞' and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,cell->>'id');end if;if split_part(old,'#',1)='basic-054' or jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'equipment-loss',a,at,jsonb_build_object('data',jsonb_build_object('card',old))||case when cells is null then '{}'::jsonb else jsonb_build_object('cells',cells) end);end if;end if;end if;after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('equip-install',jsonb_build_object('serial',pending->'serial')));
 end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));
