create or replace function ml_private.stage3_play_before_stage4(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;card text:=cmd->>'card';d jsonb:=ml_private.rule_card(s,card);converted boolean:=coalesce(cmd->>'as','')='elbow';elbow boolean;boost boolean;quoted jsonb;effect jsonb;targets jsonb:=cmd->'targets';legal jsonb;cells jsonb;options jsonb;exposed jsonb;pending jsonb;idx text;cost integer;dodge boolean:=cmd->>'as'='dodge';begin
 if coalesce(dodge,false) then perform ml_private.need(ml_private.p3d_enabled(s) and p->>'character'='character-029','只有本版本奶龙大帝可以转换躲避球');d:=ml_private.rule_card(s,'basic-009');end if;
 perform ml_private.need(p->'hand' ? card and d is not null,'手中没有该实体牌');perform ml_private.need(s#>>array['stage3','breadBlocked',a::text]<>'true','面包：本个人回合不能主动出牌');elbow:=p->>'character'='character-023' and (converted or d->>'id'='basic-002');perform ml_private.need(ml_private.p3g_cube_face(s,a)<>1 or not(d->>'type'='attack' or elbow),'魔法有方1：本个人回合不能主动使用攻击牌');perform ml_private.need(not converted or p->>'character'='character-023','只有牢大可以转换肘击');perform ml_private.need(d->>'type'<>'response' or elbow,'响应牌只能在相应窗口使用');
 perform ml_private.need(p->>'character'<>'character-005' or converted or not (ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',d->>'id','tags'] ? '建民'),'QB不能使用建民牌');boost:=p->>'character'='character-045' and d->>'id'='basic-010';perform ml_private.need(boost or converted or ml_private.stage4_location_card(s,a,d->>'id'),'当前位置禁止使用此牌');
 if coalesce(dodge,false) then quoted:=jsonb_build_object('cost',2,'effect',jsonb_build_object('origin','role-active','actor',a,'faction',p->'faction','roleModifiers',jsonb_build_array(jsonb_build_object('actor',a,'kind','conversion'))));elsif converted then quoted:=jsonb_build_object('cost',ml_private.stage3_fixed_cost(s,a,2),'effect',jsonb_build_object('origin','role-active','actor',a,'faction',p->'faction','roleModifiers',jsonb_build_array(jsonb_build_object('actor',a,'kind','conversion'))));
 else quoted:=ml_private.stage3_card_cost(s,a,card,case when s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then (s#>>array['stage3','costLocks',card,'cost'])::int else null end);end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s->>'_stage4Free'='true' then quoted:=jsonb_build_object('cost',0,'effect',jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers',coalesce(s#>array['stage4','buffSources',a||':exerciseFree','roleModifiers'],'[]')));end if;quoted:=ml_private.p3g_prime_quote(s,a,quoted);effect:=quoted->'effect';if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and coalesce(cmd->>'as','')<>'elbow' then effect:=ml_private.stage4_attack_effect(s,a,case when dodge then 'basic-009' else card end,effect);end if;
 if elbow and not converted then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','other')));end if;if boost then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','target')));end if;cost:=(quoted->>'cost')::int;
 perform ml_private.need((p->>'ap')::int>=cost,'需要'||cost||'AP');perform ml_private.need((select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标不能重复');
 if elbow then perform ml_private.need(jsonb_array_length(targets)=1 and ml_private.stage3_elbow_targets(s,a,converted) @> targets,'主动肘击目标不合法');
 elsif d->>'type'='attack' then legal:=case when dodge then ml_private.p3d_dodge_targets(s,a) else ml_private.targets(s,a,card) end;perform ml_private.need(jsonb_array_length(targets) between 1 and case when d->>'group'='true' then 3 else 1 end and legal @> targets,'攻击目标不合法');
 elsif d->>'id'='basic-016' then perform ml_private.need(ml_private.p3g_card_target_allowed(s,a,(targets->>0)::int,'basic-016') and jsonb_array_length(targets)=1 and (targets->>0)::int<>a and ml_private.stage3_alive(s,(targets->>0)::int) and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,s#>>array['players',targets->>0,'cell'],jsonb_build_array(a,targets->0)) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),(targets->>0)::int,p->>'cell',jsonb_build_array(a,targets->0)),'交换目标或坐骑位移限制不合法');
 elsif d->>'id'='basic-037' then perform ml_private.need(jsonb_array_length(targets)=1 and jsonb_array_length(ml_private.stage3_revival_cells(s,(targets->>0)::int,(s#>>'{classic,farmClosed}')::boolean))>0,'当前没有合法复活目标');
 else perform ml_private.need(targets='[]'::jsonb,'此牌不接受外部目标');targets:=case when d->>'id'='basic-041' then ml_private.stage3_assam_targets(s,a) else jsonb_build_array(a) end;end if;
 targets:=ml_private.playtest_north_targets(s,targets,cmd->>'northGroup',d->>'type'<>'attack' and not elbow and d->>'id' not in ('basic-016','basic-037'));
 if not converted and d->>'type'='equipment' then options:=ml_private.stage3_equipment_options(s,a,card);perform ml_private.need(options->>'allowed'='true' and (options->>'required'<>'true' or cmd ? 'replacement') and (not (cmd ? 'replacement') or options->'cards' ? (cmd->>'replacement')),'请先选择合法装备替换对象');perform ml_private.need(d->>'id'<>'basic-063' or ml_private.game_data(s,'map')#>>array[p->>'cell','terrain']<>'water','水中不能装备禁水的哈基米');end if;
 if elbow then cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,(targets->>0)::int);perform ml_private.need(jsonb_array_length(cells)=0 or (cmd ? 'direction') and cells ? ml_private.stage3_direction_cell(s#>>array['players',targets->>0,'cell'],cmd->>'direction'),'请先选择合法撞飞方向');end if;exposed:=ml_private.stage3_jj_targets(s,a,case when elbow then 'basic-002' when dodge then 'basic-009' else card end,targets,effect);targets:=ml_private.playtest_north_targets(s,exposed->'targets');effect:=exposed->'effect';p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card);if d->>'type'='attack' or elbow then p:=p||jsonb_build_object('attacks',(p->>'attacks')::int+1);end if;s:=ml_private.put_player(s,a,p);s:=ml_private.p3d_paid(s,a,(p->>'ap')::int+cost,cost);s:=s||jsonb_build_object('resolving',(s->'resolving')||jsonb_build_array(card),'clock',jsonb_build_object('remaining',60000,'since',at));
 s:=ml_private.stage3_begin_card(s,a,card,case when elbow then 'basic-002' else d->>'id' end,targets,effect,at);pending:=s#>'{cardStack,stack,-1}';if elbow then pending:=pending||jsonb_build_object('converted',converted);if cmd ? 'direction' then pending:=pending||jsonb_build_object('pushDirection',cmd->'direction');end if;end if;if cmd ? 'replacement' then pending:=pending||jsonb_build_object('replacement',cmd->'replacement');end if;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx],pending);
 s:=ml_private.emit(s,'play','S'||(a+1)||' 使用'||case when elbow then '肘击' else d->>'name' end||'，支付'||cost||'AP',jsonb_build_object('actor',a,'card',card,'targets',targets));s:=jsonb_set(s,'{phase}','"resolving"');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage4_change_faction(s jsonb,target integer,kind text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 perform ml_private.need(s ? 'stage4' and ml_private.stage3_alive(s,target),'阵营变更目标无效');
 s:=jsonb_set(s,array['stage4','conversion',target::text],coalesce(to_jsonb(kind),'null'::jsonb));
 s:=jsonb_set(s,array['players',target::text,'faction'],case when kind is null then s#>array['stage4','baseFactions',target::text] else to_jsonb(case when kind='monkey' then '机械猴子' else '帝汶家族' end) end);
 if s->>'mode'='team' then s:=jsonb_set(s,array['players',target::text,'team'],case when kind is null then s#>array['stage4','baseTeams',target::text] else to_jsonb(case when kind='monkey' then 'A' else 'B' end) end);end if;return ml_private.p3h_gear_refresh(s);
end $$;
create or replace function ml_private.stage4_equipment_skill(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;kind text:=cmd->>'kind';card text;watch jsonb;cell text:=cmd->>'cell';target integer:=(cmd->>'target')::int;cards jsonb:=coalesce(cmd->'cards','[]');cost integer;begin
 if kind='terrain' and ml_private.p3g_enabled(s) then s:=ml_private.p3g_terrain_setting(s,cmd);return ml_private.emit(s,'terrain','S'||(a+1)||' 唐车'||case when cmd->>'accept'='true' then '忽略' else '恢复' end||'地点效果')||jsonb_build_object('_equipmentSkill',true);end if;if kind='terrain' then perform ml_private.need(ml_private.stage4_on_board(s,a) and ml_private.stage4_combat_gear(s,a,'basic-069') is not null and jsonb_typeof(cmd->'accept')='boolean','唐车设置不可用或选项无效');s:=jsonb_set(s,array['stage4','terrainIgnore',a::text],cmd->'accept');return ml_private.emit(s,'terrain','S'||(a+1)||' 唐车'||case when cmd->>'accept'='true' then '忽略' else '恢复' end||'地点效果')||jsonb_build_object('_equipmentSkill',true);end if;
 if kind not in ('watch','flight','gift') then return s||jsonb_build_object('_equipmentSkill',false);end if;
 perform ml_private.need(kind='gift' or not ml_private.stage3_mount_blocked(s,a),'当前不能主动位移或发动该坐骑');
 if kind='watch' then
  if ml_private.p3g_enabled(s) then select v#>>'{}' into card from jsonb_array_elements(ml_private.p3h_gear_cards(s,a)) with ordinality q(v,n) where ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-060' and ml_private.stage3_card_allowed(s,a,v#>>'{}',ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment')) and (cmd->>'card' is null or v#>>'{}'=cmd->>'card') and (ml_private.p3h_gear_watch(s,a,v#>>'{}')->>'previous') is not null and (ml_private.p3h_gear_watch(s,a,v#>>'{}')->'usedTurn') is distinct from s#>'{stage3,turn}' and (ml_private.p3h_gear_watch(s,a,v#>>'{}')->>'previous')<>p->>'cell' and ml_private.stage4_board_empty(s,a,(ml_private.p3h_gear_watch(s,a,v#>>'{}')->>'previous'),jsonb_build_array(a)) order by n limit 1;else card:=ml_private.stage4_combat_gear(s,a,'basic-060');end if;watch:=ml_private.p3h_gear_watch(s,a,card);
  perform ml_private.need(card is not null and watch->>'previous' is not null and watch->'usedTurn' is distinct from s#>'{stage3,turn}','手表尚无上一开始格或本回合已使用');
  perform ml_private.need(ml_private.stage4_board_empty(s,a,watch->>'previous',jsonb_build_array(a)) and watch->>'previous'<>p->>'cell','手表原格当前不可进入');
  s:=jsonb_set(s,array['stage4','watches',card,'usedTurn'],s#>'{stage3,turn}');s:=ml_private.stage3_relocate(s,a,watch->>'previous',true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'));s:=ml_private.emit(s-'_relocationTasks','skill','S'||(a+1)||' 手表回到上次个人开始格');
 elsif kind='flight' then
  perform ml_private.need(ml_private.stage4_combat_gear(s,a,'basic-074') is not null and p->>'moved'<>'true','子腾未装备或基础移动次数已用');
  perform ml_private.need(cell is not null and cell<>p->>'cell' and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)),'请选择合法传送空格');
  cost:=ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a))+1;perform ml_private.need((p->>'ap')::int>=cost,'子腾需要'||cost||'AP');
  s:=ml_private.p3d_pay(s,a,cost);s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int+1));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));
  s:=ml_private.stage3_relocate(s,a,cell,true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'));s:=ml_private.emit(s-'_relocationTasks','cost','S'||(a+1)||' 子腾传送支付'||cost||'AP，不掷移动骰');
 else
  perform ml_private.need(ml_private.stage4_combat_gear(s,a,'basic-075') is not null,'未装备快速车');
  perform ml_private.need(target<>a and ml_private.stage4_on_board(s,target) and jsonb_array_length(cards)>0 and (select count(distinct v) from ml_private.arr(cards) v)=jsonb_array_length(cards) and p->'hand' @> cards,'送牌对象或实体手牌不合法');
  s:=jsonb_set(s,array['players',a::text,'hand'],(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(p->'hand') with ordinality q(v,ord) where not(cards @> jsonb_build_array(v))));s:=jsonb_set(s,array['players',target::text,'hand'],(s#>array['players',target::text,'hand'])||cards);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 快速车送S'||(target+1)||' '||jsonb_array_length(cards)||'张手牌');
 end if;return s||jsonb_build_object('_equipmentSkill',true);
end $$;
create or replace function ml_private.stage4_combat_gear(s jsonb,a integer,definition text) returns text language sql stable
set search_path=pg_catalog,ml_private as $$ select v#>>'{}' from jsonb_array_elements(ml_private.p3h_gear_cards(s,a)) with ordinality q(v,ord) where ml_private.stage4_equipment_definition(s,v#>>'{}')=definition and ml_private.stage3_card_allowed(s,a,v#>>'{}',ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment')) order by ord limit 1 $$;
create or replace function ml_private.stage4_attack_effect(s jsonb,a integer,card text,effect jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare gear text;definition text;mods jsonb:=effect->'roleModifiers';begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return effect;end if;
 for gear in select v#>>'{}' from ml_private.arr(ml_private.p3h_gear_cards(s,a)) v loop definition:=ml_private.stage4_equipment_definition(s,gear);
  if (ml_private.rule_card(s,card)->>'type'='attack' and (definition in ('basic-053','basic-058') or definition='basic-056' and split_part(card,'#',1)='basic-009')) or (case when ml_private.p3g_enabled(s) then s#>>array['stage3','g','gearTerrain',gear]='true' else ml_private.stage4_ignore_location(s,a) end) and definition='basic-069' then mods:=mods||coalesce(s#>array['stage3','equipmentSources',gear,'roleModifiers'],'[]');end if;
 end loop;return ml_private.p3d_effect(s,a,card,ml_private.p3c_effect(s,a,card,ml_private.p3_monkey_effect(s,a,card,jsonb_set(effect,'{roleModifiers}',mods))));
end $$;
create or replace function ml_private.stage4_prepare_hit(s jsonb,h jsonb,environment boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=ml_private.stage4_card_attack(s,h);a integer:=(h->>'target')::int;guard text;remaining integer;begin
 if ml_private.p3d_enabled(s) and s#>>array['players',a::text,'character']='character-029' and c->>'definition'='basic-009' then return s||jsonb_build_object('_hit',null);end if;
 if s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.p3_prepare_hit(s,h,environment);h:=s->'_hit';s:=s-'_hit';if h='null'::jsonb then return s||jsonb_build_object('_hit',null);end if;end if;
 h:=ml_private.p3f_modifiers(s,h);if h is null then return s||jsonb_build_object('_hit',null);end if;
 if c is not null and coalesce(h->>'extra','false')<>'true' and h->'source'<>'null'::jsonb and ml_private.stage4_combat_gear(s,(h->>'source')::int,'basic-053') is not null then h:=h||jsonb_build_object('trueDamage',true);end if;
 guard:=ml_private.stage4_combat_gear(s,a,'basic-070');
 if guard is not null and not environment and h->>'category'='attack' and coalesce(h->>'directHp','false')<>'true' and (h->>'amount')::int>0 then
  remaining:=coalesce((s#>>array['stage4','durability',guard])::int,2)-1;s:=jsonb_set(s,array['stage4','durability',guard],to_jsonb(remaining));s:=ml_private.emit(s,'block','S'||(a+1)||' 无一骑抵挡本次普通攻击，剩余'||remaining||'次');
  if remaining=0 then s:=ml_private.p3h_gear_forget(s,guard);s:=jsonb_set(s,array['stage3','equipment',coalesce(ml_private.p3h_gear_owner(s,guard),a)::text],(s#>array['stage3','equipment',coalesce(ml_private.p3h_gear_owner(s,guard),a)::text])-guard);s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-guard);s:=jsonb_set(s,'{stage4,copies}',(s#>'{stage4,copies}')-guard);s:=jsonb_set(s,'{stage4,durability}',(s#>'{stage4,durability}')-guard);s:=ml_private.exercise_discard(s,jsonb_build_array(guard));s:=ml_private.emit(s,'break','S'||(a+1)||' 无一骑损坏');end if;return s||jsonb_build_object('_hit',null);
 end if;
 if guard is not null and c->>'definition'='basic-006' then return s||jsonb_build_object('_hit',null);end if;return ml_private.p3g_cube_boost(s,h);
end $$;
create or replace function ml_private.stage4_combat_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer:=(t->>'target')::int;c jsonb;cells jsonb;targets jsonb;boosted boolean;roll integer:=0;hit boolean;jobs jsonb:='[]';begin
 if action in ('gear-reflect','gear-chalk','gear-plant') then
  if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or not(ml_private.p3h_gear_cards(s,a) ? (t->>'card')) or not ml_private.stage4_gear_permitted(s,a,target,t->>'card') or action='gear-chalk' and (s#>>array['players',a::text,'ap'])::int<1 then return s||jsonb_build_object('_combatHandled',true);end if;
  if action='gear-plant' then select coalesce(jsonb_agg(v->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(v,ord) where v->>'region' in ('云上学府','高唐农场') and ml_private.stage4_board_empty(s,target,v->>'id',jsonb_build_array(target));end if;
  if action<>'gear-plant' or jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,action,a,at,jsonb_build_object('source',target,'data',jsonb_build_object('card',t->'card'))||case when cells is not null then jsonb_build_object('cells',cells) else '{}'::jsonb end);end if;return s||jsonb_build_object('_combatHandled',true);
 elsif action='gear-cloak' then
  c:=s#>'{cardStack,stack,-1}';if c->'cancelled' @> jsonb_build_array(target) or not ml_private.stage4_on_board(s,target) or (case when t ? 'card' then not(ml_private.p3g_combat_gears(s,target,'basic-049') ? (t->>'card')) else ml_private.stage4_combat_gear(s,target,'basic-049') is null end) then return s||jsonb_build_object('_combatHandled',true);end if;
  s:=ml_private.select_choice(s,'gear-cloak',target,at,jsonb_build_object('source',c->'actor','data',jsonb_build_object('serial',c->'serial')||case when t ? 'card' then jsonb_build_object('card',t->'card') else '{}'::jsonb end));return s||jsonb_build_object('_combatHandled',true);
 elsif action='ball-hit' then
  c:=s#>'{cardStack,stack,-1}';if not(c->'cancelled' @> jsonb_build_array(target)) and ml_private.stage4_on_board(s,target) and ml_private.stage3_card_allowed(s,target,c->>'definition',c->'effect') then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',t#>'{data,amount}','source',c->'actor','category','attack')));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;return s||jsonb_build_object('_combatHandled',true);
 end if;
 if action<>'effect' or s#>>'{cardStack,stack,-1,definition}'<>'basic-009' then return s||jsonb_build_object('_combatHandled',false);end if;
 c:=s#>'{cardStack,stack,-1}';a:=(c->>'actor')::int;s:=ml_private.stage3_record_combo(s,a,c->>'definition');targets:=ml_private.stage4_map_targets(s,c);boosted:=ml_private.stage4_combat_gear(s,a,'basic-056') is not null;
 if jsonb_array_length(targets)>0 and coalesce(c#>>'{stage4,dodge}','false')<>'true' and not(ml_private.p3d_enabled(s) and s#>>array['players',a::text,'character']='character-029') then s:=ml_private.p3g_owned_die(s,'躲避球',(c->>'actor')::int);roll:=(s->>'_roll')::int;s:=s-'_roll';end if;
 hit:=coalesce(c#>>'{stage4,dodge}','false')='true' or ml_private.p3d_enabled(s) and s#>>array['players',a::text,'character']='character-029' or jsonb_array_length(targets)>0 and (case when boosted then roll<=5 else roll>=4 end);
 if hit then for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v where targets @> jsonb_build_array(v) loop
  if not boosted then if ml_private.p3g_enabled(s) then for cells in select * from ml_private.arr(ml_private.p3g_combat_gears(s,target,'basic-049')) loop jobs:=jobs||jsonb_build_array(ml_private.stage3_task('gear-cloak',jsonb_build_object('target',target,'serial',c->'serial','card',cells)));end loop;elsif ml_private.stage4_combat_gear(s,target,'basic-049') is not null then jobs:=jobs||jsonb_build_array(ml_private.stage3_task('gear-cloak',jsonb_build_object('target',target,'serial',c->'serial')));end if;end if;jobs:=jobs||jsonb_build_array(ml_private.stage3_task('ball-hit',jsonb_build_object('target',target,'serial',c->'serial','data',jsonb_build_object('amount',case when c#>>'{stage4,dodge}'='true' then 2 else 1 end))));
 end loop;end if;s:=ml_private.stage3_prepend(s,jobs||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_combatHandled',true);
end $$;
create or replace function ml_private.stage4_combat_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;target integer:=(c->>'source')::int;card text:=c#>>'{data,card}';pending jsonb;idx text;remaining integer;g jsonb;begin
 if timeout or not ml_private.stage4_on_board(s,a) then return s;end if;
 if c->>'kind'='gear-cloak' then
  if cmd->>'accept'='true' and (case when card is not null then ml_private.p3g_combat_gears(s,a,'basic-049') ? card else ml_private.stage4_combat_gear(s,a,'basic-049') is not null end) then s:=ml_private.p3g_owned_die(s,'帝汶斗篷',a);if (s->>'_roll')::int%2=1 then idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'cancelled'],(s#>array['cardStack','stack',idx,'cancelled'])||jsonb_build_array(a));if s->'attack'<>'null'::jsonb and not(s#>'{attack,cancelled}' @> jsonb_build_array(a)) then s:=jsonb_set(s,'{attack,cancelled}',(s#>'{attack,cancelled}')||jsonb_build_array(a));end if;s:=ml_private.emit(s,'block','S'||(a+1)||' 帝汶斗篷取消躲避球全部效果');end if;s:=s-'_roll';end if;return s;
 end if;
 if not(ml_private.p3h_gear_cards(s,a) ? card) or not ml_private.stage4_on_board(s,target) or not ml_private.stage4_gear_permitted(s,a,target,card) then return s;end if;
 if c->>'kind'='gear-plant' then
  if cmd->>'cell' is not null then perform ml_private.need(c->'cells' ? (cmd->>'cell') and ml_private.stage4_board_empty(s,target,cmd->>'cell',jsonb_build_array(target)),'植物落点不合法');s:=ml_private.stage3_relocate(s,target,cmd->>'cell',false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;
 end if;
 if coalesce(cmd->>'accept','false')<>'true' then return s;end if;
 if c->>'kind'='gear-reflect' then
  remaining:=coalesce((s#>>array['stage4','durability',card])::int,3)-1;s:=jsonb_set(s,array['stage4','durability',card],to_jsonb(remaining));
  if remaining=0 then s:=ml_private.p3h_gear_forget(s,card);s:=jsonb_set(s,array['stage3','equipment',coalesce(ml_private.p3h_gear_owner(s,card),a)::text],(s#>array['stage3','equipment',coalesce(ml_private.p3h_gear_owner(s,card),a)::text])-card);s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-card);s:=jsonb_set(s,'{stage4,copies}',(s#>'{stage4,copies}')-card);s:=jsonb_set(s,'{stage4,durability}',(s#>'{stage4,durability}')-card);s:=ml_private.exercise_discard(s,jsonb_build_array(card));s:=ml_private.emit(s,'break','S'||(a+1)||' 正装损坏');end if;
  s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response','reflected',true)||case when s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_object('originCard',card) else '{}'::jsonb end));
 else perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=1,'粉笔需要1AP');s:=ml_private.p3d_pay(s,a,1);s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response','extra',true)||case when s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_object('originCard',card) else '{}'::jsonb end));end if;
 s:=ml_private.stage3_prepend(s,s->'_triggers');return s-'_triggers';
end $$;
create or replace function ml_private.stage4_validate_equipment(s jsonb,cmd jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;card text:=cmd->>'card';definition text:=split_part(card,'#',1);options jsonb:=ml_private.stage3_equipment_options(s,a,card);owner integer;begin
 if ml_private.p3h_prime_active(s,a) then perform ml_private.need(options->>'allowed'='true' and jsonb_array_length(coalesce(cmd->'replacements',case when cmd ? 'replacement' then jsonb_build_array(cmd->'replacement') else '[]'::jsonb end)) between jsonb_array_length(options->'cards') and 2 and (select count(distinct v) from ml_private.arr(coalesce(cmd->'replacements',case when cmd ? 'replacement' then jsonb_build_array(cmd->'replacement') else '[]'::jsonb end)) v)=jsonb_array_length(coalesce(cmd->'replacements',case when cmd ? 'replacement' then jsonb_build_array(cmd->'replacement') else '[]'::jsonb end)) and options->'cards' @> coalesce(cmd->'replacements',case when cmd ? 'replacement' then jsonb_build_array(cmd->'replacement') else '[]'::jsonb end),'请先选择双装备所需的合法替换对象');else perform ml_private.need(not(cmd ? 'replacements') and options->>'allowed'='true' and (options->>'required'<>'true' or cmd ? 'replacement') and (not(cmd ? 'replacement') or options->'cards' ? (cmd->>'replacement')),'请先选择合法装备替换对象');end if;
 perform ml_private.need(definition='basic-073' or not(cmd ? 'copy'),'只有Bob能复制坐骑');
 if definition='basic-073' then
  select (q->>'seat')::int into owner from ml_private.arr(s->'players') q where (q->>'seat')::int<>a and ml_private.stage4_on_board(s,(q->>'seat')::int) and s#>array['stage3','equipment',q->>'seat'] ? (cmd->>'copy') limit 1;
  perform ml_private.need(owner is not null and split_part(cmd->>'copy','#',1)<>'basic-073' and ml_private.rule_card(s,cmd->>'copy')->>'slot'='mount','Bob须指定他人已装备的非Bob坐骑');definition:=split_part(cmd->>'copy','#',1);
 end if;
 perform ml_private.need(definition not in ('basic-063','basic-064') or not ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a),'水中不能装备禁水坐骑');
end $$;
create or replace function ml_private.stage4_gear_detach(s jsonb,a integer,g jsonb,discard boolean) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare card text:=g->>'card';begin
 s:=ml_private.p3h_gear_forget(s,card);if g->>'definition'='basic-069' then s:=jsonb_set(s,array['stage4','terrainIgnore',a::text],'false');end if;
 s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])-card);
 s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-card);s:=jsonb_set(s,'{stage4,watches}',(s#>'{stage4,watches}')-card);s:=jsonb_set(s,'{stage4,copies}',(s#>'{stage4,copies}')-card);s:=jsonb_set(s,'{stage4,durability}',(s#>'{stage4,durability}')-card);
 if ml_private.p3g_enabled(s) then s:=(s#-array['stage3','g','gearBreadReadyAt',card])#-array['stage3','g','gearTerrain',card];s:=ml_private.p3g_terrain_refresh(s,a);end if;if discard then s:=ml_private.exercise_discard(s,jsonb_build_array(card));else s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));end if;return ml_private.p3h_gear_refresh(ml_private.stage4_gear_movement(s,a));
end $$;
create or replace function ml_private.stage4_gear_install(s jsonb,a integer,g jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare card text:=g->>'card';durability integer:=(g->>'durability')::int;begin
 s:=ml_private.p3h_gear_forget(s,card);s:=jsonb_set(s,'{resolving}',(s->'resolving')-card);s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])||jsonb_build_array(card));
 s:=jsonb_set(s,array['stage3','equipmentSources',card],(g->'effect')||jsonb_build_object('actor',a,'faction',s#>array['players',a::text,'faction'],'origin','equipment'));
 if split_part(card,'#',1)<>g->>'definition' then s:=jsonb_set(s,array['stage4','copies',card],g->'definition');end if;
 durability:=coalesce(durability,case when g->>'definition'='basic-051' then 3 when g->>'definition'='basic-070' then 2 else null end);
 if g->>'definition'='basic-069' then s:=jsonb_set(s,array['stage4','terrainIgnore',a::text],'false');end if;
 if g->>'definition'='basic-060' then s:=jsonb_set(s,array['stage4','watches',card],jsonb_build_object('current',null,'previous',null,'usedTurn',null));end if;
 s:=ml_private.p3g_bread_install(s,a,g);if ml_private.p3g_enabled(s) and g->>'definition'='basic-069' then s:=jsonb_set(s,array['stage3','g','gearTerrain',card],'false');s:=ml_private.p3g_terrain_refresh(s,a);end if;if durability is not null then s:=jsonb_set(s,array['stage4','durability',card],to_jsonb(durability));end if;s:=ml_private.stage4_gear_movement(s,a);
 s:=ml_private.p3h_gear_refresh(s);s:=ml_private.p3h_gear_install_draw(s,a);return ml_private.emit(s,'equip','S'||(a+1)||' 装备'||(ml_private.rule_card(s,card)->>'name'));
end $$;
create or replace function ml_private.stage4_equipment_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$
declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);c jsonb;g jsonb;old jsonb;effect jsonb;definition text;cells jsonb;targets jsonb;target integer;options jsonb;tasks jsonb:='[]';data jsonb;card text;idx text;i integer;hand jsonb;index integer;here jsonb;there jsonb;q jsonb;hits jsonb:='[]';begin s:=ml_private.p3g_equipment_task(s,t,at);if s->>'_gEquipmentHandled'='true' then return (s-'_gEquipmentHandled')||jsonb_build_object('_gearHandled',true);end if;s:=s-'_gEquipmentHandled';
 if action='gear-end' then
  if not ml_private.stage4_on_board(s,a) then return s||jsonb_build_object('_gearHandled',true);end if;here:=ml_private.game_data(s,'map')->(s#>>array['players',a::text,'cell']);
  for card in select v#>>'{}' from ml_private.arr(ml_private.p3h_gear_cards(s,a)) v loop
   definition:=ml_private.stage4_equipment_definition(s,card);effect:=ml_private.p3h_gear_source(s,a,card)||jsonb_build_object('origin','equipment');
   if definition not in ('basic-050','basic-064') or definition='basic-050' and here->>'region'='教学楼' then continue;end if;
   for q in select * from ml_private.arr(s->'players') loop target:=(q->>'seat')::int;there:=ml_private.game_data(s,'map')->(q->>'cell');
    if target=a or not ml_private.stage4_on_board(s,target) or s->>'mode'='team' and q->'team'=s#>array['players',a::text,'team'] or not ml_private.stage3_card_allowed(s,target,definition,effect) then continue;end if;
    if (case when definition='basic-050' then here->'region'=there->'region' else (here->'row'=there->'row' or here->'col'=there->'col') and not ml_private.stage3_equipped(s,target,'basic-063') end) then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response'));end if;
   end loop;
  end loop;s:=ml_private.damage(s,hits);s:=ml_private.stage3_prepend(s,s->'_triggers');return (s-'_triggers')||jsonb_build_object('_gearHandled',true);
 elsif action='gear-loss' then
  g:=t->'data';definition:=g->>'definition';effect:=(g->'effect')||jsonb_build_object('origin','equipment');
  if not ml_private.stage4_on_board(s,a) or not ml_private.stage3_card_allowed(s,a,g->>'card',effect) then return s||jsonb_build_object('_gearHandled',true);end if;
  if definition='basic-063' then select coalesce(jsonb_agg(v->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(v,ord) where v->>'region'='山洞' and ml_private.stage4_board_empty(s,a,v->>'id',jsonb_build_array(a));end if;
  if definition='basic-052' then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(v,ord) where (v->>'seat')::int<>a and ml_private.stage4_on_board(s,(v->>'seat')::int) and ml_private.stage3_card_allowed(s,(v->>'seat')::int,g->>'card',effect);end if;
  if definition in ('basic-054','basic-059') or jsonb_array_length(cells)>0 or jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'gear-loss',a,at,jsonb_build_object('data',g)||case when cells is not null then jsonb_build_object('cells',cells) else '{}'::jsonb end||case when targets is not null then jsonb_build_object('targets',targets) else '{}'::jsonb end);end if;
  return s||jsonb_build_object('_gearHandled',true);
 elsif action='gear-transfer-install' then
  data:=t->'data';g:=data->'gear';
  if data ? 'replacement' and coalesce(data->>'replaced','false')<>'true' then options:=ml_private.stage3_equipment_options(s,a,g->>'card');
   if ml_private.stage4_on_board(s,a) and options->>'allowed'='true' and options->'cards' ? (data->>'replacement') then
    old:=ml_private.stage4_gear_snapshot(s,a,data->>'replacement');s:=ml_private.stage4_gear_detach(s,a,old,true);
    s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',a,'data',old)),ml_private.stage3_task('gear-transfer-install',jsonb_build_object('actor',a,'data',data||jsonb_build_object('replaced',true)))));return s||jsonb_build_object('_gearHandled',true);
   end if;
  end if;
  if ml_private.stage4_can_install(s,a,g) then s:=ml_private.stage4_gear_install(s,a,g);
  else s:=jsonb_set(s,'{resolving}',(s->'resolving')-(g->>'card'));if ml_private.stage3_alive(s,a) then s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(g->'card'));else s:=ml_private.exercise_discard(s,jsonb_build_array(g->'card'));end if;s:=ml_private.emit(s,'transfer','S'||(a+1)||' 装配条件失效，装备转入'||case when ml_private.stage3_alive(s,a) then '手牌' else '弃牌堆' end);end if;
  return s||jsonb_build_object('_gearHandled',true);
 end if;
 if action='equip-install' then
  c:=s#>'{cardStack,stack,-1}';a:=(c->>'actor')::int;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;
  if ml_private.stage4_on_board(s,a) then
   g:=jsonb_build_object('card',c->'card','definition',coalesce(c#>>'{stage4,copy}',split_part(c->>'card','#',1)),'effect',c->'effect');
   if ml_private.stage4_can_install(s,a,g) then s:=ml_private.stage4_gear_install(s,a,g);else s:=jsonb_set(s,'{resolving}',(s->'resolving')-(g->>'card'));s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(g->'card'));end if;s:=jsonb_set(s,array['cardStack','stack',idx,'installed'],'true');
  end if;return s||jsonb_build_object('_gearHandled',true);
 end if;
 if action<>'effect' then return s||jsonb_build_object('_gearHandled',false);end if;
 c:=s#>'{cardStack,stack,-1}';a:=(c->>'actor')::int;definition:=c->>'definition';
 if definition='basic-024' then
  s:=ml_private.stage3_record_combo(s,a,definition);select (v#>>'{}')::int into target from ml_private.arr(ml_private.stage4_map_targets(s,c)) v limit 1;
  if target is not null then
   if c#>>'{stage4,take}'='hand' then
    for i in 1..2 loop hand:=s#>array['players',target::text,'hand'];exit when jsonb_array_length(hand)=0;s:=ml_private.int(s,jsonb_array_length(hand));index:=(s->>'_int')::int;s:=s-'_int';card:=hand->>index;s:=jsonb_set(s,array['players',target::text,'hand'],hand-index);s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(card));end loop;s:=ml_private.emit(s,'transfer','S'||(a+1)||' 转学手册随机拿取手牌');
   elsif s#>array['stage3','equipment',target::text] ? (c#>>'{stage4,item}') then
    g:=ml_private.stage4_gear_snapshot(s,target,c#>>'{stage4,item}');s:=ml_private.stage4_gear_detach(s,target,g,false);tasks:=jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',target,'data',g)),ml_private.stage3_task('gear-transfer-install',jsonb_build_object('actor',a,'data',jsonb_build_object('gear',g)||case when c ? 'replacement' then jsonb_build_object('replacement',c->'replacement') else '{}'::jsonb end)));s:=ml_private.emit(s,'transfer','S'||(a+1)||' 转学手册拿取公开装备');
   end if;
  end if;s:=ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_gearHandled',true);
 end if;
 if ml_private.rule_card(s,c->>'card')->>'type'<>'equipment' or coalesce(c->>'converted','false')='true' then return s||jsonb_build_object('_gearHandled',false);end if;
 s:=ml_private.stage3_record_combo(s,a,definition);
 if ml_private.stage4_on_board(s,a) and ml_private.stage3_card_allowed(s,a,definition,c->'effect') then
  if c ? 'replacement' and s#>array['stage3','equipment',a::text] ? (c->>'replacement') then g:=ml_private.stage4_gear_snapshot(s,a,c->>'replacement');s:=ml_private.stage4_gear_detach(s,a,g,true);tasks:=tasks||jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',a,'data',g)));end if;tasks:=tasks||jsonb_build_array(ml_private.stage3_task('equip-install',jsonb_build_object('serial',c->'serial')));
 end if;s:=ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_gearHandled',true);
end $$;
create or replace function ml_private.stage4_map_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s#>'{cardStack,stack,-1}';action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer;definition text:=c->>'definition';targets jsonb;tasks jsonb:='[]';cards jsonb;cells jsonb;paths jsonb;options jsonb;desert jsonb;region text;cell text;roll integer;max_distance integer;e_gate jsonb;effect jsonb;idx text;begin
 if action='board-shore' then select coalesce(jsonb_agg(v order by ord),'[]') into cells from jsonb_array_elements(t#>'{data,cells}') with ordinality q(v,ord) where ml_private.stage4_board_empty(s,a,v#>>'{}',jsonb_build_array(a));perform ml_private.need(jsonb_array_length(cells)>0,'上岸预留格失效');return ml_private.select_choice(s,'native-shore',a,at,jsonb_build_object('cells',cells))||jsonb_build_object('_boardHandled',true);end if;
 if action='board-desert' then desert:=ml_private.stage4_desert(s,a);if desert is not null then
  if jsonb_array_length(s#>array['players',a::text,'hand'])>0 or (s#>>array['players',a::text,'ap'])::int>0 then s:=ml_private.select_choice(s,'board-tax',a,at,jsonb_build_object('cards',s#>array['players',a::text,'hand'],'source',desert->'owner','data',jsonb_build_object('mode','desert')));
  else s:=ml_private.stage4_pay(s,a,(desert->>'owner')::int,'desert',null,false);end if;end if;return s||jsonb_build_object('_boardHandled',true);
 elsif action='board-pay' then if ml_private.stage4_on_board(s,a) then
  if jsonb_array_length(s#>array['players',a::text,'hand'])>0 then s:=ml_private.select_choice(s,'board-tax',a,at,jsonb_build_object('cards',s#>array['players',a::text,'hand'],'source',t->'source','data',jsonb_build_object('mode',t#>'{data,mode}')));
  else s:=ml_private.stage4_pay(s,a,(t->>'source')::int,t#>>'{data,mode}',null,false);end if;end if;return s||jsonb_build_object('_boardHandled',true);
 end if;
 if action like 'board-%' then
  if c is null or t ? 'serial' and t->'serial'<>c->'serial' then return s||jsonb_build_object('_boardHandled',true);end if;
  if action='board-force' then
   paths:=ml_private.stage4_forced_paths(s,a,t#>>'{data,region}',(t#>>'{data,steps}')::int);
   if ml_private.p3e_enabled(s) and exists(select 1 from ml_private.arr(paths) path where jsonb_array_length(path)>0) then e_gate:=ml_private.p3e_gate(s,a,(c->>'actor')::int,jsonb_build_array(t),ml_private.p3e_root(s));if e_gate is not null then return ml_private.stage3_prepend(s,e_gate)||jsonb_build_object('_boardHandled',true);end if;end if;if jsonb_array_length(paths)>1 then select jsonb_object_agg((ord-1)::text,v) into options from jsonb_array_elements(paths) with ordinality q(v,ord);s:=ml_private.select_choice(s,'board-path',a,at,jsonb_build_object('options',options,'data',jsonb_build_object('serial',c->'serial')));
   elsif jsonb_array_length(coalesce(paths->0,'[]'))>0 then s:=ml_private.stage4_queue_path(s,a,paths->0,(c->>'serial')::int);end if;
  elsif action='board-step' then
   cell:=t#>>'{data,cell}';
   if not ml_private.stage4_on_board(s,a) or ml_private.distance_for_version(s->>'version',s#>>array['players',a::text,'cell'],cell)<>1 or not ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) then
    s:=jsonb_set(s,'{queue}',(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s->'queue') with ordinality q(v,ord) where not(coalesce(v->>'action','')='board-step' and (v->>'actor')::int=a and v->'serial'=c->'serial')));
   else s:=ml_private.stage3_relocate(s,a,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';
    if ml_private.game_data(s,'map')#>>array[cell,'region']='山洞' then s:=jsonb_set(s,'{queue}',(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s->'queue') with ordinality q(v,ord) where not(coalesce(v->>'action','')='board-step' and (v->>'actor')::int=a and v->'serial'=c->'serial')));end if;
   end if;
  elsif action='board-force-carry' then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',a,'data',t->'data'))));
  elsif action='board-force-after' then
   targets:=ml_private.stage4_map_targets(s,c);
   if definition='basic-013' then
    select max(ml_private.stage4_region_distance(s,(v#>>'{}')::int,'操场')) into max_distance from ml_private.arr(targets) v where v<>c->'actor';
    select coalesce(jsonb_agg(jsonb_build_object('target',v,'amount',1,'source',c->'actor','category','attack','directHp',true)),'[]') into tasks from ml_private.arr(targets) v where v<>c->'actor' and ml_private.stage4_region_distance(s,(v#>>'{}')::int,'操场')=max_distance;
    s:=ml_private.damage(s,tasks);s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';
   else
    select coalesce(jsonb_agg(ml_private.stage3_task('board-pay',jsonb_build_object('actor',v,'source',c->'actor','data',jsonb_build_object('mode','tribute'))) order by ord),'[]') into tasks
    from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v) and v<>c->'actor' and s#>array['players',v#>>'{}','team']<>s#>array['players',c->>'actor','team'] and ml_private.game_data(s,'map')#>>array[s#>>array['players',v#>>'{}','cell'],'region']='教学楼';s:=ml_private.stage3_prepend(s,tasks);
   end if;
  elsif action='board-teleport' then
   target:=(t->>'target')::int;if ml_private.stage4_on_board(s,target) and ml_private.stage4_on_board(s,(c->>'actor')::int) then
    select coalesce(jsonb_agg(candidate->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(candidate,ord) where ml_private.stage4_board_empty(s,target,candidate->>'id',jsonb_build_array(target));
    if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'board-cell',(c->>'actor')::int,at,jsonb_build_object('cells',cells,'source',target,'data',jsonb_build_object('serial',c->'serial')));elsif s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.emit(s,'effect','卫汶找你：没有合法传送落点，位置不变');end if;end if;
  else raise exception '未知阶段四地图任务';end if;return s||jsonb_build_object('_boardHandled',true);
 end if;
 if action<>'effect' or definition not in ('basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034') then return s||jsonb_build_object('_boardHandled',false);end if;
 a:=(c->>'actor')::int;targets:=ml_private.stage4_map_targets(s,c);s:=ml_private.stage3_record_combo(s,a,definition);
 if definition='basic-020' then for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop s:=jsonb_set(s,array['stage4','toiletUntil',target::text],to_jsonb((s#>>array['stage3','starts',target::text])::int+1));s:=jsonb_set(s,array['stage4','toiletEffects',target::text],c->'effect');end loop;end if;
 if definition='basic-026' then
  s:=jsonb_set(s,array['stage4','lmmUntil',a::text],to_jsonb((s#>>array['stage3','starts',a::text])::int+1));s:=jsonb_set(s,array['stage4','lmmEffects',a::text],c->'effect');s:=jsonb_set(s,array['stage4','lmmSerial',a::text],c->'serial');
  select coalesce(jsonb_agg(ml_private.stage3_task('board-pay',jsonb_build_object('actor',v,'source',a,'data',jsonb_build_object('mode','lmm'))) order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v);
 end if;
 if definition='basic-034' then for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop
  if ml_private.p3e_enabled(s) then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('e-off-map',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('root',ml_private.p3e_root(s)))));continue;end if;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');s:=ml_private.emit(s,'off-map','S'||(target+1)||' 移出地图，等待下个个人开始返回');end loop;end if;
 if definition='basic-023' then
  select coalesce(jsonb_agg(v order by ord),'[]') into cards from jsonb_array_elements(s#>'{stage4,blocks}') with ordinality q(v,ord) where not((v->>'owner')::int=a and v->'region'=c#>'{stage4,region}');
  cards:=cards||jsonb_build_array(jsonb_build_object('region',c#>'{stage4,region}','owner',a,'effect',c->'effect','until',(s#>>array['stage3','starts',a::text])::int+1,'exempt',coalesce(c#>'{stage4,officeExempt}','[]')));s:=jsonb_set(s,'{stage4,blocks}',cards);
 end if;
 if definition='basic-032' then s:=jsonb_set(s,array['stage4','deserts',c#>>'{stage4,region}'],jsonb_build_object('owner',a,'effect',c->'effect'));end if;
 if definition='basic-033' then
  if s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.playtest_flood(s,c#>>'{stage4,region}',a,c->'effect');if s->>'_floodFailed'='true' then s:=s-'_floodFailed';return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))))||jsonb_build_object('_boardHandled',true);end if;tasks:=tasks||(s->'_shoreTasks');s:=s-'_shoreTasks';else s:=jsonb_set(s,array['stage4','water',c#>>'{stage4,region}'],jsonb_build_object('owner',a,'effect',c->'effect'));end if;
  for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop
   if ml_private.stage4_on_board(s,target) and ml_private.game_data(s,'map')#>>array[s#>>array['players',target::text,'cell'],'region']=c#>>'{stage4,region}' and ml_private.stage4_board_effect(s,target,c->'effect') and not ml_private.classic_native(s,target) and jsonb_array_length(s#>array['players',target::text,'hand'])>0 then tasks:=tasks||jsonb_build_array(jsonb_build_object('kind','water','actor',target,'data',jsonb_build_object('entry',true)));end if;
  end loop;
 end if;
 if definition in ('basic-013','basic-031') then
  region:=case when definition='basic-013' then '操场' else '教学楼' end;
  select coalesce(jsonb_agg(ml_private.stage3_task('board-force',jsonb_build_object('actor',v,'serial',c->'serial','data',jsonb_build_object('region',region,'steps',case when definition='basic-013' then 1 else 3 end))) order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v);
  tasks:=tasks||jsonb_build_array(ml_private.stage3_task('board-force-after',jsonb_build_object('serial',c->'serial')));
 end if;
 if definition='basic-021' and jsonb_array_length(targets)>0 then
  if jsonb_array_length(s#>'{random,dice}')>0 then roll:=(s#>>'{random,dice,0}')::int;s:=jsonb_set(s,'{random,dice}',(s#>'{random,dice}')-0);else s:=ml_private.int(s,6);roll:=(s->>'_int')::int+1;s:=s-'_int';end if;
  idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4','guessDie'],to_jsonb(roll));s:=ml_private.select_choice(s,'board-guess',(targets->>0)::int,at,jsonb_build_object('source',a,'data',jsonb_build_object('serial',c->'serial')));
 end if;
 s:=ml_private.emit(s,'effect',definition||'地图效果结算');s:=ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_boardHandled',true);
end $$;
create or replace function ml_private.stage4_map_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare choice jsonb:=s->'choice';a integer:=(choice->>'actor')::int;kind text:=choice->>'kind';option text:=cmd->>'option';mode text:=choice#>>'{data,mode}';card text:=cmd->>'card';ap boolean;pending jsonb;roll integer;cell text:=cmd->>'cell';cells jsonb;origin text;jobs jsonb;begin
 if kind='native-shore' then if timeout then cell:=choice#>>'{cells,0}';end if;perform ml_private.need(cell is not null and choice->'cells' ? cell and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)),'请选择合法岸边');s:=s||jsonb_build_object('_gearReactiveSkip',true);s:=ml_private.stage3_relocate(s,a,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');return s-'_relocationTasks'-'_gearReactiveSkip';end if;
 if kind='board-path' then
  if option is null and timeout then select key into option from jsonb_each(choice->'options') order by key::int limit 1;end if;perform ml_private.need(option is not null and choice->'options' ? option,'请选择一条合法路径');return ml_private.stage4_queue_path(s,a,choice->'options'->option,(choice#>>'{data,serial}')::int);
 elsif kind='board-tax' then
  ap:=mode='desert' and (cmd->>'action'='ap' or timeout and (s#>>array['players',a::text,'ap'])::int>0);ap:=coalesce(ap,false);
  if card is null and timeout then select v#>>'{}' into card from ml_private.arr(s#>array['players',a::text,'hand']) v order by v#>>'{}' limit 1;end if;
  if mode='desert' then perform ml_private.need(case when ap then (s#>>array['players',a::text,'ap'])::int>0 else card is not null and choice->'cards' ? card end,'请选择1AP或一张手牌');else perform ml_private.need(card is not null and choice->'cards' ? card,'请选择一张上交牌');end if;
  return ml_private.stage4_pay(s,a,(choice->>'source')::int,mode,card,ap);
 elsif kind='board-guess' then
  pending:=s#>'{cardStack,stack,-1}';roll:=(pending#>>'{stage4,guessDie}')::int;perform ml_private.need(timeout or jsonb_typeof(cmd->'guess')='number' and (cmd->>'guess')::numeric=trunc((cmd->>'guess')::numeric) and (cmd->>'guess')::int between 1 and 6,'请选择1—6');
  s:=ml_private.emit(s,'dice','卫汶找你：d6 = '||roll,to_jsonb(roll));if ml_private.p3g_enabled(s) then s:=ml_private.p3g_after_die(s,'卫汶找你',(pending->>'actor')::int,roll);roll:=(s->>'_roll')::int;s:=s-'_roll';end if;if s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.emit(s,'effect',case when timeout or (cmd->>'guess')::int<>roll then '卫汶找你：S'||(a+1)||case when timeout then '猜点超时' else '猜错' end||'，由S'||((pending->>'actor')::int+1)||'选择传送落点' else '卫汶找你：S'||(a+1)||'猜中，位置不变' end);end if;if timeout or (cmd->>'guess')::int<>roll then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('board-teleport',jsonb_build_object('target',a,'serial',pending->'serial'))));end if;return s-'_fPlacement';
 elsif kind='board-cell' then
  if cell is not null then perform ml_private.need(choice->'cells' ? cell and ml_private.stage4_board_empty(s,(choice->>'source')::int,cell,jsonb_build_array(choice->'source')),'传送落点不合法');s:=ml_private.stage3_relocate(s,(choice->>'source')::int,cell,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';elsif s->>'version' in ('web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.emit(s,'effect','卫汶找你：S'||(a+1)||case when timeout then '选择超时' else '放弃传送' end||'，位置不变');end if;return s-'_fPlacement';
 elsif kind='board-return' then if ml_private.p3f_enabled(s) then s:=s||jsonb_build_object('_fPlacement',true);end if;
  select coalesce(jsonb_agg(v order by ord),'[]') into cells from jsonb_array_elements(choice->'cells') with ordinality q(v,ord) where ml_private.stage4_board_empty(s,a,v#>>'{}',jsonb_build_array(a));perform ml_private.need(jsonb_array_length(cells)>0,'当前无合法返回格');
  if timeout then s:=ml_private.int(s,jsonb_array_length(cells));cell:=cells->>(s->>'_int')::int;s:=s-'_int';end if;perform ml_private.need(cell is not null and cells ? cell,'请选择合法返回格');
  s:=jsonb_set(s,array['stage4','offMap',a::text],'false');origin:=s#>>array['players',a::text,'cell'];if ml_private.p3e_enabled(s) then s:=ml_private.p3e_relocate(s,a,cell,false,true,true,a,ml_private.p3e_root(s));else s:=ml_private.stage3_relocate(s,a,cell,false);end if;jobs:=s->'_relocationTasks';s:=s-'_relocationTasks';
  if origin=cell and ml_private.stage4_board_water(s,cell,a) and not ml_private.classic_native(s,a) and jsonb_array_length(s#>array['players',a::text,'hand'])>0 then jobs:=jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true)))||jobs;end if;
  if origin=cell and ml_private.stage4_desert(s,a) is not null then jobs:=jobs||jsonb_build_array(ml_private.stage3_task('board-desert',jsonb_build_object('actor',a)));end if;
  s:=ml_private.stage3_prepend(s,jobs);return ml_private.emit(s,'return','S'||(a+1)||' 返回地图'||cell);
 end if;raise exception '未知阶段四地图选择';
end $$;
create or replace function ml_private.stage4_public_state(s jsonb) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select ml_private.p3h_gear_public(s)||jsonb_build_object(
 'copies',s#>'{stage4,copies}','durability',s#>'{stage4,durability}','offMap',s#>'{stage4,offMap}','terrainIgnore',s#>'{stage4,terrainIgnore}',
 'water',coalesce((select jsonb_object_agg(key,value->'owner') from jsonb_each(s#>'{stage4,water}')),'{}'),
 'deserts',coalesce((select jsonb_object_agg(key,value->'owner') from jsonb_each(s#>'{stage4,deserts}')),'{}'),
 'blocks',(select coalesce(jsonb_agg(jsonb_build_object('region',v->'region','owner',v->'owner','until',v->'until') order by ord),'[]') from jsonb_array_elements(s#>'{stage4,blocks}') with ordinality q(v,ord)),
 'toilet',(select jsonb_agg(v<>'null'::jsonb order by ord) from jsonb_array_elements(s#>'{stage4,toiletUntil}') with ordinality q(v,ord)),
 'lmm',(select jsonb_agg(v<>'null'::jsonb order by ord) from jsonb_array_elements(s#>'{stage4,lmmUntil}') with ordinality q(v,ord)),
 'tongBlocked',(select jsonb_agg(s#>array['stage4','tongBlocked',v->>'seat'] is not null order by ord) from jsonb_array_elements(s->'players') with ordinality q(v,ord)),
 'tea',s#>'{stage4,tea}','dodge',s#>'{stage4,dodge}','exerciseFree',s#>'{stage4,exerciseFree}','exerciseGuard',s#>'{stage4,exerciseGuard}') $$;
create or replace function ml_private.stage4_actions(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$
declare base jsonb:=ml_private.stage3_actions(s,a);p jsonb:=s->'players'->a;r jsonb:=s->'stage4';free boolean:=ml_private.stage4_on_board(s,a) and (s->>'active')::int=a and s->>'phase'='action' and s->'choice'='null'::jsonb;
 blocked boolean:=ml_private.stage3_mount_blocked(s,a);normal integer:=ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a));card text;definition text;d jsonb;info jsonb;tea boolean;exercise boolean;targeted boolean;targets jsonb;elbow boolean;pushes jsonb;target integer;cells jsonb;direction text;cell text;options jsonb;cards jsonb:='{}';copies jsonb;steal jsonb;watch text;record jsonb;watch_cell text;flight jsonb:='[]';gift jsonb:='[]';interrupt text;reserve integer;can_interrupt boolean;begin
 for card in select v#>>'{}' from ml_private.arr(p->'hand') v loop
  definition:=split_part(card,'#',1);d:=ml_private.stage4_content()#>array['cards',definition];info:=base#>array['cards',card];tea:=definition='basic-002' and r#>>array['tea',a::text]='true';exercise:=definition in ('basic-003','basic-004','basic-005') and r#>>array['exerciseFree',a::text]='true';
  targeted:=tea or d->>'type'='attack' or definition in ('basic-016','basic-037','basic-018','basic-019','basic-021','basic-022','basic-024','basic-029','basic-030','basic-035','basic-036') or definition='basic-002' and p->>'character'='character-023';
  targets:=case when tea then ml_private.stage4_tea_targets(s,a) when d->>'inherited'='true' then info->'targets' when targeted then ml_private.stage4_targets(s,a,card) else '[]'::jsonb end;
  elbow:=tea or definition='basic-002' and p->>'character'='character-023';pushes:='{}';
  if elbow then for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);options:='{}';foreach direction in array array['up','right','down','left'] loop cell:=ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],direction);if cell is not null and cells ? cell then options:=options||jsonb_build_object(direction,cell);end if;end loop;pushes:=pushes||jsonb_build_object(target::text,options);end loop;end if;
  cards:=cards||jsonb_build_object(card,info||jsonb_build_object('cost',case when tea or exercise then case when ml_private.p3h_prime_active(s,a) then '1'::jsonb else '0'::jsonb end when d#>>'{cost,kind}'='variable' then 'null'::jsonb else info->'cost' end,
   'needsQuote',not tea and not exercise and (info->>'needsQuote')::boolean,'costKind',d#>'{cost,kind}','printedCost',case when s->>'version' in ('web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.exercise_rank(card)>0 then to_jsonb(ml_private.rule_card(s,card)->>'cost') else d->'printedCost' end,'targeted',targeted,'targets',targets,'tea',tea,'elbow',elbow,'pushes',pushes,
   'playable',(d->>'type'<>'response' or elbow) and definition not in ('basic-027','basic-028','basic-038'),'allowed',ml_private.stage4_location_card(s,a,definition) and not(ml_private.p3g_cube_face(s,a)=1 and (d->>'type'='attack' or elbow)),'region',definition in ('basic-023','basic-032','basic-033'),'counter',definition in ('basic-027','basic-028','basic-038')));
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('owner',q->'seat','card',v) order by player_ord,gear_ord),'[]') into copies from jsonb_array_elements(s->'players') with ordinality t(q,player_ord) cross join lateral jsonb_array_elements(s#>array['stage3','equipment',q->>'seat']) with ordinality g(v,gear_ord) where (q->>'seat')::int<>a and ml_private.stage4_on_board(s,(q->>'seat')::int) and split_part(v#>>'{}','#',1)<>'basic-073' and ml_private.rule_card(s,v#>>'{}')->>'slot'='mount';
 select jsonb_object_agg(q->>'seat',coalesce((select jsonb_object_agg(v#>>'{}',ml_private.stage3_equipment_options(s,a,v#>>'{}')) from ml_private.arr(s#>array['stage3','equipment',q->>'seat']) v),'{}')) into steal from ml_private.arr(s->'players') q;
 watch:=ml_private.stage4_combat_gear(s,a,'basic-060');record:=ml_private.p3h_gear_watch(s,a,watch);
 if free and not blocked and record->>'previous' is not null and record->'usedTurn' is distinct from s#>'{stage3,turn}' and record->>'previous'<>p->>'cell' and ml_private.stage4_board_empty(s,a,record->>'previous',jsonb_build_array(a)) then watch_cell:=record->>'previous';end if;
 if free and not blocked and p->>'moved'<>'true' and ml_private.stage4_combat_gear(s,a,'basic-074') is not null and (p->>'ap')::int>=normal+1 then select coalesce(jsonb_agg(v->'id' order by ord),'[]') into flight from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(v,ord) where v->>'id'<>p->>'cell' and ml_private.stage4_board_empty(s,a,v->>'id',jsonb_build_array(a));end if;
 if free and ml_private.stage4_combat_gear(s,a,'basic-075') is not null then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into gift from jsonb_array_elements(s->'players') with ordinality q(v,ord) where (v->>'seat')::int<>a and ml_private.stage4_on_board(s,(v->>'seat')::int);end if;
 select v#>>'{}' into interrupt from ml_private.arr(p->'hand') v where split_part(v#>>'{}','#',1)='basic-017' limit 1;reserve:=case when (s->>'active')::int=a and s#>>'{movement,costDue}'='true' and jsonb_array_length(s#>'{movement,path}')>1 then 1 else 0 end;
 can_interrupt:=coalesce(interrupt is not null and ml_private.stage4_on_board(s,a) and p->>'character'<>'character-005' and ((s->>'active')::int<>a or s#>>array['stage3','breadBlocked',a::text]<>'true') and (p->>'ap')::int>=(ml_private.stage3_card_cost(s,a,interrupt)->>'cost')::int+reserve,false);
 return jsonb_build_object('cards',cards,'regions',(select jsonb_agg(key order by key) from jsonb_object_keys(ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}') key),
  'copyMounts',copies,'stealEquipment',steal,'watchCell',watch_cell,'flightCells',flight,'flightCost',normal+1,'giftTargets',gift,'canInterrupt',can_interrupt,'terrainSelectable',ml_private.stage4_on_board(s,a) and ml_private.stage4_combat_gear(s,a,'basic-069') is not null)||ml_private.p3g_equipment_actions(s,a,free,blocked);
end $$;
create or replace function ml_private.stage4_create_draft(mode text,random_state jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare s jsonb:=jsonb_build_object('random',random_state);firstn integer;pair jsonb;teams jsonb:='[]';pools jsonb:='{}';ids jsonb:=ml_private.runtime_data('web-v0.1.19','characterIds');pool jsonb;family text;a integer;begin
 s:=ml_private.int(s,4);firstn:=(s->>'_int')::int;s:=s-'_int';s:=ml_private.shuffle(s,'[0,1,2,3]');pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1);s:=s-'_shuffle';
 for a in 0..3 loop family:=case when mode='team' then case when pair @> jsonb_build_array(a) then '机械猴子' else '帝汶家族' end else 'S'||(a+1) end;teams:=teams||jsonb_build_array(family);end loop;
 for family in select distinct x#>>'{}' from ml_private.arr(teams) x loop
 select jsonb_agg(id order by ord) into pool from jsonb_array_elements(ids) with ordinality q(id,ord) where mode='ffa' or ml_private.runtime_data('web-v0.1.19','characters')#>>array[id#>>'{}','faction'] in (family,'中立');pools:=jsonb_set(pools,array[family],pool);end loop;
 return ml_private.create_draft(jsonb_build_object('mode',mode,'order',(select jsonb_agg((firstn+i)%4 order by i) from generate_series(0,3) i),'teams',teams,'pools',pools,'random',s->'random','catalogVersion','web-v0.1.19'),at);
end $$;
create or replace function ml_private.playtest_role_choice(s jsonb,kind text) returns boolean language sql immutable as $$
 select (ml_private.p3h_enabled(s) and kind in ('h-equip-draw','h-small','h-birth','h-respect','h-ren-retreat','h-ren-back','h-ren-expel','h-ren-gear','h-cooperate','h-circle-pay','h-attract','h-reroll','h-six')) or (ml_private.p3g_enabled(s) and kind in ('g-haki','g-food','g-invisible','g-program','g-math','g-counter','g-white-eye')) or s->>'version' in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and (ml_private.p3f_enabled(s) and kind like 'f-%' and kind<>'f-discard' or ml_private.p3e_enabled(s) and kind in ('move-consent','egg-move','force-step') or ml_private.p3d_enabled(s) and kind='encourage' or ml_private.p3c_enabled(s) and kind='primitive-food' or kind in ('draw-start','draw-end','lemon-reward','lemon-support','runner-roll','runner-pay','teleport','easy','qb-pursuit','east-start','xiao-overflow','xie-ledger','elbow-push','west-carry')) $$;
create or replace function ml_private.playtest_north_targets(s jsonb,targets jsonb,branch text default null,automatic boolean default false) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare north integer;result jsonb;begin
 if s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return targets;end if;
 select (v#>>'{}')::int into north from ml_private.arr(targets) v where s#>>array['players',v#>>'{}','character']='character-006';
 if north is null or not exists(select 1 from ml_private.arr(targets) v where (v#>>'{}')::int<>north and s#>>array['players',v#>>'{}','faction']<>'机械猴子') then return targets;end if;
 perform ml_private.need(automatic and branch in ('north','others'),'北帝汶与其他非机械猴子不能同时指定；请选择目标分支');
 select coalesce(jsonb_agg(v order by ord),'[]') into result from jsonb_array_elements(targets) with ordinality q(v,ord)
 where case when branch='north' then (v#>>'{}')::int=north or s#>>array['players',v#>>'{}','faction']='机械猴子' else (v#>>'{}')::int<>north end;
 return result;
end $$;
create or replace function ml_private.playtest_relocation_cell(s jsonb,a integer,origin text,destination text,ignored jsonb default '[]') returns text language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare startcell jsonb:=ml_private.game_data(s,'map')->origin;cell jsonb:=ml_private.game_data(s,'map')->destination;dr integer;dc integer;begin
 if s->>'version' not in ('web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return destination;end if;
 if startcell is null or cell is null then return null;end if;
 dr:=sign((cell->>'row')::int-(startcell->>'row')::int);dc:=sign((cell->>'col')::int-(startcell->>'col')::int);
 loop
  if not ml_private.stage4_board_entry(s,a,cell->>'id') or exists(select 1 from ml_private.arr(s->'players') p where (p->>'seat')::int<>a and not ignored @> jsonb_build_array(p->'seat') and ml_private.stage4_on_board(s,(p->>'seat')::int) and ml_private.p3h_blocks(s,a,(p->>'seat')::int) and p->'cell'=cell->'id') then return null;end if;
  if not ml_private.classic_native(s,a) or not ml_private.stage4_board_water(s,cell->>'id',a) then return cell->>'id';end if;
  if dr=0 and dc=0 then return null;end if;
  cell:=ml_private.game_data(s,'map')->('r'||((cell->>'row')::int+dr)||'c'||((cell->>'col')::int+dc));if cell is null then return null;end if;
 end loop;
end $$;
create or replace function ml_private.exercise_remember(s jsonb,a integer,card text) returns jsonb language plpgsql immutable
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' not in ('web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return s;end if;
 if not s ? 'exercise' then s:=s||jsonb_build_object('exercise',jsonb_build_object('owners','{}'::jsonb));end if;
 if ml_private.exercise_rank(card)>0 and not (s#>'{exercise,owners}') ? card then s:=jsonb_set(s,array['exercise','owners',card],to_jsonb(a));end if;
 return s;
end $$;
create or replace function ml_private.exercise_response(s jsonb,attack text,response text) returns boolean language sql immutable
set search_path=pg_catalog,ml_private as $$ select s->>'version' in ('web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.exercise_rank(attack)>0 and ml_private.exercise_rank(response)>ml_private.exercise_rank(attack) $$;
create or replace function ml_private.p3_yinghao_immune(s jsonb,target integer,card text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(s->>'version' in ('web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['players',target::text,'character']='character-045' and split_part(card,'#',1)='basic-010',false) $$;
create or replace function ml_private.p3_monkey_effect(s jsonb,a integer,card text,effect jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['players',a::text,'character']='character-013' and ml_private.game_data(s,'cardTags')->split_part(card,'#',1) ? '外星' and (ml_private.rule_card(s,card)->>'type'='attack' or split_part(card,'#',1)='basic-048') then
 return jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','damage')));end if;return effect;
end $$;
create or replace function ml_private.p3_mayi_targets(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare region text;result jsonb;begin
 if s->>'version' not in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or s#>>array['players',a::text,'character']<>'character-025' or not ml_private.stage4_on_board(s,a) then return '[]';end if;
 region:=ml_private.region_at(s->>'version',s#>>array['players',a::text,'cell']);
 select coalesce(jsonb_agg(p->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality q(p,ord)
 where ml_private.stage4_on_board(s,(p->>'seat')::int) and ((p->>'seat')::int=a or s->>'mode'='team' and p->'team'=s#>array['players',a::text,'team'])
 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),(p->>'seat')::int,p->>'character')
 and (ml_private.region_at(s->>'version',p->>'cell')=region or ml_private.neighbor_for_version(s->>'version',region,ml_private.region_at(s->>'version',p->>'cell')));return result;
end $$;
create or replace function ml_private.p3_mayi_skill(s jsonb,cmd jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;targets jsonb;target integer;label text;begin
 perform ml_private.need(s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and s#>>array['players',a::text,'character']='character-025' and ml_private.stage4_on_board(s,a),'樱岛麻衣仅限本版本马懿使用');
 perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=3,'樱岛麻衣需要3AP');targets:=ml_private.p3_mayi_targets(s,a);perform ml_private.need(jsonb_array_length(targets)>0,'当前没有合法治疗目标');
 s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-3));
 select string_agg('S'||((x#>>'{}')::int+1),'、' order by ord) into label from jsonb_array_elements(targets) with ordinality q(x,ord);
 s:=ml_private.emit(s,'skill','S'||(a+1)||' 樱岛麻衣，支付3AP，治疗'||label);
 for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.heal(s,target,1,false);end loop;return s;
end $$;
create or replace function ml_private.p3_prepare_hit(s jsonb,h jsonb,environment boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(h->>'source')::int;pending jsonb:=s#>'{cardStack,stack,-1}';card text:=h->>'originCard';begin
 if s->>'version' not in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or environment or (h->>'amount')::int<=0 or a is null or s#>>array['players',a::text,'character']<>'character-013' then return s||jsonb_build_object('_hit',h);end if;
 if card is null and (pending->>'actor')::int=a and h->>'category'='attack' and coalesce(h->>'extra','false')<>'true' and coalesce(h->>'reflected','false')<>'true' then card:=pending->>'definition';end if;
 if card is null or not (ml_private.game_data(s,'cardTags')->split_part(card,'#',1) ? '外星') then return s||jsonb_build_object('_hit',h);end if;
 if not ml_private.character_effect_allowed(jsonb_build_object('origin','card','actor',a,'roleModifiers',jsonb_build_array(jsonb_build_object('actor',a,'kind','damage'))),(h->>'target')::int,s#>>array['players',h->>'target','character']) then return s||jsonb_build_object('_hit',null);end if;
 s:=ml_private.emit(s,'skill','S'||(a+1)||' 武士刀：外星伤害+1');return s||jsonb_build_object('_hit',h||jsonb_build_object('amount',(h->>'amount')::int+1));
end $$;
create or replace function ml_private.p3c_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s->>'version' in ('web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19'),false)$$;
create or replace function ml_private.p3c_end(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$begin
 if not ml_private.p3c_enabled(s) then return s;end if;
 s:=jsonb_set(s,array['stage3','c','sleep',a::text],to_jsonb(ml_private.p3h_active_allowed(s,a) and s#>>array['players',a::text,'character']='character-047' and ml_private.stage4_on_board(s,a) and s#>>array['stage3','c','used',a::text]='false'));
 return jsonb_set(s,array['stage3','c','feather',a::text],'false');
end $$;
create or replace function ml_private.p3d_spawn_pool(s jsonb,pool jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare catalog jsonb; result jsonb;begin
 if s->>'catalogVersion' not in ('web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return pool;end if;catalog:=ml_private.version_catalog(s->>'catalogVersion');
 select coalesce(jsonb_agg(v order by ord),'[]') into result from jsonb_array_elements(pool) with ordinality q(v,ord) where
 (s->>'catalogVersion'='web-v0.1.19' and v#>>'{}'='character-035') or (select count(*) from ml_private.arr(s->'selected') p where p<>'null'::jsonb and catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion']) <
 (select count(*) from ml_private.arr(catalog#>'{mapDefinition,cells}') c where c->>'region'=catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion']);return result;end $$;
create or replace function ml_private.p3d_spawn_safe(s jsonb) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare i integer; a integer; pool jsonb; catalog jsonb:=ml_private.version_catalog(s->>'catalogVersion'); r text; slots integer; extra integer; n integer; safe boolean:=true; picked jsonb; next_s jsonb;begin
 if s->>'catalogVersion' not in ('web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or (s->>'cursor')::int=4 then return true;end if;
 for i in (s->>'cursor')::int..3 loop a:=(s->'order'->>i)::int;select coalesce(jsonb_agg(v order by ord),'[]') into pool from jsonb_array_elements(ml_private.p3d_spawn_pool(s,s->'pools'->(s->'teams'->>a))) with ordinality q(v,ord) where not(s->'selected' @> jsonb_build_array(v));
 if jsonb_array_length(pool)<3 then return false;end if;extra:=0;
 for r in select distinct catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion'] from ml_private.arr(pool) v where not(s->>'catalogVersion'='web-v0.1.19' and v#>>'{}'='character-035') loop
 select count(*) into slots from ml_private.arr(catalog#>'{mapDefinition,cells}') c where c->>'region'=r;
 slots:=slots-(select count(*) from ml_private.arr(s->'selected') p where p<>'null'::jsonb and catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=r);
 if slots<=i-(s->>'cursor')::int then select count(*) into n from ml_private.arr(pool) p where catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=r;extra:=extra+greatest(0,n-slots);end if;end loop;
 if jsonb_array_length(pool)-(i-(s->>'cursor')::int)-extra<3 then safe:=false;end if;end loop;
 if safe then return true;end if;a:=(s->'order'->>(s->>'cursor')::int)::int;
 for picked in select * from ml_private.arr(ml_private.p3d_spawn_pool(s,s->'pools'->(s->'teams'->>a))) p where not(s->'selected' @> jsonb_build_array(p)) loop
 next_s:=jsonb_set(s,array['selected',a::text],picked);next_s:=jsonb_set(next_s,'{cursor}',to_jsonb((s->>'cursor')::int+1));if not ml_private.p3d_spawn_safe(next_s) then return false;end if;end loop;return true;end $$;
create or replace function ml_private.p3d_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s->>'version' in ('web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19'),false)$$;
create or replace function ml_private.p3d_ball_allowed(s jsonb,a integer,t integer,converted boolean default false) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select not ml_private.p3h_small(s,t) and (not ml_private.p3d_enabled(s) or s#>>array['players',t::text,'character']<>'character-029' and ml_private.character_effect_allowed(jsonb_build_object('origin',case when converted then 'role-active' else 'card' end,'actor',a,'roleModifiers',case when s#>>array['players',a::text,'character']='character-029' then jsonb_build_array(jsonb_build_object('actor',a,'kind','target')) else '[]'::jsonb end),t,s#>>array['players',t::text,'character']))$$;
create or replace function ml_private.p3e_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s->>'version' in ('web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19'),false)$$;
create or replace function ml_private.p3e_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer:=(t->>'target')::int;data jsonb:=t->'data';root text:=data->>'root';source integer:=(data->>'source')::int;action text:=t->>'action';cells jsonb;gate jsonb;tasks jsonb:='[]';egg integer;max_hp integer;max_distance integer;origin text;destination text;first_cell text;second_cell text;c jsonb:=s#>'{cardStack,stack,-1}';begin
 if root is not null then s:=jsonb_set(s,'{stage3,e,current}',to_jsonb(root));end if;
 if action='e-consent' then if ml_private.stage4_on_board(s,a) then s:=ml_private.select_choice(s,'move-consent',a,at,jsonb_build_object('data',data)||case when source is null then '{}'::jsonb else jsonb_build_object('source',source) end);end if;return s;end if;
 if action='e-relocate' then if ml_private.stage4_on_board(s,a) and ml_private.stage4_board_empty(s,a,data->>'cell',jsonb_build_array(a)) and ml_private.stage3_can_enter(s,a,data->>'cell') then s:=ml_private.p3e_relocate(s,a,data->>'cell',(data->>'voluntary')::boolean,(data->>'carry')::boolean,(data->>'reactive')::boolean,source,root);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;
 if action='e-egg' then select (v->>'seat')::int into egg from ml_private.arr(s->'players') v where v->>'character'='character-024' and ml_private.stage4_on_board(s,(v->>'seat')::int);if egg is null or s#>>array['stage3','e','eggUsed',root]='true' or coalesce(s#>>array['stage3','e','moved',root],'false')<>'true' then return s;end if;cells:=ml_private.p3e_neighbours(s,egg,true);if jsonb_array_length(cells)>0 then s:=jsonb_set(s,array['stage3','e','eggUsed',root],'true');s:=ml_private.select_choice(s,'egg-move',egg,at,jsonb_build_object('cells',cells,'data',jsonb_build_object('root',root)));end if;return s;end if;
 if action='e-highest' then if not ml_private.stage4_on_board(s,a) then return s;end if;select max((v->>'hp')::int) into max_hp from ml_private.arr(s->'players') v where ml_private.stage4_on_board(s,(v->>'seat')::int);for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and (s#>>array['players',v#>>'{}','hp'])::int=max_hp and ml_private.p3e_group_allowed(s,a,(v#>>'{}')::int,true) loop tasks:=tasks||jsonb_build_array(ml_private.stage3_task('e-force',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('root',root,'mode','away','base',s#>array['players',a::text,'cell'],'locked',true))));end loop;return ml_private.stage3_prepend(s,tasks);end if;
 if action='e-force' then if not ml_private.stage4_on_board(s,a) or not ml_private.p3e_group_allowed(s,a,target,coalesce((data->>'locked')::boolean,false)) then return s;end if;cells:=ml_private.p3e_force_cells(s,target,data);if jsonb_array_length(cells)=0 then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;return ml_private.select_choice(s,'force-step',a,at,jsonb_build_object('source',target,'cells',cells,'data',data));end if;
 if action='e-escape-hit' then if not ml_private.stage4_on_board(s,a) then return s;end if;select max(ml_private.stage4_region_distance(s,(v#>>'{}')::int,data->>'region')) into max_distance from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int);select coalesce(jsonb_agg(jsonb_build_object('target',v,'amount',1,'source',a,'category','response') order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and ml_private.stage4_region_distance(s,(v#>>'{}')::int,data->>'region')=max_distance and ml_private.p3e_group_allowed(s,a,(v#>>'{}')::int);s:=ml_private.damage(s,tasks);return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end if;
 if action='e-off-map' then if not ml_private.stage4_on_board(s,target) then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;s:=ml_private.p3h_circle_gate(s,target,null,jsonb_build_array(t),root);gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if gate<>'null'::jsonb then return ml_private.stage3_prepend(s,gate);end if;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');return ml_private.emit(s,'off-map','S'||(target+1)||' 移出地图，等待下个个人开始返回');end if;
 if action='e-swap' then if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or c is null or not ml_private.stage3_card_allowed(s,a,c->>'definition',c->'effect') or not ml_private.stage3_card_allowed(s,target,c->>'definition',c->'effect') then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;
 origin:=s#>>array['players',a::text,'cell'];destination:=s#>>array['players',target::text,'cell'];first_cell:=ml_private.playtest_relocation_cell(s,a,origin,destination,jsonb_build_array(target));second_cell:=ml_private.playtest_relocation_cell(s,target,destination,origin,jsonb_build_array(a));if first_cell is null or second_cell is null or first_cell=second_cell or not ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,first_cell,jsonb_build_array(a,target)) or not ml_private.stage3_empty_entry(ml_private.stage3_board(s),target,second_cell,jsonb_build_array(a,target)) or not ml_private.stage3_can_enter(s,a,first_cell) or not ml_private.stage3_can_enter(s,target,second_cell) or ml_private.stage3_mount_blocked(s,a) then return s;end if;
 s:=ml_private.p3f_move_gate(s,a,first_cell,false,root);if s->>'_fMoveAllowed'='false' then return s-'_fMoveAllowed';end if;s:=ml_private.p3f_move_gate(s-'_fMoveAllowed',target,second_cell,false,root);if s->>'_fMoveAllowed'='false' then return s-'_fMoveAllowed';end if;s:=s-'_fMoveAllowed';s:=ml_private.p3h_circle_gate(s,a,first_cell,jsonb_build_array(t),root);gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if gate<>'null'::jsonb then return ml_private.stage3_prepend(s,gate);end if;s:=ml_private.p3h_circle_gate(s,target,second_cell,jsonb_build_array(t),root);gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if gate<>'null'::jsonb then return ml_private.stage3_prepend(s,gate);end if;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=ml_private.p3e_relocate(s,a,first_cell,true,true,true,a,root);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=jsonb_set(s,array['stage4','offMap',target::text],'false');s:=ml_private.p3e_relocate(s,target,second_cell,false,true,true,a,root);return ml_private.stage3_prepend(s,tasks||(s->'_relocationTasks'))-'_relocationTasks';end if;
 if action='e-elbow' then if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or not ml_private.stage4_board_empty(s,target,data->>'cell',jsonb_build_array(target)) or not ml_private.stage3_can_enter(s,target,data->>'cell') or not ml_private.stage3_can_enter(s,a,s#>>array['players',target::text,'cell']) or ml_private.stage3_mount_blocked(s,a) then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.p3f_move_gate(s,target,data->>'cell',false,root);if s->>'_fMoveAllowed'='false' then return s-'_fMoveAllowed';end if;s:=ml_private.p3f_move_gate(s-'_fMoveAllowed',a,origin,false,root);if s->>'_fMoveAllowed'='false' then return s-'_fMoveAllowed';end if;s:=s-'_fMoveAllowed';s:=ml_private.p3h_circle_gate(s,target,data->>'cell',jsonb_build_array(t),root);gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if gate<>'null'::jsonb then return ml_private.stage3_prepend(s,gate);end if;s:=ml_private.p3h_circle_gate(s,a,origin,jsonb_build_array(t),root);gate:=s->'_hCircleGate';s:=s-'_hCircleGate';if gate<>'null'::jsonb then return ml_private.stage3_prepend(s,gate);end if;s:=ml_private.p3e_relocate(s,target,data->>'cell',false,true,true,a,root);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.p3e_relocate(s,a,origin,true,true,true,a,root);return ml_private.stage3_prepend(s,tasks||(s->'_relocationTasks'))-'_relocationTasks';end if;
 raise exception '未知E批任务';end $$;
create or replace function ml_private.p3f_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select s->>'version' in ('web-v0.1.17','web-v0.1.18','web-v0.1.19')$$;
create or replace function ml_private.p3f_cast_heal(s jsonb,a integer,definition text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare amount integer;begin
 if not ml_private.p3f_uncapped(s,a) or not(coalesce(ml_private.version_catalog(s->>'version')#>array['runtimeData','cardTags',definition],'[]') ? '搏击操') then return s;end if;
 amount:=ml_private.stage3_healing(s,a,1,false);s:=jsonb_set(s,array['players',a::text,'hp'],to_jsonb((s#>>array['players',a::text,'hp'])::int+amount));s:=ml_private.p3h_cooperate_heal(s,a,amount);return ml_private.emit(s,'heal','S'||(a+1)||' 搏击操爱好者回复'||amount||'生命');end $$;
create or replace function ml_private.p3f_damage_frame(s jsonb,d jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare mirrors jsonb:='[]';injury jsonb;idx integer:=(d->>'index')::int;h jsonb;original jsonb;p jsonb;result jsonb;src integer;a integer;blocked integer;remaining integer;loss integer;prior integer;wound integer;environment boolean:=(d->>'environment')::boolean;begin
 if not(d ? 'batch') then s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));d:=d||jsonb_build_object('batch',s->'batch');end if;
 while idx<jsonb_array_length(d->'hits') loop
  original:=d->'hits'->idx;a:=(original->>'target')::int;if not ml_private.stage4_on_board(s,a) or (original->>'amount')::int<=0 then idx:=idx+1;continue;end if;
  if d ? 'prepared' then h:=d#>'{prepared,hit}';blocked:=(d#>>'{prepared,blocked}')::int;remaining:=(d#>>'{prepared,remaining}')::int;d:=d-'prepared';
  else
   s:=ml_private.stage4_prepare_hit(s,original,environment);h:=s->'_hit';s:=s-'_hit';if h='null'::jsonb then idx:=idx+1;continue;end if;
   if not environment and s#>>array['players',a::text,'character']='character-037' or ml_private.stage3_equipped(s,a,'basic-059') then h:=h||jsonb_build_object('amount',least(1,(h->>'amount')::int));end if;
   if (h->>'amount')::int<=0 then idx:=idx+1;continue;end if;p:=s->'players'->a;blocked:=case when h->>'trueDamage'='true' then 0 else least((p->>'shield')::int,(h->>'amount')::int) end;remaining:=(h->>'amount')::int-blocked;s:=jsonb_set(s,array['players',a::text,'shield'],to_jsonb((p->>'shield')::int-blocked));
   if p->>'character'='character-051' and remaining>0 and (p->>'maxHp')::int>1 then d:=d||jsonb_build_object('index',idx,'prepared',jsonb_build_object('hit',h,'blocked',blocked,'remaining',remaining));return ml_private.select_choice(s,'f-tenacity',a,at,jsonb_build_object('count',least(remaining,(p->>'hp')::int,(p->>'maxHp')::int-1),'data',d));end if;
  end if;
  p:=s->'players'->a;prior:=(p->>'hp')::int;
  if h->>'jelly'='true' and not ml_private.p3f_uncapped(s,a) then result:=ml_private.p3f_jelly_health(prior,(p->>'maxHp')::int,remaining);p:=p||jsonb_build_object('hp',result->'hp','maxHp',result->'maxHp');loss:=(result->>'hpLoss')::int;else loss:=least(prior,remaining);p:=p||jsonb_build_object('hp',prior-loss);end if;s:=ml_private.put_player(s,a,p);src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s#>>array['players',src::text,'damage'])::int+loss,'kills',(s#>>array['players',src::text,'kills'])::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end));end if;
  s:=ml_private.emit(s,'damage','S'||(a+1)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',d->'batch'));
  s:=ml_private.p3h_observe_hp(s);if loss>0 then s:=ml_private.p3g_cube_injury(s,h,loss);
   d:=jsonb_set(d,'{injured}',(d->'injured')||jsonb_build_array(h||jsonb_build_object('loss',loss)));
   if s#>>'{stage3,f,firstDeath}'='false' and src is not null and s#>>array['players',src::text,'character']='character-017' then wound:=(s#>>array['stage3','f','wounds',a::text])::int+loss;s:=jsonb_set(s,array['stage3','f','wounds',a::text],to_jsonb(wound));if ml_private.p3f_uncapped(s,a) then s:=jsonb_set(s,array['stage3','f','unlimitedCeil',a::text],to_jsonb(least(coalesce((s#>>array['stage3','f','unlimitedCeil',a::text])::int,prior),prior)-loss));end if;end if;
   if (p->>'hp')::int>0 and p->>'character'='character-018' then s:=jsonb_set(s,array['stage3','f','home',a::text],'true');end if;
   if (p->>'hp')::int>0 and p->>'character'='character-032' then s:=jsonb_set(s,array['players',a::text,'maxHp'],to_jsonb((p->>'maxHp')::int+loss));s:=ml_private.stage3_gain_ap(s,a,2*loss)-'_gain';s:=ml_private.emit(s,'skill','S'||(a+1)||' 和气：上限+'||loss||'，获得'||(2*loss)||'AP');end if;
  end if;idx:=idx+1;
 end loop;
 if s#>>'{cardStack,stack,-1,definition}'='basic-006' then s:=jsonb_set(s,array['stage3','f','results',d->>'token'],d->'injured');end if;
 for injury in select v from ml_private.arr(d->'injured') v loop mirrors:=mirrors||ml_private.p3h_cooperate_health(s,(injury->>'target')::int,(injury->>'loss')::int,'damage');end loop;s:=ml_private.p3f_complete_damage(s,d->'injured',environment,(d->>'suppressPursuit')::boolean);return ml_private.stage3_prepend(s,mirrors||(s->'_triggers'))-'_triggers';end $$;
create or replace function ml_private.p3f_complete_damage(s jsonb,injured jsonb,environment boolean,skip_pursuit boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare h jsonb;p jsonb;a integer;src integer;triggers jsonb:='[]';homes jsonb;begin
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=ml_private.exercise_discard(s,p->'hand'); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); if exists(select 1 from ml_private.arr(s->'players') member where member->'eliminated'<>'null'::jsonb) then s:=jsonb_set(s,'{stage3,f,firstDeath}','true');s:=jsonb_set(s,'{stage3,f,wounds}','[0,0,0,0]');s:=jsonb_set(s,'{stage3,f,unlimitedCeil}','[null,null,null,null]');end if;
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage3_death(s,a);end if;s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 s:=ml_private.p3h_cooperate_cleanup(s,true);s:=ml_private.p3h_observe_hp(s);if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.stage4_after_damage(s,injured,environment);triggers:=s->'_gearTriggers';s:=s-'_gearTriggers';end if;
 select coalesce(jsonb_agg(ml_private.stage3_task('f-home',jsonb_build_object('actor',(v->>'target')::int,'data',jsonb_build_object('root','home'||(s->>'batch')))) order by ord),'[]') into homes from jsonb_array_elements(injured) with ordinality q(v,ord) where s#>>array['players',v->>'target','character']='character-018' and ml_private.stage4_on_board(s,(v->>'target')::int);triggers:=homes||triggers;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) and (s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',a,'roleModifiers','[]'::jsonb),src,s#>>array['players',src::text,'character'])) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop;
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and not skip_pursuit then
 for h in select * from ml_private.arr(injured) loop src:=(h->>'source')::int;a:=(h->>'target')::int;
 if src is null or src=a or (s#>>array['players',src::text,'hp'])::int<=0 or (s#>>array['players',a::text,'hp'])::int<=0 or s#>>array['players',src::text,'character']<>'character-005' or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',src,'roleModifiers','[]'::jsonb),a,s#>>array['players',a::text,'character']) then continue;end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then
 if coalesce(s#>'{cardStack,stack,0,pursuits}','[]') @> jsonb_build_array(a) then continue;end if;
 s:=jsonb_set(s,'{cardStack,stack,0,pursuits}',coalesce(s#>'{cardStack,stack,0,pursuits}','[]')||jsonb_build_array(a));end if;
 triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','stage3','action','qb','actor',src,'target',a));end loop;end if;
 return s||jsonb_build_object('_triggers',triggers||ml_private.p3d_injury(s,injured)||ml_private.p3h_ren_injuries(s,injured));
end $$;
create or replace function ml_private.p3g_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select s->>'version' in ('web-v0.1.18','web-v0.1.19')$$;
create or replace function ml_private.p3g_prime_quote(s jsonb,a integer,quote jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare effect jsonb:=quote->'effect';begin
 if ml_private.p3h_prime_active(s,a) and coalesce(quote->>'gPrimeQuoted','false')<>'true' then effect:=jsonb_set(effect,'{roleModifiers}',coalesce(effect->'roleModifiers','[]')||jsonb_build_array(jsonb_build_object('actor',a,'kind','active')));quote:=quote||jsonb_build_object('cost',(quote->>'cost')::bigint+1,'effect',effect,'gPrimeQuoted',true);end if;return quote;end $$;
create or replace function ml_private.p3g_counter_actor(s jsonb,c jsonb) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (v#>>'{}')::int from jsonb_array_elements(s->'order') with ordinality q(v,n) where v<>c->'actor' and ml_private.p3h_active_allowed(s,(v#>>'{}')::int) and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>>array['players',v#>>'{}','character']='character-009' and s#>>array['stage3','g','counterUsed',v#>>'{}']='false' and (s#>>array['players',v#>>'{}','ap'])::int>=1 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',v,'roleModifiers','[]'::jsonb),(c->>'actor')::int,s#>>array['players',c->>'actor','character']) order by n limit 1$$;
create or replace function ml_private.p3g_dog_targets(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(q->'seat' order by n),'[]') from jsonb_array_elements(s->'players') with ordinality r(q,n) where ml_private.p3g_enabled(s) and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-022' and ml_private.stage4_on_board(s,(q->>'seat')::int) and not exists(select 1 from ml_private.arr(s->'players') east where east->>'character'='character-010' and (east->'seat'=q->'seat' or s->>'mode'='team' and east->'team'=q->'team')) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),(q->>'seat')::int,q->>'character')$$;
create or replace function ml_private.p3g_bread_equipment(s jsonb,a integer,requested text default null) returns text language sql stable set search_path=pg_catalog,ml_private as $$select v#>>'{}' from jsonb_array_elements(ml_private.p3h_gear_cards(s,a)) with ordinality q(v,n) where (requested is null or v#>>'{}'=requested) and ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-054' and ml_private.character_effect_allowed(ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment'),a,s#>>array['players',a::text,'character']) and ml_private.p3h_gear_starts(s,a,v#>>'{}')>=coalesce((s#>>array['stage3','g','gearBreadReadyAt',v#>>'{}'])::int,0) order by n limit 1$$;
create or replace function ml_private.p3g_bread(s jsonb,a integer,target integer,requested text default null) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare card text:=ml_private.p3g_bread_equipment(s,a,requested);begin
 perform ml_private.need(card is not null and a<>target and (s#>>array['players',target::text,'hp'])::int>0,'面包技能暂不可用或目标不合法');s:=jsonb_set(s,array['stage3','g','gearBreadReadyAt',card],to_jsonb(ml_private.p3h_gear_starts(s,a,card)+2));return jsonb_set(s,array['stage3','breadPending',target::text],'true');end $$;
create or replace function ml_private.p3g_terrain_setting(s jsonb,cmd jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer:=(cmd->>'actor')::int;cards jsonb;card text;begin
 select coalesce(jsonb_agg(v order by n),'[]') into cards from jsonb_array_elements(ml_private.p3h_gear_cards(s,a)) with ordinality q(v,n) where ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-069' and ml_private.stage3_card_allowed(s,a,v#>>'{}',ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment'));
 perform ml_private.need(ml_private.stage4_on_board(s,a) and jsonb_array_length(cards)>0 and jsonb_typeof(cmd->'accept')='boolean' and (cmd->>'card' is null or cards ? (cmd->>'card')),'唐车设置不可用或选项无效');
 for card in select v#>>'{}' from ml_private.arr(cards) v where cmd->>'card' is null or v#>>'{}'=cmd->>'card' loop s:=jsonb_set(s,array['stage3','g','gearTerrain',card],cmd->'accept');end loop;
 return ml_private.p3h_gear_refresh(jsonb_set(s,array['stage4','terrainIgnore',a::text],to_jsonb(exists(select 1 from ml_private.arr(cards) v where s#>>array['stage3','g','gearTerrain',v#>>'{}']='true'))));end $$;
create or replace function ml_private.p3g_after_die(s jsonb,reason text,owner integer,raw integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare r jsonb:=s->'_gReplay';idx integer;old jsonb;programmer integer;ev jsonb;intent jsonb;reroll integer;math boolean;saved_events jsonb;saved_serial jsonb;begin
 if not ml_private.p3g_enabled(s) then return s||jsonb_build_object('_roll',raw);end if;
 perform ml_private.need(r is not null,'G骰子缺少续接上下文');idx:=(r->>'index')::int;s:=jsonb_set(s,'{_gReplay,index}',to_jsonb(idx+1));
 select v into old from jsonb_array_elements(r->'steps') v where (v->>'index')::int=idx limit 1;
 if old is not null then
  perform ml_private.need((old->>'owner')::int is not distinct from owner and old->>'reason'=reason and (old->>'raw')::int=raw,'G骰子续接身份不一致');
  if old->>'programmed'='true' then
   perform ml_private.need(old->'programmer'<>'null'::jsonb,'G编程来源缺失');s:=ml_private.p3g_raw_die(s);reroll:=(s->>'_roll')::int;s:=s-'_roll';perform ml_private.need(reroll=(old->>'reroll')::int,'G编程续接随机不一致');s:=jsonb_set(s,array['stage3','g','programUsed',old->>'programmer'],'true');
  end if;
  if old ? 'h' then if old#>>'{h,rolled}'='true' then s:=ml_private.p3g_raw_die(s);perform ml_private.need(s->'_roll'=old#>'{h,reroll}','H狂叫续接随机不一致');s:=jsonb_set(s-'_roll',array['stage3','h','rerollRoots',old#>>'{h,root}'],'true');end if;if old#>>'{h,draw}'='true' then saved_events:=s->'events';saved_serial:=s->'eventSerial';s:=ml_private.draw(s,(old#>>'{h,sixActor}')::int,2);s:=s||jsonb_build_object('events',saved_events,'eventSerial',saved_serial);end if;end if;for intent in select * from ml_private.arr(old->'intents') loop s:=ml_private.p3g_side_intent(s,intent->'command',(intent->>'at')::double precision,true);perform ml_private.need(s->>'_gSideHandled'='true','G等待期间意图续接失败');s:=s-'_gSideHandled';end loop;
  for ev in select * from ml_private.arr(old->'events') loop s:=s||jsonb_build_object('eventSerial',(s->>'eventSerial')::int+1);s:=jsonb_set(s,'{events}',(s->'events')||jsonb_build_array(ev||jsonb_build_object('seq',s->'eventSerial')));end loop;
  s:=s||jsonb_build_object('choiceSerial',old->'choiceSerial','clock',jsonb_build_object('remaining',old->'remaining','since',null));s:=jsonb_set(s,'{_gReplay}',(s->'_gReplay')||jsonb_build_object('continued',true,'now',old->'at','logicalAt',old->'at'));return s||jsonb_build_object('_roll',old->'final');
 end if;
 select (v#>>'{}')::int into programmer from jsonb_array_elements(s->'order') with ordinality q(v,n)
 where (v#>>'{}')::int is distinct from owner and ml_private.p3h_active_allowed(s,(v#>>'{}')::int) and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>>array['players',v#>>'{}','character']='character-033' and s#>>array['stage3','g','programUsed',v#>>'{}']='false' and (owner is null or ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',(v#>>'{}')::int,'roleModifiers','[]'::jsonb),owner,s#>>array['players',owner::text,'character'])) order by n limit 1;
 math:=owner is not null and ml_private.p3h_active_allowed(s,owner) and ml_private.stage4_on_board(s,owner) and s#>>array['players',owner::text,'character']='character-042';
 if programmer is not null or math or ml_private.p3h_can_reroll(s,owner) or ml_private.p3h_six_actor(s,owner,raw) is not null then raise exception using errcode='P3G01',message='G骰子等待权威选择',detail=jsonb_build_object('state',s,'index',idx,'owner',owner,'reason',reason,'raw',raw,'programmer',programmer)::text;end if;
 return s||jsonb_build_object('_roll',raw);end $$;
create or replace function ml_private.p3g_capture(err jsonb,driver jsonb,steps jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare s jsonb:=err->'state';random jsonb:=coalesce(s#>'{random,_gTrace,entries}','[]');waiting jsonb;kind text;a integer;begin
 at:=coalesce((s#>>'{_gReplay,logicalAt}')::double precision,at);
 s:=(s-'_gReplay')#-'{random,_gTrace}';waiting:=jsonb_build_object('index',err->'index','owner',err->'owner','reason',err->'reason','raw',err->'raw','value',err->'raw','programmer',err->'programmer','programmed',false,'reroll',null,'eventStart',jsonb_array_length(s->'events'));
 if ml_private.p3h_enabled(s) then waiting:=waiting||jsonb_build_object('h',jsonb_build_object('root',case when err->'owner'='null'::jsonb then 'none' else ml_private.p3h_reroll_key(s,(err->>'owner')::int) end,'rolled',false,'reroll',null,'sixActor',null,'draw',false));end if;kind:=case when err->'programmer'<>'null'::jsonb then 'g-program' when ml_private.p3h_can_reroll(s,(err->>'owner')::int) then 'h-reroll' when ml_private.p3h_active_allowed(s,(err->>'owner')::int) and s#>>array['players',err->>'owner','character']='character-042' then 'g-math' else 'h-six' end;a:=case when kind='h-six' then ml_private.p3h_six_actor(s,(err->>'owner')::int,(err->>'raw')::int) else coalesce((err->>'programmer')::int,(err->>'owner')::int) end;if kind='h-six' then waiting:=jsonb_set(waiting,'{h,sixActor}',to_jsonb(a));end if;s:=jsonb_set(s,'{stage3,g,dice}',jsonb_build_object('driver',driver,'steps',steps,'random',random,'waiting',waiting));
 return ml_private.select_choice(s,kind,a,at,jsonb_build_object('data',jsonb_build_object('owner',err->'owner','reason',err->'reason','value',err->'raw')));end $$;
create or replace function ml_private.p3g_dispatch_step(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare flow jsonb:=previous#>'{stage3,g,dice}';s jsonb;v jsonb;c jsonb:=previous->'choice';pending jsonb;w jsonb;step jsonb;events jsonb;timeout boolean;choice_at double precision;a integer;option text;begin
 if flow is null then
  v:=ml_private.p3g_execute(jsonb_build_object('kind','command','base',previous,'command',cmd,'at',at),'[]','[]',at);
  if v->>'ok'<>'true' then return jsonb_build_object('state',previous,'ok',false,'error',v->'error');end if;
  s:=v->'state';if s#>'{stage3,g,dice}' is not null then s:=s||jsonb_build_object('seen',(previous->'seen')||jsonb_build_array(cmd->'id'),'revision',(previous->>'revision')::int+1,'time',at);v:=jsonb_set(v,'{state}',s);end if;return v;
 end if;
 perform ml_private.need(jsonb_typeof(cmd)='object' and jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not(previous->'seen' ? (cmd->>'id')),'重复命令');
 perform ml_private.need(cmd->'revision'=previous->'revision','命令版本过期');
 perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::numeric between 0 and 3,'座位/命令版本必须为有效整数');a:=(cmd->>'actor')::int;
 perform ml_private.need(at is not null and at not in ('NaN'::double precision,'Infinity'::double precision,'-Infinity'::double precision) and at>=(previous->>'time')::double precision,'时钟必须单调');
 if coalesce(cmd->>'type','') not in ('choose','tick') then
  perform ml_private.need(at<(c->>'deadline')::double precision,'命令已超时，请先处理时钟事件');s:=ml_private.p3g_side_intent(previous,cmd,at,false);perform ml_private.need(s->>'_gSideHandled'='true','请先完成改骰选择');s:=s-'_gSideHandled';
  s:=jsonb_set(s,'{stage3,g,dice,waiting,intents}',coalesce(s#>'{stage3,g,dice,waiting,intents}','[]')||jsonb_build_array(jsonb_build_object('command',cmd,'at',at)));s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);return jsonb_build_object('state',s,'ok',true);
 end if;
 if cmd->>'type'='tick' and at<(c->>'deadline')::double precision then return jsonb_build_object('state',previous,'ok',true);end if;
 timeout:=cmd->>'type'='tick';choice_at:=case when timeout then (c->>'deadline')::double precision else at end;
 if not timeout then
  perform ml_private.need(at<(c->>'deadline')::double precision,'命令已超时，请先处理时钟事件');perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need(a=(c->>'actor')::int,'请交给待选择的座位操作');perform ml_private.need(not(cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值');
 end if;
 s:=previous;pending:=flow;w:=pending->'waiting';if ml_private.p3h_enabled(s) then a:=(c->>'actor')::int;end if;
 if c->>'kind'='g-program' then
  if not timeout and cmd->>'accept'='true' then
   perform ml_private.need(w->'programmer'=c->'actor' and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and s#>>array['stage3','g','programUsed',a::text]='false','编程次数或来源无效');
   s:=jsonb_set(s,array['stage3','g','programUsed',a::text],'true');w:=w||jsonb_build_object('programmed',true);
   s:=jsonb_set(s,'{random,_gTrace}',jsonb_build_object('index',jsonb_array_length(pending->'random'),'entries',pending->'random'));s:=ml_private.p3g_raw_die(s);w:=w||jsonb_build_object('value',s->'_roll','reroll',s->'_roll');pending:=jsonb_set(pending,'{random}',s#>'{random,_gTrace,entries}');s:=(s-'_roll')#-'{random,_gTrace}';s:=ml_private.emit(s,'dice','编程：d6 = '||(w->>'value'),w->'value');
  end if;
  if timeout then s:=ml_private.emit(s,'timeout','S'||((c->>'actor')::int+1)||' 编程选择超时');end if;
  if ml_private.p3h_can_reroll(s,(w->>'owner')::int) then return ml_private.p3h_window(s,pending,w,'h-reroll',(w->>'owner')::int,choice_at,at,cmd);end if;if w->'owner'<>'null'::jsonb and ml_private.p3h_active_allowed(s,(w->>'owner')::int) and ml_private.stage4_on_board(s,(w->>'owner')::int) and s#>>array['players',w->>'owner','character']='character-042' then
   pending:=jsonb_set(pending,'{waiting}',w);s:=jsonb_set(s,'{stage3,g,dice}',pending);s:=ml_private.select_choice(s,'g-math',(w->>'owner')::int,choice_at,jsonb_build_object('data',jsonb_build_object('owner',w->'owner','reason',w->'reason','value',w->'value')));s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);return jsonb_build_object('state',s,'ok',true);
  end if;
 elsif c->>'kind'='h-reroll' then
  perform ml_private.need(ml_private.p3h_can_reroll(s,(w->>'owner')::int) and w->'owner'=c->'actor','狂叫次数或来源无效');
  if not timeout and cmd->>'accept'='true' then s:=jsonb_set(s,array['stage3','h','rerollRoots',w#>>'{h,root}'],'true');w:=jsonb_set(w,'{h,rolled}','true');s:=jsonb_set(s,'{random,_gTrace}',jsonb_build_object('index',jsonb_array_length(pending->'random'),'entries',pending->'random'));s:=ml_private.p3g_raw_die(s);w:=jsonb_set(w,'{value}',s->'_roll');w:=jsonb_set(w,'{h,reroll}',s->'_roll');pending:=jsonb_set(pending,'{random}',s#>'{random,_gTrace,entries}');s:=(s-'_roll')#-'{random,_gTrace}';s:=ml_private.emit(s,'dice','狂叫：d6 = '||(w->>'value'),w->'value');end if;
  if timeout then s:=ml_private.emit(s,'timeout','S'||(a+1)||' 狂叫选择超时');end if;
 elsif c->>'kind'='h-six' then
  perform ml_private.need(w#>'{h,sixActor}'=c->'actor' and ml_private.p3h_six_actor(s,(w->>'owner')::int,(w->>'value')::int)=a,'6技能来源或最终点数无效');
  if not timeout and cmd->>'accept'='true' then w:=jsonb_set(w,'{h,draw}','true');s:=jsonb_set(s,'{random,_gTrace}',jsonb_build_object('index',jsonb_array_length(pending->'random'),'entries',pending->'random'));s:=ml_private.draw(s,a,2);pending:=jsonb_set(pending,'{random}',s#>'{random,_gTrace,entries}');s:=s#-'{random,_gTrace}';s:=ml_private.emit(s,'skill','S'||(a+1)||' 6：最终点数6，免费摸2');end if;
  if timeout then s:=ml_private.emit(s,'timeout','S'||(a+1)||' 6选择超时');end if;
 else
  perform ml_private.need(c->>'kind'='g-math' and w->'owner'=c->'actor' and ml_private.p3h_active_allowed(s,a),'不是当前数学天才窗口');
  if not timeout and cmd ? 'option' then
   perform ml_private.need(jsonb_typeof(cmd->'option')='string' and cmd->>'option' ~ '^[1-6]$','数学天才点数须1—6');option:=cmd->>'option';w:=jsonb_set(w,'{value}',to_jsonb(option::int));s:=ml_private.emit(s,'skill','S'||((c->>'actor')::int+1)||' 数学天才：最终点数'||option);
  end if;
  if timeout then s:=ml_private.emit(s,'timeout','S'||((c->>'actor')::int+1)||' 数学天才选择超时');end if;
 end if;
 if c->>'kind'<>'h-six' and ml_private.p3h_six_actor(s,(w->>'owner')::int,(w->>'value')::int) is not null then a:=ml_private.p3h_six_actor(s,(w->>'owner')::int,(w->>'value')::int);w:=jsonb_set(w,'{h,sixActor}',to_jsonb(a));return ml_private.p3h_window(s,pending,w,'h-six',a,choice_at,at,cmd);end if;select coalesce(jsonb_agg(ev order by n),'[]') into events from jsonb_array_elements(s->'events') with ordinality q(ev,n) where n>(w->>'eventStart')::int;
 step:=(w-'value'-'eventStart')||jsonb_build_object('final',w->'value','events',events,'choiceSerial',s->'choiceSerial','remaining',s#>'{clock,remaining}','at',choice_at);
 v:=ml_private.p3g_execute(pending->'driver',(pending->'steps')||jsonb_build_array(step),pending->'random',choice_at);if v->>'ok'<>'true' then return jsonb_build_object('state',previous,'ok',false,'error',v->'error');end if;
 s:=v->'state';s:=s||jsonb_build_object('seen',(previous->'seen')||jsonb_build_array(cmd->'id'),'revision',(previous->>'revision')::int+1,'time',at);return jsonb_set(v,'{state}',s);
 exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);end $$;
create or replace function ml_private.p3g_food_thief(s jsonb,c jsonb,target integer) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (v#>>'{}')::int from jsonb_array_elements(s->'order') with ordinality q(v,n) where ml_private.p3g_enabled(s) and ml_private.p3g_food_original_allowed(s,c,target) and v<>c->'actor' and ml_private.p3h_active_allowed(s,(v#>>'{}')::int) and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>>array['players',v#>>'{}','character']='character-021' and (s#>>array['players',v#>>'{}','ap'])::int>=2 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',v,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) order by n limit 1$$;
create or replace function ml_private.p3g_haki_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;begin
 if not ml_private.p3g_enabled(s) or t->>'action'<>'g-haki' then return s||jsonb_build_object('_gHakiHandled',false);end if;if ml_private.p3g_haki(s,a) and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and ml_private.p3f_allowed(s,a,target) then s:=ml_private.select_choice(s,'g-haki',a,at,jsonb_build_object('source',target));end if;return s||jsonb_build_object('_gHakiHandled',true);end $$;
create or replace function ml_private.p3g_haki_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(s#>>'{choice,actor}')::int;target integer:=(s#>>'{choice,source}')::int;begin
 if not ml_private.p3g_enabled(s) or s#>>'{choice,kind}'<>'g-haki' then return s||jsonb_build_object('_gHakiHandled',false);end if;if not timeout and cmd->>'accept'='true' and ml_private.p3g_haki(s,a) and ml_private.p3h_active_allowed(s,a) and ml_private.stage4_on_board(s,a) and ml_private.p3f_allowed(s,a,target) then s:=ml_private.p3f_damage(s,jsonb_build_array(jsonb_build_object('source',a,'target',target,'amount',1,'category','response')),false,false);s:=ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end if;return s||jsonb_build_object('_gHakiHandled',true);end $$;
create or replace function ml_private.p3g_dual_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare firstn jsonb:=s#>'{cardStack,stack,-1}';parent jsonb;c jsonb;d jsonb;a integer;idx text;targets jsonb;original_queue jsonb;begin
 if not ml_private.p3g_enabled(s) then return s||jsonb_build_object('_gDualHandled',false);end if;
 if t->>'action'='cleanup' and firstn#>>'{g,copy}'='1' and (not(t ? 'serial') or t->'serial'=firstn->'serial') then s:=ml_private.p3g_close_card(s);firstn:=s->'_closed';s:=s-'_closed';original_queue:=s->'queue';s:=jsonb_set(s,'{queue}','[]');s:=ml_private.p3c_food_tasks(s,firstn);s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('g-repeat-card',jsonb_build_object('data',firstn)))||original_queue);if firstn->>'installed'='true' then s:=jsonb_set(s,'{discard}',(s->'discard')-(firstn->>'card'));end if;parent:=s#>'{cardStack,stack,-1}';s:=s||jsonb_build_object('phase','resolving','attack',case when parent is null then null else jsonb_build_object('actor',parent->'actor','card',parent->'card','targets',parent->'targets','cancelled',parent->'cancelled','elbows',parent->'elbows') end);return s||jsonb_build_object('_gDualHandled',true);end if;
 if t->>'action'<>'g-repeat-card' then return s||jsonb_build_object('_gDualHandled',false);end if;firstn:=t->'data';a:=(firstn->>'actor')::int;parent:=s#>'{cardStack,stack,-1}';
 if not ml_private.stage4_on_board(s,a) or firstn->'responseTo'<>'null'::jsonb and (parent is null or parent->'serial'<>firstn->'responseTo' or not ml_private.p3g_card_target_allowed(s,a,case when firstn->>'definition'='basic-001' then a else (parent->>'actor')::int end,firstn->>'definition')) then s:=jsonb_set(s,'{resolving}',(s->'resolving')-(firstn->>'card'));s:=ml_private.exercise_discard(s,jsonb_build_array(firstn->'card'));s:=ml_private.emit(s,'play','S'||(a+1)||' 质数第二份失效：使用者或父牌已失效');if jsonb_array_length(s#>'{cardStack,stack}')=0 then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then if ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;end if;end if;return s||jsonb_build_object('_gDualHandled',true);end if;
 d:=ml_private.rule_card(s,firstn->>'definition');select coalesce(jsonb_agg(v order by n),'[]') into targets from jsonb_array_elements(firstn#>'{g,targets}') with ordinality q(v,n) where ml_private.p3g_repeat_legal(s,firstn,(v#>>'{}')::int);
 s:=ml_private.stage3_begin_card(s||jsonb_build_object('_hPrimeSecond',true),a,firstn->>'card',firstn->>'definition',targets,firstn->'effect',at,(firstn->>'responseTo')::int);s:=s-'_hPrimeSecond';idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;c:=s#>array['cardStack','stack',idx];c:=jsonb_set(c,'{g,copy}','2');if firstn#>'{g,replacements}' is not null then c:=jsonb_set(c,'{g,replacements}',firstn#>'{g,replacements}');end if;if firstn->>'definition'='basic-017' and firstn->>'countered'<>'true' then c:=jsonb_set(c,'{g,firstSucceeded}','true');end if;
 if firstn ? 'converted' then c:=c||jsonb_build_object('converted',firstn->'converted');end if;if firstn ? 'pushDirection' then c:=c||jsonb_build_object('pushDirection',firstn->'pushDirection');end if;if firstn ? 'replacement' then c:=c||jsonb_build_object('replacement',firstn->'replacement');end if;
 select coalesce(jsonb_agg(p->'seat' order by n),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(p,n) where not ml_private.stage4_location_effect(s,(p->>'seat')::int,firstn->>'definition');c:=c||jsonb_build_object('stage4',coalesce(firstn->'stage4','{}')-array['counterEffective','counterOffered','guessDie','officeExempt']||jsonb_build_object('officeExempt',targets));s:=jsonb_set(s,array['cardStack','stack',idx],c);
 if d->>'type'='attack' or c->>'definition'='basic-002' and c->'responseTo'='null'::jsonb then s:=jsonb_set(s,array['players',a::text,'attacks'],to_jsonb((s#>>array['players',a::text,'attacks'])::int+1));end if;s:=ml_private.emit(s,'play','S'||(a+1)||' 质数第二份'||(d->>'name')||'，不重复支付费用');s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',c->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_gDualHandled',true);
end $$;
create or replace function ml_private.p3g_equipment_actions(s jsonb,a integer,free boolean,blocked boolean) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare bread jsonb:='[]';watch jsonb:='[]';terrain jsonb:='[]';card text;record jsonb;begin
 if not ml_private.p3g_enabled(s) then return '{}';end if;
 if free then select coalesce(jsonb_agg(v order by n),'[]') into bread from jsonb_array_elements(ml_private.p3g_combat_gears(s,a,'basic-054')) with ordinality q(v,n) where ml_private.p3h_gear_starts(s,a,v#>>'{}')>=coalesce((s#>>array['stage3','g','gearBreadReadyAt',v#>>'{}'])::int,0);end if;
 if free and not blocked then for card in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,a,'basic-060')) v loop record:=ml_private.p3h_gear_watch(s,a,card);if record->>'previous' is not null and record->'usedTurn' is distinct from s#>'{stage3,turn}' and record->>'previous'<>s#>>array['players',a::text,'cell'] and ml_private.stage4_board_empty(s,a,record->>'previous',jsonb_build_array(a)) then watch:=watch||jsonb_build_array(jsonb_build_object('card',card,'cell',record->'previous'));end if;end loop;end if;
 if ml_private.stage4_on_board(s,a) then select coalesce(jsonb_agg(jsonb_build_object('card',v,'ignored',coalesce(s#>>array['stage3','g','gearTerrain',v#>>'{}'],'false')='true') order by n),'[]') into terrain from jsonb_array_elements(ml_private.p3g_combat_gears(s,a,'basic-069')) with ordinality q(v,n);end if;
 return jsonb_build_object('equipmentSkills',jsonb_build_object('bread',bread,'watch',watch,'terrain',terrain));
end $$;
create or replace function ml_private.p3g_combat_gears(s jsonb,a integer,definition text) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(ml_private.p3h_gear_cards(s,a)) with ordinality q(v,n) where ml_private.stage4_equipment_definition(s,v#>>'{}')=definition and ml_private.stage3_card_allowed(s,a,v#>>'{}',ml_private.p3h_gear_source(s,a,v#>>'{}')||jsonb_build_object('origin','equipment'))$$;
create or replace function ml_private.p3g_terrain_refresh(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3g_enabled(s) then jsonb_set(s,array['stage4','terrainIgnore',a::text],to_jsonb(exists(select 1 from ml_private.arr(ml_private.p3h_gear_cards(s,a)) v where ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-069' and s#>>array['stage3','g','gearTerrain',v#>>'{}']='true'))) else s end$$;
create or replace function ml_private.p3g_dispatch_core(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous;a integer;typ text:=cmd->>'type';p jsonb;v jsonb;cell text;cost integer;roll integer;steps integer;direction text;deadline double precision;guard integer:=0;changed boolean:=false;begin if cmd ? 'replacements' then perform ml_private.need(ml_private.p3g_prime(s,(cmd->>'actor')::int) and not(cmd ? 'replacement') and jsonb_typeof(cmd->'replacements')='array' and jsonb_array_length(cmd->'replacements')<=2 and (select count(distinct g_item) from ml_private.arr(cmd->'replacements') g_item)=jsonb_array_length(cmd->'replacements') and not exists(select 1 from ml_private.arr(cmd->'replacements') g_item where jsonb_typeof(g_item)<>'string'),'双装备替换输入无效');end if;
 if previous->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.dispatch_before_stage3(previous,cmd,at);end if;
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');a:=(cmd->>'actor')::int;
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location','skill'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array' and not exists(select 1 from ml_private.arr(cmd->'targets') x where jsonb_typeof(x)<>'number' or (x#>>'{}')::numeric<>trunc((x#>>'{}')::numeric) or (x#>>'{}')::int not between 0 and 3),'出牌/目标输入无效');perform ml_private.need((not (cmd ? 'as') or cmd->>'as'='elbow' or ml_private.p3d_enabled(s) and cmd->>'as'='dodge') and (not (cmd ? 'replacement') or jsonb_typeof(cmd->'replacement')='string'),'转换或替换输入无效');end if;
 if typ in ('move','play') and cmd ? 'direction' then perform ml_private.need(cmd->>'direction' in ('up','right','down','left'),'方向输入无效');end if;
 if typ='skill' then perform ml_private.need((not(cmd ? 'region') or jsonb_typeof(cmd->'region')='string') and (cmd->>'kind' in ('jj','bread','revival-quote') or previous->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and cmd->>'kind' in ('quote-cost','watch','flight','gift','terrain','mayi','feather','clan','gas','escape','execute','magma','dog','freeze','circle','cooperate','ren')) and (not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'card') or jsonb_typeof(cmd->'card')='string'),'技能输入无效');end if;
 if typ='skill' and s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then perform ml_private.need((not(cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean') and (not(cmd ? 'cell') or jsonb_typeof(cmd->'cell')='string') and (not(cmd ? 'cards') or jsonb_typeof(cmd->'cards')='array' and not exists(select 1 from ml_private.arr(cmd->'cards') input_card where jsonb_typeof(input_card)<>'string')),'技能输入无效');end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array' and not exists(select 1 from ml_private.arr(cmd->'path') x where jsonb_typeof(x)<>'string'),'路径必须为格子数组');end if;
 if typ='choose' then
 perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号必须为正整数');
 perform ml_private.need(not (cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值');perform ml_private.need(not (cmd ? 'card') or jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效');perform ml_private.need(not (cmd ? 'cell') or jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效');
 perform ml_private.need(not (cmd ? 'cards') or jsonb_typeof(cmd->'cards')='array' and not exists(select 1 from ml_private.arr(cmd->'cards') x where jsonb_typeof(x)<>'string'),'弃牌必须为实体牌数组');
 perform ml_private.need((not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'action') or (cmd->>'action' in ('draw','steal') or previous->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and cmd->>'action'='ap')),'技能选择输入无效');end if;
 perform ml_private.need(at>=(s->>'time')::double precision and at<'Infinity'::double precision,'时钟必须单调');perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期');perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令');perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 if ml_private.p3e_enabled(s) and s->'choice'='null'::jsonb and typ not in ('choose','tick') then s:=jsonb_set(s,'{stage3,e,current}',to_jsonb('revision'||(s->>'revision')));end if;
 if typ='tick' then while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision);exit when deadline is null or deadline>at;exit when guard>=999;guard:=guard+1;s:=ml_private.expire(s,deadline);changed:=true;end loop;if not changed then return jsonb_build_object('state',previous,'ok',true);end if;
 else perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时，请先处理时钟事件');
 if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口');s:=ml_private.choose(s,cmd,at);
 elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and typ='play' and split_part(cmd->>'card','#',1)='basic-017' then s:=ml_private.stage4_reserve_interrupt(s,cmd);
  elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and typ='skill' and cmd->>'kind'='terrain' then s:=ml_private.stage3_skill(s,cmd,at);
  elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and typ='skill' and cmd->>'kind'='quote-cost' and s#>>'{choice,kind}'='card-counter' and s#>'{choice,actor}'=cmd->'actor' then s:=ml_private.stage4_quote(s,a,cmd->>'card');
  else p:=s->'players'->a;perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作');perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');perform ml_private.need(s->>'version' not in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') or ml_private.stage4_on_board(s,a) or typ='end','离场期间只能结束行动');
 if typ='step' then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空');s:=ml_private.classic_walk(s,cmd->'path',at);
 elsif typ='stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格');s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
 elsif typ='end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动，请先离开');s:=ml_private.end_turn(s,at);
 else perform ml_private.need(s->>'phase'='action','请先完成移动');
 if typ='location' then cell:=cmd->>'cell';perform ml_private.need(ml_private.stage3_locations(s,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||jsonb_build_array(a));else s:=ml_private.p3d_pay(s,a,(s#>>array['players',a::text,'ap'])::int);end if;s:=ml_private.stage3_relocate(s,a,cell,true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'));s:=s-'_relocationTasks';s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
 elsif typ='move' then if ml_private.p3h_leap_role(s,a) then s:=ml_private.p3h_leap_move(s,cmd);elsif ml_private.p3g_cube_face(s,a)=6 then s:=ml_private.p3g_cube_move(s,cmd);else perform ml_private.need(not(cmd ? 'cell'),'当前基础移动不接受传送落点');
 perform ml_private.need(p->>'moved'='false' and coalesce(s#>>array['stage3','c','blocked',a::text],'false')<>'true','本个人回合已使用基础移动');perform ml_private.need(not ml_private.stage3_mount_blocked(s,a),'小白马：有坐骑者暂时不能主动位移');cost:=case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a)) end;perform ml_private.need((p->>'ap')::int>=cost,'移动需要1AP');
 if ml_private.p3g_enabled(s) then s:=jsonb_set(s,array['players',a::text,'moved'],'true');end if;s:=ml_private.p3c_move(s,a,cost);if s->>'_cMoveFailed'='true' then s:=s-'_cMoveFailed';else s:=s-'_cMoveFailed';
 if p->>'character'='character-040' then perform ml_private.need(cmd ? 'direction','请先声明移动方向');s:=ml_private.p3g_owned_die(s,'西帝汶方向',a);direction:=ml_private.stage3_west_direction(cmd->>'direction',(s->>'_roll')::int);s:=s-'_roll';end if;
 s:=ml_private.p3g_owned_die(s,'基础移动',a);roll:=(s->>'_roll')::int;s:=s-'_roll';if ml_private.p3f_enabled(s) and p->>'character'='character-036' then s:=jsonb_set(s,array['stage3','f','dry','move'||(s->>'revision')||':'||a],to_jsonb(roll=6));end if;steps:=case when s#>>array['stage3','doubleMove',a::text]='true' and ml_private.stage3_equipped(s,a,'basic-066') then roll else ceil(roll::numeric/2)::int end;s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int+1));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));
 s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'),'costDue',cost>0,'carry',ml_private.stage3_carry_candidates(s,a,p->>'cell'))||case when direction is null then '{}'::jsonb else jsonb_build_object('direction',direction) end,'phase','moving');if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{movement,gearRoot}',s->'revision');end if;if ml_private.p3g_enabled(s) and p->>'character'='character-049' and roll=6 and ml_private.p3h_active_allowed(s,a) then s:=jsonb_set(s,'{movement,haki}','[]');end if;s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when cost=0 then ' 免费移动' else ' 移动结束扣费' end||'，获得'||steps||'步');
 end if;
 end if;elsif typ='skill' then s:=ml_private.stage3_skill(s,cmd,at);
 elsif typ='play' then s:=ml_private.stage3_play(s,cmd,at);else raise exception '未知命令';end if;end if;end if;end if;
 s:=ml_private.pump(s,at);s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);perform ml_private.validate(s);return jsonb_build_object('state',s,'ok',true);
 exception when sqlstate 'P3G01' then raise;when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.stage3_damage(s jsonb,hits jsonb,environment boolean default false,skip_pursuit boolean default false)
returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ begin
 if ml_private.p3f_enabled(s) then return ml_private.p3f_damage(s,hits,environment,skip_pursuit);end if;
 if s->>'version' in ('web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then return ml_private.stage3_damage_before_stage4(s,hits,environment,skip_pursuit);end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then
  select coalesce(jsonb_agg(case when (not environment and s#>>array['players',h->>'target','character']='character-037') or ml_private.stage3_equipped(s,(h->>'target')::int,'basic-059') then h||jsonb_build_object('amount',least(1,(h->>'amount')::int)) else h end order by ord),'[]') into hits
  from jsonb_array_elements(hits) with ordinality q(h,ord) where ml_private.stage4_on_board(s,(h->>'target')::int);
 end if;return ml_private.stage3_damage_before_stage4(s,hits,environment,skip_pursuit);
end $$;
create or replace function ml_private.exercise_discard_before_g(s jsonb,cards jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare card text;owner integer;begin
 for card in select x#>>'{}' from ml_private.arr(cards) x loop
  s:=jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(card));
  if s->>'version' in ('web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and ml_private.exercise_rank(card)>0 then
   owner:=(s#>>array['exercise','owners',card])::int;
   if owner is not null and (s#>>array['players',owner::text,'hp'])::int>0 then s:=ml_private.stage3_gain_ap(s,owner,1)-'_gain';end if;
  end if;
 end loop;return s;
end $$;
create or replace function ml_private.p3g_create_development(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin perform ml_private.need(setup->>'ruleVersion'='web-v0.1.18','开发开局仅接受G版本');
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1,s->'_shuffle'->2,s->'_shuffle'->3) else s->'_shuffle' end; s:=s-'_shuffle'; end if;
 perform ml_private.need(case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then jsonb_array_length(chars)=4 and (select count(distinct x) from ml_private.arr(chars) x)=4 and ml_private.game_data(s,'characterIds') @> chars else (select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x) end,'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if ml_private.p3d_enabled(s) and chars ? 'character-020' then select ord-1 into firstn from jsonb_array_elements(chars) with ordinality q(v,ord) where v='"character-020"';end if;
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') and setup->>'mode'='team' then to_jsonb(case when teams->>a='A' then '机械猴子' else '帝汶家族' end) else c->'faction' end,'hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
 if rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('stage3',ml_private.stage3_initial(),'cardStack',jsonb_build_object('serial',0,'stack','[]'::jsonb));end if;
 if rulev in ('web-v0.1.7','web-v0.1.8','web-v0.1.9','web-v0.1.10','web-v0.1.11','web-v0.1.12','web-v0.1.13','web-v0.1.14','web-v0.1.15','web-v0.1.16','web-v0.1.17','web-v0.1.18','web-v0.1.19') then s:=s||jsonb_build_object('stage4',ml_private.stage4_initial(s->'players'));end if;
 if ml_private.p3d_enabled(s) then s:=ml_private.p3d_start(ml_private.p3c_start(s,firstn),firstn);end if;if ml_private.p3e_enabled(s) then s:=ml_private.p3e_start(s,firstn);end if;if ml_private.p3f_enabled(s) then s:=ml_private.p3f_start(s,firstn);end if;if ml_private.p3g_enabled(s) then s:=jsonb_set(s,'{stage3,g}',ml_private.p3g_initial_state());end if;s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 if ml_private.p3g_enabled(s) then return ml_private.p3g_initial(s,at);end if;s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
