 'draftReady',ready,'characterSkillsReady',ready,'stage3Ready',ready,'stage4Ready',ready,'cardDefinitions',76,'cardInstances',191,'classicRuleVersion','web-v0.1.19','potatoRulesReady',ready,'batchCReady',ready,'batchDReady',ready,'batchEReady',ready,'yinghaoRulesReady',ready,'p3CharactersReady',ready,'characterDefinitions',52,'batchFReady',ready,'batchGReady',ready,'batchHReady',ready,'engine','postgresql') from readiness $$;
